import{a as e}from"./jsx-runtime-Bzw2jH9X.js";var t=e({default:()=>n}),n=JSON.parse(`[{"id":"qx-b2-001","clusterId":"B","werkstueckRef":"B.17","stufe":1,"question":"Welche Antwort auf diese beiden Aussagen trifft den Kern, ohne das Gespräch ins Gegenteil kippen zu lassen?","options":["Der erste Satz ist richtig, denn Normen wie das Verbot, Menschen zu besitzen, gelten zeitlos, und für ein Urteil braucht es kein Verstehen.","Der erste Satz ersetzt das Verstehen durch ein heutiges Urteil, der zweite verbietet jedes Urteil. Beide Sätze sind verkürzt.","Der zweite Satz ist richtig, denn jedes Urteil über frühere Zeiten geht von heutigen Maßstäben aus und kann deshalb nicht belastbar sein.","Beide Sätze lassen sich nicht beurteilen, denn ohne gesicherte Quellen über die damaligen Menschen bleibt jede Aussage über sie Meinung."],"correctIndex":1,"explanation":"Der erste Satz begeht den Fehler des Präsentismus: Er misst Menschen früherer Zeiten an Normen und Wissen von heute und hält das für das ganze Bild. Damit bleibt unverstanden, in welchem Weltbild, mit welchem Wissen und mit welchen Handlungsmöglichkeiten sie lebten. Die Gegenposition schießt übers Ziel hinaus: Wer Verstehen verlangt, muss deshalb nicht auf Bewertung verzichten. Das zeigt der Fall Thomas Jefferson: Den Kontext zu beachten entschuldigt die Sklaverei nicht, ihn zu ignorieren verhindert aber das Verständnis der Widersprüche, mit denen er rang. Jefferson nannte die Sklaverei in seinen „Notes on the State of Virginia“ selbst einen „unablässigen Despotismus“ und hielt zugleich die Unterlegenheit Schwarzer „nur als Verdacht“ für möglich. Falsch wird es erst, wenn Verurteilung oder Verklärung das Verständnis ersetzen. Gute Prüffrage: Versuche ich gerade, diese Person aus ihrer eigenen Realität heraus zu verstehen, oder benutze ich sie nur als Leinwand für heutige Urteile? Dass manche Normen zeitlos gelten mögen, ersetzt das Verstehen nicht, und genau dieses Verstehen überspringt der erste Satz. Dass ein Urteil heutige Maßstäbe nutzt, macht es nicht unbegründet; es darf nur den Kontext nicht ausblenden. Und die Quellenlage ist zwar wichtig, aber nicht das Thema der beiden Sätze.","coreRule":"⚡ Verstehen und Urteilen schließen sich nicht aus. Falsch wird es, wenn das Urteil das Verständnis ersetzt.","quote":"Versuche ich gerade, diese Epoche/Person aus ihrer eigenen, komplexen Realität heraus zu verstehen?","quoteLabel":"Prüffrage:","beleg":"Werkstück B.17 (Kernidee; Kipppunkt)","status":"entwurf","scenario":"In einer Diskussion über historische Figuren sagt jemand: „Wer vor 250 Jahren Menschen als Besitz gehalten hat, war eben ein Verbrecher, und alle damaligen Zeitgenossen gleich mit. Da gibt es nichts zu verstehen.“ Eine andere Person entgegnet: „Das ist unfair, man muss jede Zeit an ihren eigenen Maßstäben messen. Urteilen darf man über die Vergangenheit gar nicht.“","kurz":"Der erste Satz setzt ein heutiges Urteil an die Stelle des Verstehens, der zweite verbietet jedes Urteil. Dabei schließen sich Verstehen und Bewerten nicht aus: Den Kontext zu beachten entschuldigt nichts, ihn zu ignorieren verbaut aber das Verständnis.","prueffrage":"Gab es vor 250 Jahren schon Menschen, die Sklaverei öffentlich als Unrecht bezeichneten, und wie reagierte ihre Umgebung darauf?","rueckmeldung":[{"option":0,"text":"Dass manche Normen zeitlos gelten mögen, ist ein ernstzunehmender Gedanke. Doch auch dann ersetzt ein Urteil das Verstehen nicht: Wie diese Menschen lebten, was sie wussten und was sie tun konnten, bleibt offen, und genau das überspringt der erste Satz."},{"option":2,"text":"Richtig ist, dass Urteile über die Vergangenheit heutige Maßstäbe nutzen. Daraus folgt aber nicht, dass sie unbelastbar wären. Ein Urteil kann begründet sein, wenn es den Kontext einbezieht; ein Verbot jedes Urteils schießt übers Ziel hinaus."},{"option":3,"text":"Gesicherte Quellen sind für Aussagen über die Vergangenheit wichtig, darum geht es in den beiden Sätzen aber gar nicht. Ihre Schwäche liegt im Schluss selbst: einmal Urteil statt Verstehen, einmal Urteilsverbot. Dass ohne Quellen alles bloße Meinung sei, trägt ebenfalls nicht."}],"familie":"aus-ihrer-lage-urteilen","fertigkeit":"F2","quellen":[{"typ":"url","kurz":"Jefferson, T. (1787): Notes on the State of Virginia, Query XVIII „Manners“ (Scholars' Lab, University of Virginia, Faksimile der Ausgaben 1784/1787)","oeffentlich":true,"url":"https://notes.scholarslab.org/milestones/manners.html","seite":"Query XVIII","abruf":"2026-10-12"},{"typ":"url","kurz":"Jefferson, T. (1787): Notes on the State of Virginia, Query XIV „Laws“ (Scholars' Lab, University of Virginia)","oeffentlich":true,"url":"https://notes.scholarslab.org/milestones/laws.html","seite":"Query XIV","abruf":"2026-10-12"},{"typ":"url","kurz":"Hunt, L. (2002): From the President: Against Presentism. Perspectives on History (American Historical Association)","oeffentlich":true,"url":"https://historians.org/perspectives-article/against-presentism-may-2002/","abruf":"2026-10-12"}],"thema":"Geschichte und Wissenschaft","pruefung":{"lauf":"quiz-audit-v3","modell":"claude-sonnet-5-5","datum":"2026-10-13","urteil":"korrigieren","pruefsumme":"e238028ee41dac9a"}},{"id":"qx-b2-002","clusterId":"B","werkstueckRef":"B.17","stufe":2,"question":"Welche Entgegnung prüft die Schwärmerei von der „guten alten Zeit“ in der Sache, ohne selbst die Vorfahren abzuwerten?","scenario":"Beim Abendessen schwärmt ein Freund nach einem Historienfilm, der um 1800 spielt: „Früher waren die Menschen naturverbundener, hatten stärkere Gemeinschaften und keinen Stress. Wir sollten wieder so leben.“","options":["Man stellt der Schwärmerei überprüfbare Lebensdaten gegenüber, etwa dass die Lebenserwartung um 1800 in keiner Weltregion über 40 Jahren lag, auch wegen früh sterbender Kinder.","Man fragt ihn, ob er selbst auf Zahnmedizin, Heizung und Kühlschrank verzichten würde, und führt damit vor, dass er seine eigene Forderung nach einem Leben wie damals nicht ernst meinen kann.","Man erklärt die Schwärmerei mit Nostalgie, die in jeder Epoche vorkam, und folgert daraus, dass seine Aussagen über das Leben um 1800 nicht stimmen können.","Man hält ihm vor, dass er mit seiner Sehnsucht nach früher die Errungenschaften der Gegenwart geringschätzt, und verlangt von ihm, dafür mehr Dankbarkeit zu zeigen."],"correctIndex":0,"explanation":"Die Schwärmerei pickt Ästhetisches heraus (schöne Kleider, keine Smartphones) und blendet Hunger, Krankheiten, Kindersterblichkeit, erdrückende soziale Kontrolle und fehlende Rechte aus. Der stärkste Einwand setzt dort an, wo sich etwas überprüfen lässt: Lebensdaten sind Tatsachen, kein Werturteil, und sie stellen das idealisierte Bild auf die Probe. Gegen Verklärung hilft der Blick auf den ganzen Alltag der Epoche, ohne die Menschen von damals herabzusetzen. Die Frage, ob er selbst verzichten würde, trifft die Person und nicht das Bild der Zeit. Dass Sehnsucht nach früher in jeder Epoche vorkommt, erklärt ihre Herkunft, aber nicht, ob das Bild stimmt. Und der Vorwurf der Undankbarkeit ersetzt die Prüfung durch einen Appell.","coreRule":"⚡ Gegen die Verklärung der Vergangenheit helfen überprüfbare Daten über den ganzen Alltag der Epoche, nicht ihre Verurteilung.","beleg":"Werkstück B.17, Abschnitt „Die zweite, subtilere Falle: Die naive Romantisierung“ und Abschnitt „Bei Esoterik & New Age“; Fn. gl-b-lebenserwartung (Dattani u. a. 2023, Our World in Data)","status":"entwurf","kurz":"Lebensdaten sind überprüfbar und stellen das idealisierte Bild auf die Probe, ohne die Menschen von damals herabzusetzen. Der naheliegende Fehler ist, stattdessen die Person oder die Herkunft ihrer Sehnsucht anzugreifen, statt das Bild selbst zu prüfen.","prueffrage":"Welche Seiten des damaligen Lebens zeigt ein Historienfilm, und welche lässt er meistens weg?","rueckmeldung":[{"option":1,"text":"Die Frage nach dem eigenen Verzicht wirkt schlagfertig, trifft aber den Freund und nicht sein Bild von damals. Ob er verzichten würde, sagt nichts darüber, ob Gemeinschaft, Stress und Alltag um 1800 so waren, wie er sie schildert."},{"option":2,"text":"Sehnsucht nach früher gab es tatsächlich in jeder Epoche, das erklärt, woher die Schwärmerei kommt. Ob seine Aussagen stimmen, folgt daraus nicht: Auch ein nostalgisch gefärbtes Bild kann einzelne zutreffende Züge haben und muss an Tatsachen geprüft werden."},{"option":3,"text":"Gegenwärtige Errungenschaften sind real, doch der Vorwurf der Undankbarkeit ist ein Appell und keine Prüfung. Er sagt nichts darüber, ob das Leben um 1800 naturverbunden, gemeinschaftlich und stressfrei war, und verlangt vom Freund nur ein anderes Gefühl."}],"familie":"aus-ihrer-lage-urteilen","fertigkeit":"F2","quellen":[{"typ":"url","kurz":"Dattani, S. u. a. (2023): Life Expectancy. Our World in Data","oeffentlich":true,"url":"https://ourworldindata.org/life-expectancy","abruf":"2026-10-12"},{"typ":"url","kurz":"Hunt, L. (2002): From the President: Against Presentism. Perspectives on History (AHA)","oeffentlich":true,"url":"https://historians.org/perspectives-article/against-presentism-may-2002/","abruf":"2026-10-12"},{"typ":"literatur","kurz":"Clauss, M. (2009): Ritter und Raufbolde. Vom Krieg im Mittelalter. Darmstadt: Primus","oeffentlich":false,"seite":"S. 7–8, 75–77"}],"thema":"Geschichte und Wissenschaft","pruefung":{"lauf":"quiz-audit-v3","modell":"claude-sonnet-5-5","datum":"2026-10-13","urteil":"ok","pruefsumme":"145a4b59f2e570e6"}},{"id":"qx-b2-003","clusterId":"B","werkstueckRef":"B.17","stufe":3,"question":"Du hörst in einer Diskussion: „Thomas Jefferson hatte Sklaven – also war er ein monströser Heuchler.“ Jemand kontert: „Damals dachten eben alle so, also darf man ihn nicht verurteilen.“ Dann kommt der Hinweis, dass Jefferson die Sklaverei in einem eigenen Buch einen „unablässigen Despotismus“ nannte und schrieb, er zittere um sein Land, wenn er bedenke, dass Gott gerecht sei – im selben Buch äußerte er „nur als Verdacht“, Schwarze seien Weißen an Körper und Geist unterlegen. Was folgt daraus für das Argument „Damals dachten alle so“?","options":["Der Kontext verbietet jede Bewertung, weil Menschen einer fremden Epoche nur an den Maßstäben ihrer eigenen Zeit gemessen werden dürfen.","Der Kontext erklärt, aber entschuldigt nicht: Jefferson sah den Widerspruch selbst, und diesen zu verstehen bringt mehr als ein Etikett.","Der Kontext entlastet Jefferson weitgehend, weil Sklaverei damals als natürliche Ordnung galt und er sie nur kritisch kommentierte.","Der Kontext ist wertlos, weil es in jeder Zeit Menschen gab, die anders dachten als die Mehrheit, und an ihnen wird jede Figur gemessen."],"correctIndex":1,"explanation":"Beide Kurzschlüsse greifen zu kurz: weder „monströser Heuchler“ noch „Kind seiner Zeit, also unschuldig“. Dass alle gleich dachten, trifft nicht zu: Jefferson nannte die Sklaverei selbst einen „unablässigen Despotismus“, äußerte im selben Buch aber zugleich „nur als Verdacht“, Schwarze seien Weißen an Körper und Geist unterlegen. Den Widerspruch sah er also selbst. Das entschuldigt die Sklaverei nicht, aber es zu ignorieren, verhindert das Verständnis der tiefen Widersprüche, mit denen historische Akteure rangen.","coreRule":"⚡ Kontext ist eine Erklärung, kein Freispruch – und ohne ihn bleibt das Urteil blind.","beleg":"Werkstück B.17 (Anwendung: Bewertung historischer Figuren; Jefferson)","status":"freigegeben","freigabe":{"datum":"2026-10-13","pruefsumme":"4df819394debbbd9","vermerk":"Prüfpult"},"scenario":"","kurz":"Dass alle so dachten, stimmt hier nicht: Jefferson nannte die Sklaverei selbst „unablässigen Despotismus“ und äußerte zugleich den „Verdacht“, Schwarze seien unterlegen. Er sah den Widerspruch also selbst. Das entschuldigt nichts, erklärt aber mehr als ein Etikett.","prueffrage":"Was hat Jefferson selbst über die Sklaverei geschrieben, und deckt sich das mit der Behauptung, alle hätten damals gleich gedacht?","rueckmeldung":[{"option":0,"text":"Kontext gehört zum Verstehen einer Person tatsächlich dazu. Ein Bewertungsverbot folgt daraus aber nicht, zumal Jefferson die Sklaverei selbst „Despotismus“ nannte und sich so an seinen eigenen Maßstäben messen lassen muss."},{"option":2,"text":"Die Sklaverei war damals weit verbreitet, das stimmt. Dass sie allgemein als natürliche Ordnung galt, passt aber nicht zu Jeffersons eigenen Worten. Kritische Kommentare entlasten ihn auch nicht, sie zeigen eher, dass er den Widerspruch kannte."},{"option":3,"text":"Dass es auch damals Menschen gab, die anders dachten, trifft zu und widerlegt „alle dachten so“. Daraus folgt aber nicht, dass Kontext wertlos wäre. Er hilft zu verstehen, wie Einsicht und Handeln so weit auseinandergehen konnten."}],"familie":"aus-ihrer-lage-urteilen","fertigkeit":"F2","quellen":[{"typ":"url","kurz":"Jefferson, T. (1787): Notes on the State of Virginia, Query XVIII „Manners“ (Scholars' Lab, UVA)","oeffentlich":true,"url":"https://notes.scholarslab.org/milestones/manners.html","seite":"Query XVIII","abruf":"2026-10-12"},{"typ":"url","kurz":"Jefferson, T. (1787): Notes on the State of Virginia, Query XIV „Laws“ (Scholars' Lab, UVA)","oeffentlich":true,"url":"https://notes.scholarslab.org/milestones/laws.html","seite":"Query XIV","abruf":"2026-10-12"},{"typ":"url","kurz":"Hunt, L. (2002): Against Presentism. Perspectives on History (AHA)","oeffentlich":true,"url":"https://historians.org/perspectives-article/against-presentism-may-2002/","abruf":"2026-10-12"}],"thema":"Geschichte und Wissenschaft","pruefung":{"lauf":"quiz-audit-v3","modell":"claude-sonnet-5-5","datum":"2026-10-13","urteil":"ok","pruefsumme":"4df819394debbbd9"}},{"id":"qx-b2-004","clusterId":"B","werkstueckRef":"B.17","stufe":4,"question":"Welche Rückfrage prüft die Behauptung am besten, ohne sie sofort zu verwerfen oder zu übernehmen?","scenario":"Ein Politiker beschwört „die guten alten 50er“ und nennt heutige gesellschaftliche Veränderungen „Verfall und Dekadenz“.","options":["Welche Ausbildung und Berufserfahrung hat der Politiker, und versteht er genug von Geschichte, um die 50er Jahre überhaupt beurteilen zu können?","Seit wann wird der Begriff „Dekadenz“ in politischen Reden gebraucht, und wie hat sich seine Bedeutung seit seiner Entstehung bis heute gewandelt?","Wie reagiert der Politiker, wenn man ihn auf die Schattenseiten der 50er anspricht, und bleibt er auch dann bei seiner Aussage, wenn man ihm Gegenbeispiele nennt?","Wie sahen Alltag, Rechte und Gesundheit damals tatsächlich aus, und wozu wird dieses Bild heute gebraucht, etwa um Veränderungen als Verfall darzustellen?"],"correctIndex":3,"explanation":"Eine „goldene“ Vergangenheit ist oft ein idealisiertes Zerrbild: Man pickt die angenehmen Seiten heraus (schöne Kleider, keine Smartphones) und blendet den Rest aus, etwa hohe Kindersterblichkeit, fehlende Rechte oder soziale Kontrolle. Außerdem dient ein solches Bild häufig dazu, gegenwärtige Veränderungen, zum Beispiel mehr Rechte für Minderheiten, als Verfall darzustellen. Eine gute Prüfung fragt deshalb zweierlei: Wie sah der tatsächliche Alltag der Epoche aus, und welche Funktion hat das Bild in der heutigen Debatte? So wird die Behauptung weder pauschal abgetan noch übernommen. Die Ausbildung des Politikers sagt nicht, ob sein Bild der Zeit stimmt. Die Geschichte des Wortes „Dekadenz“ klärt nicht, wie die 50er tatsächlich waren. Und seine Reaktion auf Einwände zeigt etwas über ihn, aber nichts über die Zeit.","coreRule":"⚡ Prüfe bei jeder „guten alten Zeit“, wie der Alltag damals tatsächlich aussah und wofür das Bild heute gebraucht wird.","beleg":"Werkstück B.17 (Anwendung: Verschwörungsmythen, rechts-konservative Variante; Red Flags)","status":"entwurf","kurz":"Ein „goldenes“ Früher blendet oft aus, was unangenehm war, und dient dazu, heutige Veränderungen als Verfall hinzustellen. Wer beides prüft, den tatsächlichen Alltag damals und die Funktion des Bildes heute, weist die Aussage weder pauschal ab noch übernimmt er sie.","prueffrage":"Für wen waren die 50er „gut“, und wer hätte damals wohl ganz anders darüber gesprochen?","rueckmeldung":[{"option":0,"text":"Fachkenntnis kann durchaus ein Anlass sein, genauer hinzusehen. Ob das Bild der 50er stimmt, sagt die Ausbildung aber nicht: Auch Fachleute können idealisieren, und Laien können recht haben. Das lässt sich nur am Alltag der Zeit selbst prüfen."},{"option":1,"text":"Begriffe wie „Dekadenz“ sind oft aufgeladen, und ihre Geschichte kann für die Rhetorik interessant sein. Sie klärt aber nicht, wie die 50er tatsächlich waren, und auch nicht, wozu das Bild heute eingesetzt wird. Die Behauptung selbst bleibt dabei ungeprüft."},{"option":2,"text":"Wie jemand auf Einwände reagiert, zeigt etwas über seine Gesprächsweise. Es sagt aber nichts darüber, wie die Zeit tatsächlich war, und fragt auch nicht, wozu das Bild gebraucht wird. Die Aussage selbst wird so nicht geprüft."}],"familie":"aus-ihrer-lage-urteilen","fertigkeit":"F2","quellen":[{"typ":"url","kurz":"Dattani, S. u. a. (2023): Life Expectancy. Our World in Data","oeffentlich":true,"url":"https://ourworldindata.org/life-expectancy","abruf":"2026-10-12"},{"typ":"literatur","kurz":"Clauss, M. (2009): Ritter und Raufbolde. Vom Krieg im Mittelalter. Darmstadt: Primus","oeffentlich":false,"seite":"S. 7–8, 75–77"}],"thema":"Zusammenleben","pruefung":{"lauf":"quiz-audit-v3","modell":"claude-sonnet-5-5","datum":"2026-10-13","urteil":"ok","pruefsumme":"44f098ec97b455e6"}},{"id":"qx-b2-005","clusterId":"B","werkstueckRef":"B.18","stufe":1,"question":"Was ist an dieser Begründung für das Weitermachen fehlerhaft?","options":["Sie schließt aus dem bisherigen Ausbleiben eines Schadens auf Sicherheit und deutet das Schweigen der anderen als Zustimmung, obwohl es auch Selbstzensur sein kann.","Sie begeht den Fehlschluss versunkener Kosten, indem sie am Vorhaben festhält, nur weil schon viel Zeit und Geld hineingesteckt wurden, statt neu zu bewerten.","Sie begeht einen Zirkelschluss, denn sie setzt voraus, dass die Konstruktion unbedenklich ist, um dann zu schließen, dass die Konstruktion unbedenklich ist.","Sie stellt eine falsche Alternative auf, als gäbe es nur Weitermachen oder Abbrechen, obwohl sich die Konstruktion auch gezielt prüfen und nachbessern ließe."],"correctIndex":0,"explanation":"Zwei Schlüsse tragen hier nicht. Erstens: Dass dreimal nichts passiert ist, zeigt nicht, dass das Risiko klein ist. Ein Schaden, der bisher ausblieb, kann beim nächsten Mal eintreten. Genau so wurde bei der Challenger über Jahre der Dichtungsschaden als „annehmbares Risiko“ verbucht, weil Flug um Flug gut ging, bis der Start bei großer Kälte zur Katastrophe führte. Zweitens: Wer Bedenken ausdrücklich unerwünscht macht, darf Schweigen nicht als Zustimmung lesen. Ausbleibender Widerspruch kann auch Selbstzensur aus Angst vor Ausgrenzung sein. Hier wird aus einem individuellen Impuls („die anderen sehen es offenbar auch so“) über sozialen Druck ein Gruppendenken, bei dem Einigkeit wichtiger wird als eine gute Entscheidung. Der Gruppendruck erklärt solche Entscheidungen allerdings nur zum Teil; hinzu kommt die schleichende Normalisierung der Abweichung. Kritik gehört deshalb nicht unterdrückt, sondern gezielt eingeholt. Von versunkenen Kosten ist im Szenario keine Rede; die Leiterin begründet nichts mit bereits Investiertem. Ein Zirkelschluss liegt auch nicht vor, denn sie nennt einen Grund, der nur nicht trägt (es ist bisher gutgegangen). Und sie schließt ein Nachbessern nicht ausdrücklich aus; das Problem ist, dass die Warnzeichen nicht geprüft werden.","coreRule":"⚡ Wer „bisher ging es gut“ als Beweis nimmt und Schweigen als Zustimmung liest, übersieht Risiko und Selbstzensur.","beleg":"Werkstück B.18 (Kernidee; Analyse: Die drei Stufen; Abschnitt „Die Nacht erzählt allerdings nur das Ende“; Fn. gl-b-normalisierung)","status":"entwurf","scenario":"Ein Projektteam hat dreimal in Folge Warnzeichen für ein Qualitätsproblem bemerkt, jedes Mal ohne sichtbaren Schaden. In der Sitzung sagt die Leiterin: „Bisher ist immer alles gut gegangen, also verkraftet die Konstruktion das. Wenn jemand Bedenken hat, soll er sie bitte für sich behalten, wir sind uns doch alle einig.“","kurz":"Dass dreimal nichts passiert ist, zeigt nicht, dass das Risiko klein ist: Ein bisher ausgebliebener Schaden kann beim nächsten Mal eintreten. Und wer Bedenken unerwünscht macht, darf Schweigen nicht als Zustimmung lesen, es kann auch Selbstzensur sein.","prueffrage":"Was ist aus den drei Warnzeichen geworden, und wer im Team hat in der Sitzung überhaupt etwas dazu gesagt?","rueckmeldung":[{"option":1,"text":"Festhalten am Bisherigen wirkt ähnlich, als wäre schon zu viel investiert, um umzukehren. Davon ist hier aber keine Rede: Die Leiterin begründet ihr Weitermachen mit dem ausgebliebenen Schaden, nicht mit bereits eingesetzten Mitteln."},{"option":2,"text":"Ein Zirkelschluss liegt nicht vor, denn die Leiterin nennt einen eigenen Grund: Bisher ist alles gut gegangen. Er ist von der Schlussfolgerung getrennt, er trägt nur nicht, weil ein ausgebliebener Schaden nichts über das künftige Risiko sagt."},{"option":3,"text":"Gezielt prüfen und nachbessern wäre tatsächlich ein sinnvoller Weg. Die Leiterin schließt ihn aber nicht ausdrücklich aus, sie stellt keine Entweder-oder-Wahl auf. Ihr Fehler liegt woanders: Die Warnzeichen werden gar nicht geprüft."}],"familie":"schweigen-ist-keine-zustimmung","fertigkeit":"F2","quellen":[{"typ":"url","kurz":"Columbia Accident Investigation Board (2003): Report, Bd. 1, Kap. 8 „History As Cause: Columbia and Challenger“","oeffentlich":true,"url":"http://s3.amazonaws.com/akamai.netstorage/anon.nasa-global/CAIB/CAIB_lowres_chapter8.pdf","seite":"S. 196","abruf":"2026-10-12"},{"typ":"url","kurz":"Rogers Commission (1986): Report, Bd. 1, Kap. V „The Contributing Cause of the Accident“ (NASA)","oeffentlich":true,"url":"https://www.nasa.gov/history/rogersrep/v1ch5.htm","abruf":"2026-10-12"},{"typ":"doi","kurz":"Esser, J. K.; Lindoerfer, J. S. (1989): Groupthink and the space shuttle Challenger accident. Journal of Behavioral Decision Making 2(3)","oeffentlich":false,"doi":"10.1002/bdm.3960020304","seite":"S. 173"}],"thema":"Zusammenleben","pruefung":{"lauf":"quiz-audit-v3","modell":"claude-sonnet-5-5","datum":"2026-10-13","urteil":"ok","pruefsumme":"bb478835f75d05f6"}},{"id":"qx-b2-006","clusterId":"B","werkstueckRef":"B.18","stufe":2,"question":"Was ist an dieser Schlussfolgerung der Kollegin fehlerhaft?","scenario":"In der Teamsitzung stimmt dir eine Zahl nicht. Alle nicken, du schweigst – nicht weil du glaubst, die anderen wüssten es besser, sondern weil du nicht als Spielverderber dastehen willst. Später sagt dir eine Kollegin: „Du hast das ja einfach mitgetragen, also warst du überzeugt.“","options":["Sie hält dein Schweigen für Zustimmung, obwohl es auch aus Furcht vor sozialer Ablehnung entstehen kann und dann nichts über deine Überzeugung sagt.","Sie schließt aus der Zustimmung der Mehrheit auf die Richtigkeit der Zahl, obwohl die Zahl der Zustimmenden nichts über Wahrheit aussagt.","Sie verallgemeinert aus einem einzelnen Vorfall auf dein gesamtes Verhalten in Teams, obwohl eine einzige Sitzung dafür nicht ausreicht.","Sie bleibt an der zuerst genannten Zahl wie an einem Anker hängen, obwohl solche Anker das Urteil über die eigentliche Sache verzerren können."],"correctIndex":0,"explanation":"Äußeres Verhalten und innere Überzeugung fallen nicht zusammen. Es gibt zwei Gründe, sich einer Gruppe anzuschließen: Man hält die anderen für wissender (informativer Einfluss), oder man fürchtet Ausgrenzung, Lächerlichkeit oder Bestrafung (normativer Einfluss). Dein Schweigen entspringt dem zweiten Grund, und dann sagt das Nicken der Gruppe nichts darüber, was die Einzelnen wirklich denken. Genau so entsteht in eng verbundenen Gruppen die Illusion der Einstimmigkeit: Schweigen wird fälschlich als Zustimmung gedeutet, während Einzelne ihre Zweifel zurückhalten (Selbstzensur). In Asch-Experimenten gaben rund drei Viertel der Versuchspersonen mindestens einmal öffentlich eine offensichtlich falsche Antwort, nur weil alle anderen es taten. Wer Einigkeit nur an äußerer Zustimmung misst, kann sich täuschen. Eine gute Frage wäre: „Welche Argumente haben wir noch nicht gehört oder trauen uns nicht auszusprechen?“","coreRule":"⚡ Schweigen ist kein Beleg für Zustimmung: Es kann auch aus Angst vor dem Gruppenurteil entstehen.","beleg":"Werkstück B.18 (Stufe 2; Symptom 6 Selbstzensur)","status":"entwurf","kurz":"Nicken und Schweigen zeigen nur das Verhalten, nicht die Überzeugung. Wer aus Angst vor Ablehnung mitgeht, stimmt innerlich nicht zu. Der Fehler: äußere Zustimmung gilt als innere, obwohl zwei Gründe zum selben Schweigen führen können.","prueffrage":"Wie viele der Nickenden hatten vielleicht eigene Bedenken, und woran hätte die Kollegin das von außen erkennen können?","rueckmeldung":[{"option":1,"text":"Dass viele Zustimmende nichts über die Wahrheit einer Zahl beweisen, stimmt. Die Kollegin behauptet aber nicht, die Zahl sei richtig, sondern, dass du überzeugt warst. Ihr Fehler liegt in der Deutung deines Schweigens."},{"option":2,"text":"Von einem allgemeinen Verhaltensmuster spricht die Kollegin nicht, sie deutet nur diese eine Sitzung. Dass einzelne Vorfälle nicht für große Schlüsse reichen, ist richtig, trifft hier aber nicht den Kern. Falsch ist, was sie aus dem Schweigen liest."},{"option":3,"text":"Anker können Urteile tatsächlich verzerren. Im Szenario fehlt aber ein Anker: Es gibt keine zuerst genannte Zahl, die das Urteil lenkt, und die Kollegin urteilt über dein Schweigen, nicht über die Zahl."}],"familie":"schweigen-ist-keine-zustimmung","fertigkeit":"F2","quellen":[{"typ":"url","kurz":"Spielman, R. M.; Jenkins, W. J.; Lovett, M. D.: Psychology 2e, Kap. 12.4 „Conformity, Compliance, and Obedience“ (OpenStax)","oeffentlich":true,"url":"https://openstax.org/books/psychology-2e/pages/12-4-conformity-compliance-and-obedience","abruf":"2026-10-12"},{"typ":"doi","kurz":"Asch, S. E. (1956): Studies of Independence and Conformity: I. A Minority of One Against a Unanimous Majority. Psychological Monographs 70(9)","oeffentlich":false,"doi":"10.1037/h0093718","seite":"S. 10–11"},{"typ":"doi","kurz":"Deutsch, M.; Gerard, H. B. (1955): A Study of Normative and Informational Social Influences upon Individual Judgment. Journal of Abnormal and Social Psychology 51(3)","oeffentlich":false,"doi":"10.1037/h0046408","seite":"S. 629–633"}],"thema":"Zusammenleben","pruefung":{"lauf":"quiz-audit-v3","modell":"claude-sonnet-5-5","datum":"2026-10-13","urteil":"korrigieren","pruefsumme":"8d6ef04b164415dc"}},{"id":"qx-b2-007","clusterId":"B","werkstueckRef":"B.18","stufe":3,"question":"Ein Kommentator sagt: „Der Gruppendruck in der Nacht davor erklärt alles.“ Was spricht dagegen, diese Erklärung als vollständig zu akzeptieren?","options":["Die Dichtungsschäden waren schon bei früheren Flügen aufgetreten und galten als annehmbares Risiko, weil die Flüge gut gegangen waren.","Die oberste Startleitung hatte die Einwände der Ingenieure gehört und sie bewusst überstimmt, um den Zeitplan einzuhalten.","Die Dichtungen waren vor jener Nacht nie beschädigt worden, sodass niemand im Team das Risiko im Voraus erkennen konnte.","Die Ingenieure hatten ihre Bedenken nie ausgesprochen, sodass es in jener Nacht gar keinen Druck auf das Management gab."],"correctIndex":0,"explanation":"Eine einzelne dramatische Szene ist eine verlockende Ursache, aber selten die ganze. Hier hatten die Ingenieure dringend abgeraten, ihr Management revidierte die Warnung, und die oberste Startleitung erfuhr nach eigener Aussage nichts davon. Dahinter steht eine längere Vorgeschichte: Schon seit den ersten Flügen waren Dichtringe immer wieder angegriffen worden, ein Jahr zuvor nach Kältenächten besonders stark. Weil die Flüge trotzdem gut gingen, galt jeder neue Schaden als Beweis, dass die Konstruktion ihn verkraftet. Dieses Muster wird „Normalisierung der Abweichung“ genannt; die Untersuchung nach dem Absturz der Columbia 2003 fand es auch beim Isolierschaum wieder. Eine gute Ursachenanalyse fragt deshalb nicht nur, wer in der entscheidenden Nacht was sagte, sondern auch, welche Gewöhnung diese Entscheidung über Jahre vorbereitet hat.","coreRule":"⚡ Wer ein Unglück mit der letzten Entscheidung erklärt, übersieht oft die Gewöhnung an Warnzeichen, die Jahre vorher begann.","beleg":"Werkstück B.18; Fn. gl-b-challenger (Rogers Commission 1986, Bd. 1, Kap. V; Vaughan 1996); Fn. gl-b-normalisierung (CAIB 2003, Bd. 1, Kap. 8, S. 196–197)","status":"entwurf","scenario":"Vor einem Raumfähren-Start bei Kälte rieten Ingenieure des Herstellers der Feststoffraketen dringend ab: Die Dichtungen waren bei Kälte nicht für einen sicheren Start zertifiziert. Ihr Management gab am Vorabend dennoch die Freigabe, und die oberste Startleitung sagte später aus, von den Einwänden nichts gewusst zu haben. Schon bei früheren Flügen waren Dichtringe angegriffen worden, doch weil die Flüge gut gegangen waren, wurde der Schaden als „annehmbares Risiko“ geführt. Der Start endete in der Katastrophe.","kurz":"Die Nacht der Entscheidung ist nur der letzte Schritt: Schon bei früheren Flügen waren Dichtringe angegriffen worden und galten als annehmbar, weil es gut ausging. Wer nur die dramatische Szene betrachtet, übersieht diese Gewöhnung.","prueffrage":"Wer wusste in jener Nacht was über die Dichtungen, und seit wann war das bekannt?","rueckmeldung":[{"option":1,"text":"Dass jemand Einwände bewusst überging, klingt nach einer klaren Schuldfrage. Die oberste Startleitung sagte aber aus, von den Einwänden nichts gewusst zu haben; überstimmt wurde die Warnung im Management der Firma."},{"option":2,"text":"Wäre vorher nie etwas passiert, wäre die Katastrophe tatsächlich schwer vorherzusehen gewesen. Doch Dichtringe waren schon bei früheren Flügen angegriffen worden, und die Ingenieure warnten. Das Risiko war erkennbar, galt aber als annehmbar."},{"option":3,"text":"Dass Gruppendruck nicht alles erklärt, heißt nicht, dass es ihn nicht gab: Die Ingenieure hatten dringend abgeraten, und das Management nahm die Warnung zurück. Der Druck gehört zur Erklärung, nur reicht er allein nicht aus."}],"familie":"schweigen-ist-keine-zustimmung","fertigkeit":"F2","quellen":[{"typ":"url","kurz":"Rogers Commission (1986): Report, Bd. 1, Kap. V (NASA)","oeffentlich":true,"url":"https://www.nasa.gov/history/rogersrep/v1ch5.htm","abruf":"2026-10-12"},{"typ":"url","kurz":"Columbia Accident Investigation Board (2003): Report, Bd. 1, Kap. 8 „History As Cause: Columbia and Challenger“","oeffentlich":true,"url":"http://s3.amazonaws.com/akamai.netstorage/anon.nasa-global/CAIB/CAIB_lowres_chapter8.pdf","seite":"S. 196–197","abruf":"2026-10-12"},{"typ":"literatur","kurz":"Vaughan, D. (1996): The Challenger Launch Decision. Chicago: University of Chicago Press","oeffentlich":false}],"thema":"Technik und KI","pruefung":{"lauf":"quiz-audit-v3","modell":"claude-sonnet-5-5","datum":"2026-10-13","urteil":"korrigieren","pruefsumme":"c62f6425dcd57c2b"}},{"id":"qx-b2-008","clusterId":"B","werkstueckRef":"B.18","stufe":4,"question":"Was ist an dieser Schlussfolgerung der Vorsitzenden am ehesten fragwürdig?","scenario":"Ein Vorstand will Gruppendenken vermeiden. In jeder Sitzung muss reihum ein Mitglied die Rolle des „Advocatus Diaboli“ spielen und gegen den Beschlussvorschlag argumentieren. Nach einem halben Jahr fällt auf: Die Beschlüsse fallen weiterhin sehr schnell und fast immer einstimmig. Der Teufelsanwalt bringt regelmäßig Einwände vor, die nach kurzer Diskussion allen als „bekannt“ gelten. Die Vorsitzende deutet das als Beweis, dass die Gruppe gründlich prüft.","options":["Dass die Einwände bei einer zugewiesenen Rolle womöglich nur gespielt sind und deshalb leicht abgehakt werden, ohne dass ein Mitglied tatsächlich widerspricht.","Dass ein Gremium überhaupt Einwände sammelt, weil jede Kritik den Entscheidungsprozess verlangsamt und die Gruppe handlungsunfähig macht.","Dass die Rolle reihum vergeben wird, weil nur Mitglieder mit ausgeprägtem Fachwissen glaubwürdige Gegenargumente liefern können.","Dass einstimmige Beschlüsse zustande kommen, weil Einstimmigkeit in einer Gruppe grundsätzlich auf mangelnde Sorgfalt hindeutet."],"correctIndex":0,"explanation":"Ein Einwand, den jemand pflichtgemäß vorbringt, weil er an der Reihe ist, zeigt noch nicht, dass die Gruppe Widerspruch ernst nimmt. Das Ritual kann den Eindruck gründlicher Prüfung erwecken, ohne dass echter Widerspruch stattfindet. Dass jeder Einwand schnell als „bekannt“ gilt und die Beschlüsse einstimmig bleiben, ist eher ein Warnsignal. Echter, selbst geäußerter Widerspruch ist dagegen nicht an eine Rolle gebunden und wird eher als ernsthafte Alternative geprüft. Laut Experimenten war von sich aus geäußerter Widerspruch jeder geprüften Form des bestellten Teufelsanwalts überlegen. Das heißt nicht, dass die Rolle wertlos wäre, wohl aber, dass sie echten Widerspruch nicht ersetzt. Einstimmigkeit allein beweist weder Sorgfalt noch Nachlässigkeit; entscheidend ist, ob abweichende Meinungen real geäußert und ernsthaft geprüft werden können.","coreRule":"⚡ Ein bestellter Widerspruch ersetzt nicht die Kultur, in der echter Widerspruch erwünscht ist.","beleg":"Werkstück B.18 (Verbindungen: Advocatus Diaboli)","status":"entwurf","kurz":"Ein Einwand, den jemand nur vorbringt, weil er an der Reihe ist, zeigt nicht, dass Widerspruch ernst genommen wird. Dass jeder Einwand schnell als „bekannt“ gilt und alles einstimmig bleibt, ist eher ein Warnsignal als ein Beleg für Gründlichkeit.","prueffrage":"Wie oft hat in diesem halben Jahr ein Einwand einen Beschluss verändert, und wie lange wurde jeweils darüber gesprochen?","rueckmeldung":[{"option":1,"text":"Einwände kosten tatsächlich Zeit, deshalb wirkt das plausibel. Fragwürdig ist aber nicht, dass Einwände gesammelt werden, sondern wie die Vorsitzende deren Auftreten deutet. Kritik muss ein Gremium nicht lähmen."},{"option":2,"text":"Fachwissen hilft, überzeugende Gegenargumente zu finden. Um die Qualität der Argumente oder die Reihenfolge geht es hier aber nicht. Fragwürdig ist, dass ein pflichtgemäß vorgebrachter Einwand als Beleg für echte Prüfung gilt."},{"option":3,"text":"Anhaltende Einstimmigkeit kann tatsächlich ein Warnsignal sein. Daraus folgt aber keine Regel: Einstimmigkeit beweist weder Sorgfalt noch Nachlässigkeit. Fragwürdig ist, dass ein Einwand aus der zugewiesenen Rolle als echter Widerspruch gilt."}],"familie":"schweigen-ist-keine-zustimmung","fertigkeit":"F2","quellen":[{"typ":"doi","kurz":"Nemeth, C.; Brown, K.; Rogers, J. (2001): Devil's advocate versus authentic dissent: stimulating quantity and quality. European Journal of Social Psychology 31(6), 707–720","oeffentlich":false,"doi":"10.1002/ejsp.58","seite":"S. 707, 713–717"},{"typ":"url","kurz":"Behavioral Scientist (2018): Stop Playing Devil's Advocate, and Other Advice for Better Decision Making (Interview mit Charlan Nemeth)","oeffentlich":true,"url":"https://behavioralscientist.org/stop-playing-devils-advocate-and-other-advice-for-better-decision-making/","abruf":"2026-10-12"}],"thema":"Zusammenleben","pruefung":{"lauf":"quiz-audit-v3","modell":"claude-sonnet-5-5","datum":"2026-10-13","urteil":"korrigieren","pruefsumme":"46aad42396a1f93e"}},{"id":"qx-b2-009","clusterId":"B","werkstueckRef":"B.19","stufe":2,"question":"Welche Frage prüft die Werbebehauptung am besten?","scenario":"Eine Broschüre für ein Nahrungsergänzungsmittel wirbt: „Studie belegt – zwei Gesundheitswerte verbessert!“ Im Kleingedruckten steht, dass die Studie insgesamt 50 verschiedene Gesundheitswerte erfasst hat. Über die übrigen 48 Werte schweigt die Broschüre.","options":["Wurde vor der Studie festgelegt, welche Werte als Erfolgskriterium gelten sollten, und wie sahen die übrigen gemessenen Werte aus?","Wurde die Studie in einer Fachzeitschrift veröffentlicht, und wie oft wurde sie seither von anderen Forschenden zitiert?","Wie lange dauerte die Studie, und hielt die Verbesserung auch an, nachdem die Teilnehmer das Mittel nicht mehr einnahmen?","Wie teuer ist das Mittel im Vergleich zu ähnlichen Präparaten, und lohnt sich der Kauf aus Sicht der Kunden wirklich?"],"correctIndex":0,"explanation":"Wer 50 Werte misst, bekommt allein durch Zufall bei einigen davon eine scheinbar „signifikante“ Veränderung, ganz ohne jede Wirkung des Mittels. Entscheidend ist deshalb, ob die zwei Werte schon vor der Messung als Ziel festgelegt waren oder ob man sie erst im Nachhinein aus den Ergebnissen herausgepickt hat. Das ist, als würde man erst auf die Scheunenwand schießen und dann die Zielscheibe um die dichtesten Einschusslöcher malen. Und nur wenn man die übrigen 48 Werte kennt, lässt sich einschätzen, ob die zwei Treffer ein Volltreffer oder ein Zufallscluster sind. Ob die Studie in einer Fachzeitschrift erschien und oft zitiert wurde, sagt nicht, ob aus 50 Werten die passenden zwei herausgesucht wurden. Dauer und Nachwirkung betreffen eine andere Frage als die Auswahl der Werte. Der Preis hat mit der Aussagekraft der Studie nichts zu tun.","coreRule":"⚡ Frag nie nur nach dem Treffer, sondern nach allen Schüssen und nach dem Zeitpunkt der Zielscheibe.","beleg":"Werkstück B.19 (Anwendung: Pseudomedizin und Nahrungsergänzungsmittel; Red Flags)","status":"entwurf","kurz":"Bei 50 gemessenen Werten ergeben sich zwei „Treffer“ schon durch Zufall. Ob sie vorab als Ziel galten und wie die anderen 48 aussahen, entscheidet. Der naheliegende Fehler ist, die Treffer zu zählen, ohne die Fehlschüsse zu kennen.","prueffrage":"Was würdest du bei 50 gemessenen Werten erwarten, wenn das Mittel überhaupt nichts bewirkt?","rueckmeldung":[{"option":1,"text":"Veröffentlichung und viele Zitate deuten auf eine gewisse Qualitätskontrolle hin. Sie beantworten aber nicht, ob die zwei Werte vorab als Ziel galten oder nachträglich aus 50 herausgepickt wurden."},{"option":2,"text":"Dauer und Nachwirkung sind berechtigte Fragen, wenn es um die Wirkung geht. Das Problem der Broschüre liegt aber woanders: darin, dass zwei Treffer aus 50 Messungen ohne den Rest wenig sagen."},{"option":3,"text":"Der Preis ist für die Kaufentscheidung wichtig, sagt aber nichts darüber, wie belastbar die Studie ist. Auch ein sehr günstiges Mittel wäre nicht besser belegt, wenn zwei Treffer aus 50 Werten zufällig sein können."}],"familie":"muster-im-zufall","fertigkeit":"F4","quellen":[{"typ":"url","kurz":"CDC/CSTE (2013): Investigating Suspected Cancer Clusters and Responding to Community Concerns. MMWR 62(8)","oeffentlich":true,"url":"https://www.cdc.gov/mmwr/pdf/rr/rr6208.pdf","seite":"S. 21–22","abruf":"2026-10-12"},{"typ":"doi","kurz":"Nosek, B. A. u. a. (2018): The preregistration revolution. PNAS 115(11) (frei über PMC5856500)","oeffentlich":true,"doi":"10.1073/pnas.1708274114","abruf":"2026-10-12"}],"thema":"Gesundheit","pruefung":{"lauf":"quiz-audit-v3","modell":"claude-sonnet-5-5","datum":"2026-10-13","urteil":"korrigieren","pruefsumme":"3dadc3a5c1a7e0d1"}},{"id":"qx-b2-010","clusterId":"B","werkstueckRef":"B.19","stufe":3,"question":"Ein Team wertet die Daten einer großen Befragung ohne vorab festgelegte Hypothese aus und stößt auf eine auffällige Häufung. Was darf es mit diesem Ergebnis redlicherweise tun?","options":["Die Häufung als vorläufige Hypothese festhalten und an einer neuen, unabhängigen Stichprobe gezielt prüfen, bevor sie als Befund gilt.","Nach einem Drittfaktor suchen, der Rosenkohlvorliebe und Geburtsmonat verbindet, und die Häufung erst nach dessen Herausrechnen als Befund melden.","Die Häufung mit einem Signifikanztest an denselben Daten prüfen und erst dann als Befund weitergeben, wenn der p-Wert unter 0,05 liegt.","Einen plausiblen Mechanismus zwischen Rosenkohlvorliebe und Geburtsmonat ausarbeiten und die Häufung erst dann als Befund melden, wenn er schlüssig ist."],"correctIndex":0,"explanation":"Das Suchen nach Mustern ist legitim, denn so entstehen Hypothesen. Ein Arzt, der aus vielen unspezifischen Symptomen eine seltene Krankheit vermutet, tut genau das. Kritisch wird es erst, wenn der Fund als Beweis ausgegeben wird. In jeder ausreichend großen, zufälligen Datenmenge entstehen zwangsläufig Cluster, daher kann der erste Fund nur eine Hypothese sein. Erst die Prüfung an einem neuen, unabhängigen Datensatz zeigt, ob das Muster mehr ist als Rauschen. Einen Drittfaktor herauszurechnen ist sinnvoll, wenn ein Zusammenhang schon als echt gilt; hier ist aber erst offen, ob die Häufung mehr als Zufall ist, und das bleibt in denselben Daten ungeklärt. Auch ein p-Wert unter 0,05 beweist bei 40 durchsuchten Merkmalen wenig, weil bei so vielen Vergleichen irgendwo zufällig einer darunter liegt. Eine schlüssig klingende Erklärung lässt sich im Nachhinein zu fast jedem Muster finden und prüft deshalb nichts.","coreRule":"⚡ Ein gefundenes Muster ist der Anfang der Prüfung, nicht ihr Ergebnis.","beleg":"Werkstück B.19 (Adaptives Talent; Kipppunkt)","status":"entwurf","scenario":"Eine Forschungsgruppe hat 40 Merkmale von 3.000 Personen erhoben. Beim Durchsehen fällt auf, dass Menschen, die gern Rosenkohl essen, auffällig oft im Frühjahr Geburtstag haben. Die Gruppe überlegt, wie sie damit umgehen soll.","kurz":"Der erste Fund aus einer Datensuche ist nur eine Hypothese, denn in vielen Daten entstehen zufällig Häufungen. Ob mehr dahintersteckt, zeigt erst ein neuer, unabhängiger Datensatz, nicht dieselben Daten, aus denen das Muster stammt.","prueffrage":"Wie viele Merkmalspaare lassen sich bei 40 Merkmalen überhaupt miteinander vergleichen, und wie viele davon fallen zufällig auf?","rueckmeldung":[{"option":1,"text":"Einen Drittfaktor herauszurechnen ist sinnvoll, wenn ein Zusammenhang schon als echt gilt. Hier ist aber erst offen, ob die Häufung mehr als Zufall ist, und das lässt sich in denselben Daten nicht klären."},{"option":2,"text":"Ein Test an denselben Daten, die das Muster erst gezeigt haben, prüft wenig. Bei 40 durchsuchten Merkmalen liegt irgendwo zufällig ein p-Wert unter 0,05, sodass er hier kaum etwas belegt."},{"option":3,"text":"Ein Mechanismus lässt sich im Nachhinein zu fast jedem Muster finden, auch zu reinem Zufall. Dass eine Erklärung schlüssig klingt, prüft deshalb noch nicht, ob die Häufung real ist."}],"familie":"muster-im-zufall","fertigkeit":"F4","quellen":[{"typ":"doi","kurz":"Nosek, B. A. u. a. (2018): The preregistration revolution. PNAS 115(11) (frei über PMC5856500)","oeffentlich":true,"doi":"10.1073/pnas.1708274114","abruf":"2026-10-12"},{"typ":"url","kurz":"CDC/CSTE (2013): Investigating Suspected Cancer Clusters and Responding to Community Concerns. MMWR 62(8)","oeffentlich":true,"url":"https://www.cdc.gov/mmwr/pdf/rr/rr6208.pdf","seite":"S. 22","abruf":"2026-10-12"}],"thema":"Geld und Zahlen","pruefung":{"lauf":"quiz-audit-v3","modell":"claude-sonnet-5-5","datum":"2026-10-13","urteil":"korrigieren","pruefsumme":"4d77672fcbed4dc5"}},{"id":"qx-b2-011","clusterId":"B","werkstueckRef":"B.19","stufe":4,"question":"Was müsste geprüft werden, bevor man der Meldung einen ursächlichen Zusammenhang abnimmt?","scenario":"Eine Zeitung berichtet über auffällig viele Krankheitsfälle in einer Straße. Die Fälle seien erst aufgefallen, nachdem Anwohner begonnen hatten, Erkrankte zu zählen. Die Zeitung führt die Häufung auf einen nahen Mobilfunkmast zurück und zeigt dazu eine Karte mit den Wohnorten der Betroffenen.","options":["Ob der Zufall die Häufung erklären kann, denn auch ohne jede Ursache bilden sich in einer Region gelegentlich Gruppen von Fällen.","Ob noch weitere Einzelschicksale aus derselben Straße gefunden werden können, denn mehr Fälle machen den Zusammenhang zwingender.","Ob der Betreiber des Mobilfunkmasts dazu Stellung nimmt, denn erst der Widerspruch der Gegenseite gilt als Prüfung.","Ob sich die Fälle auf einer Karte neben dem Mast einzeichnen lassen, denn räumliche Nähe macht den Zusammenhang sichtbar."],"correctIndex":0,"explanation":"In einer ausreichend großen, zufälligen Datenmenge entstehen zwangsläufig Cluster und scheinbar unwahrscheinliche Muster, auch wenn nichts dahintersteckt. Hier kommt hinzu, dass die Häufung erst beim Zählen aufgefallen ist. Ein solches nachträglich gefundenes Muster ist nur eine Hypothese. Bevor man ihm eine Bedeutung beimisst, muss geklärt werden, ob schon der Zufall genügt, um die Häufung zu erklären, und der Zusammenhang muss an einem neuen, unabhängigen Datensatz getestet werden. Weitere Einzelfälle, eine Karte oder eine Stellungnahme verstärken nur den Eindruck, prüfen aber nicht, ob das Muster mehr ist als Zufall.","coreRule":"⚡ Bevor ein Cluster eine Ursache bekommt, muss der Zufall als Erklärung ausgeschlossen sein.","beleg":"Werkstück B.19 (Red Flags: Cluster in geografischen Daten; Kontext & Tiefe; Das Adaptive Talent; Anti-Denkmuster)","status":"entwurf","kurz":"Eine Häufung, die erst beim Zählen aufgefallen ist, ist zunächst nur eine Hypothese. Zufällige Daten bilden von selbst Cluster, deshalb muss zuerst geklärt werden, ob der Zufall genügt, und danach ein unabhängiger Datensatz das Muster bestätigen.","prueffrage":"Wie viele Erkrankte gibt es im Durchschnitt in Straßen dieser Größe, auch weit weg von jedem Mast?","rueckmeldung":[{"option":1,"text":"Mehr Fälle aus derselben Straße wirken wie zusätzliche Belege. Sie stammen aber aus derselben nachträglichen Zählung und verstärken nur den Eindruck. Erst neue, unabhängige Daten würden das Muster tatsächlich testen."},{"option":2,"text":"Die Stellungnahme des Betreibers gehört zu einer fairen Berichterstattung. Sie sagt aber nichts darüber, ob die Häufung über den Zufall hinausgeht. Ein Widerspruch ersetzt keine Prüfung der Daten."},{"option":3,"text":"Die Karte macht die Nähe zum Mast anschaulich, und genau darin liegt ihre Wirkung. Ein nachträglich gesuchtes Muster lässt sich fast immer mit etwas in der Nähe verknüpfen. Nähe zeigt noch keine Ursache und prüft nicht, ob der Zufall genügt."}],"familie":"muster-im-zufall","fertigkeit":"F4","quellen":[{"typ":"url","kurz":"CDC/CSTE (2013): Investigating Suspected Cancer Clusters and Responding to Community Concerns. MMWR 62(8)","oeffentlich":true,"url":"https://www.cdc.gov/mmwr/pdf/rr/rr6208.pdf","seite":"S. 3, 22","abruf":"2026-10-12"}],"thema":"Gesundheit","pruefung":{"lauf":"quiz-audit-v3","modell":"claude-sonnet-5-5","datum":"2026-10-13","urteil":"korrigieren","pruefsumme":"80c9de888cf08211"}},{"id":"qx-b2-012","clusterId":"B","werkstueckRef":"B.19","stufe":1,"question":"Welche Einordnung ist am besten begründet?","options":["Nach sieben Mal Kopf ist Zahl nun überfällig, weil sich Zufallsfolgen ausgleichen und das Gleichgewicht bald wiederherstellen.","Eine bestimmte Folge von sieben Würfen ergibt nur in etwa 0,8 Prozent der Fälle siebenmal Kopf, daher ist Zufall hier wenig plausibel.","Der Freund hat vermutlich nur die Würfe beachtet, die zu seiner Vermutung passen, sodass ein Bestätigungsfehler seinen Eindruck prägt.","Solche Klumpen sind in langen Zufallsreihen gar nicht selten; eine Ursache wäre erst eine Vermutung, die an neuen Würfen zu prüfen wäre."],"correctIndex":3,"explanation":"Bei 100 Würfen gibt es viele Stellen, an denen eine solche Reihe beginnen könnte: Mindestens sieben Mal Kopf in Folge kommt bei einer fairen Münze in etwa jeder dritten Hunderterreihe vor, sieben gleiche Ergebnisse in Folge sogar in etwa jeder zweiten. Dein Freund hat erst die Daten angesehen und dann eine Erklärung um den Klumpen gebaut, wie jemand, der erst auf die Scheunenwand schießt und die Zielscheibe danach um die dichteste Stelle malt. Eine gezinkte Münze ist deshalb nur eine Hypothese, die an neuen, unabhängigen Würfen geprüft werden muss, bevor man ihr glaubt. Der Wert von etwa 0,8 Prozent gilt nur für sieben Würfe, die man vorher festgelegt hat; hier wurde die Stelle erst im Nachhinein gesucht. Dass der Freund nur passende Würfe beachtet hätte, trifft nicht zu, denn er hat jedes Ergebnis notiert. Dass Zahl nun „überfällig“ sei, liest ebenfalls Bedeutung in den Zufall hinein, denn die Münze hat kein Gedächtnis.","coreRule":"⚡ Wo Zufall wirkt, entstehen Klumpen, ohne dass jemand sie verursacht hat.","quote":"Der Fehler liegt darin, diesen Zufallsclustern eine Bedeutung beizumessen, nachdem man sie gefunden hat.","quoteLabel":"Merksatz:","beleg":"Werkstück B.19 (Werkbank-Frage; Analyse)","status":"entwurf","scenario":"Ein Freund wirft 100-mal eine Münze und schreibt jedes Ergebnis auf. In der Reihe findet er sieben Mal hintereinander Kopf. Er ist sicher: „Das kann kein Zufall sein. Entweder ist die Münze gezinkt, oder irgendetwas hat das Ergebnis beeinflusst.“","kurz":"Bei 100 Würfen gibt es viele mögliche Startstellen, ein Siebener-Klumpen ist daher gar nicht selten. Der Fehler: erst die Daten ansehen und dann eine Erklärung um den Klumpen bauen. Eine Ursache bleibt eine Vermutung für neue Würfe.","prueffrage":"In wie vielen von zehn Hunderterreihen einer fairen Münze würdest du irgendwo sieben Mal Kopf hintereinander erwarten?","rueckmeldung":[{"option":0,"text":"Auf lange Sicht nähern sich die Anteile zwar 50 zu 50 an, aber nicht, weil früheres „ausgeglichen“ würde. Die Münze hat kein Gedächtnis, der nächste Wurf ist wieder genau so offen wie jeder andere."},{"option":1,"text":"Die 0,8 Prozent stimmen für sieben Würfe, die man vorher festgelegt hat. Hier wurde die Stelle erst im Nachhinein in 100 Würfen gesucht, und dann kommt so ein Klumpen weit häufiger vor."},{"option":2,"text":"Selektive Wahrnehmung ist ein echtes Risiko, trifft hier aber nicht zu: Der Freund hat jedes Ergebnis notiert und nichts ausgeblendet. Sein Problem liegt woanders, nämlich darin, wie er die Auffälligkeit deutet."}],"familie":"muster-im-zufall","fertigkeit":"F4","quellen":[{"typ":"url","kurz":"Tversky, A.; Kahneman, D. (1974): Judgment under Uncertainty: Heuristics and Biases. Science 185 (inoffizielle Kopie auf einer Kursseite der University of Washington)","oeffentlich":true,"url":"https://sites.stat.washington.edu/peter/498.Sp16/Tversky.pdf","seite":"S. 1125","abruf":"2026-10-12"},{"typ":"doi","kurz":"Tversky, A.; Kahneman, D. (1974): Judgment under Uncertainty: Heuristics and Biases. Science 185(4157), 1124–1131","oeffentlich":false,"doi":"10.1126/science.185.4157.1124","seite":"S. 1125"}],"thema":"Geld und Zahlen","pruefung":{"lauf":"quiz-audit-v3","modell":"claude-sonnet-5-5","datum":"2026-10-13","urteil":"korrigieren","pruefsumme":"ab8d8233b35891d1"}},{"id":"qx-b2-013","clusterId":"B","werkstueckRef":"B.20","stufe":1,"question":"Ein Schätzexperiment: Menschen sehen ein Glücksrad, das zufällig bei 10 oder 65 stehen bleibt. Danach sagen sie, ob der Anteil afrikanischer Länder in der UNO über oder unter dieser Zahl liegt, und schätzen ihn. Wer die 10 sah, schätzt im Median 25 %, wer die 65 sah, 45 %. Wie lässt sich das am besten deuten?","options":["Nur Zahlen mit erkennbarem Bezug zur Frage beeinflussen Schätzungen, denn Menschen blenden Unpassendes aus; der Unterschied hat andere Gründe.","Die beiden Gruppen unterschieden sich schon vorher im Wissen über die UNO, wie es bei Vergleichen ohne Zufallszuteilung vorkommt.","Die Teilnehmer schätzten nach dem, was ihnen aus Nachrichten über Afrika präsent war (Verfügbarkeitsheuristik), nicht nach dem Glücksrad.","Auch eine zufällige, völlig unpassende Zahl zieht Schätzungen in ihre Richtung, selbst wenn sie mit der Frage nichts zu tun hat."],"correctIndex":3,"explanation":"Die zufällige, bedeutungslose Zahl des Glücksrads wirkte als mentaler Anker: Die Schätzungen wurden in Richtung dieser ersten Zahl gezogen. Bei Schätzungen wirkt eine solche erste Zahl selbst dann, wenn sie erkennbar willkürlich ist. Beide Gruppen schätzten jeweils zur gezeigten Zahl hin, also gerichtet verschoben (Median 25 % gegenüber 45 %; Tversky und Kahneman, 1974). Dass die Gruppen schon vorher unterschiedlich viel wussten, passt nicht, denn das Glücksrad teilte sie zufällig ein. Was Menschen aus den Nachrichten präsent haben, kann beide Gruppen gleich betreffen und erklärt deshalb den Unterschied zwischen ihnen nicht. Und dass nur Passendes zähle, widerlegt gerade dieser Versuch, in dem eine erkennbar zufällige Zahl wirkte.","coreRule":"⚡ Die erste Zahl zieht dein Urteil zu sich, auch wenn sie nichts mit der Frage zu tun hat.","beleg":"Werkstück B.20; Fn. gl-b-anchoring (Tversky/Kahneman 1974, Science 185, S. 1128; Rad-Detail nach Kahneman 2012, Kap. 11)","status":"entwurf","scenario":"","quote":"","quoteLabel":"","kurz":"Eine zufällige, bedeutungslose Zahl zog die Schätzungen jeweils in ihre Richtung (Median 25 % gegenüber 45 %). Der naheliegende Fehler ist, anzunehmen, nur Passendes beeinflusse uns; hier wirkte gerade eine erkennbar willkürliche Zahl.","prueffrage":"Wie wurde entschieden, wer die 10 und wer die 65 zu sehen bekam, und welche Gruppe schätzte höher?","rueckmeldung":[{"option":0,"text":"Dass Menschen Unpassendes ausblenden, klingt vernünftig. Der Versuch zeigt aber das Gegenteil: Obwohl das Glücksrad erkennbar zufällig war, verschob seine Zahl die Schätzungen deutlich. Für den Unterschied braucht es keine anderen Gründe."},{"option":1,"text":"Vorab-Unterschiede im Wissen sind bei Vergleichen ohne Zufallszuteilung tatsächlich ein häufiger Störfaktor. Hier aber entschied das Glücksrad per Zufall, wer welche Zahl sah, daher sollten sich die Gruppen im Vorwissen im Schnitt nicht unterscheiden."},{"option":2,"text":"Was aus den Nachrichten präsent ist, kann Schätzungen durchaus prägen. Es kann aber beide Gruppen gleich betreffen und erklärt deshalb nicht, warum die Gruppe mit der 65 deutlich höher schätzte als die mit der 10."}],"familie":"anker-erkennen","fertigkeit":"F4","quellen":[{"typ":"url","kurz":"Tversky, A.; Kahneman, D. (1974): Judgment under Uncertainty: Heuristics and Biases. Science 185 (inoffizielle Kopie, Kursseite University of Washington)","oeffentlich":true,"url":"https://sites.stat.washington.edu/peter/498.Sp16/Tversky.pdf","seite":"S. 1128","abruf":"2026-10-12"},{"typ":"doi","kurz":"Tversky, A.; Kahneman, D. (1974): Judgment under Uncertainty: Heuristics and Biases. Science 185(4157), 1124–1131","oeffentlich":false,"doi":"10.1126/science.185.4157.1124","seite":"S. 1128"},{"typ":"literatur","kurz":"Kahneman, D. (2012): Schnelles Denken, langsames Denken. München: Siedler, Kap. 11","oeffentlich":false}],"thema":"Psychologie","pruefung":{"lauf":"quiz-audit-v3","modell":"claude-sonnet-5-5","datum":"2026-10-13","urteil":"ok","pruefsumme":"66286afbfa12ea19"}},{"id":"qx-b2-014","clusterId":"B","werkstueckRef":"B.20","stufe":2,"question":"Wie wirkt der durchgestrichene Preis auf dein Urteil, und welche Frage prüft das Angebot am besten?","scenario":"Im Onlineshop steht neben einer Jacke: „UVP 199 €, jetzt nur 99 €!“ Du hattest vorher keine Vorstellung davon, was eine solche Jacke kosten sollte.","options":["Die 199 € löst die Angst aus, etwas zu verpassen, denn Verluste wiegen schwerer als Gewinne; frag dich, ob du das Angebot bereuen würdest, wenn du es auslässt.","Die 199 € zieht dein Urteil in ihre Richtung, denn die hohe erste Zahl lässt 99 € billig erscheinen; frag dich, wie du den Preis ohne die 199 ganz neu bewerten würdest.","Die 199 € wirkt über die Menge der Käufer, denn was viele zu diesem Preis kauften, scheint gut zu sein; frag dich, wie beliebt die Jacke bei anderen Kunden ist.","Die 199 € wirkt über den Ruf einer Marke, denn bekannte Namen färben auf die Bewertung ab (Halo-Effekt); frag dich, ob die Jacke auch ohne Markennamen überzeugen würde."],"correctIndex":1,"explanation":"Die durchgestrichene Zahl ist ein klassischer Anker: Die erste genannte Zahl setzt den Rahmen, in dem du die zweite beurteilst, und 99 € wirken günstig, weil sie neben 199 € stehen, nicht weil du den Wert der Jacke kennst. Gegen die Wirkung hilft die Frage, wie du den Preis bewerten würdest, wenn es die erste Zahl nie gegeben hätte. Preiswissen schützt nicht zuverlässig: In einem Versuch ließen sich auch erfahrene Immobilienmakler bei der Schätzung eines Hauswerts vom vorgegebenen Angebotspreis beeinflussen (Northcraft und Neale 1987). Der Streichpreis ist außerdem kein verlässlicher Beleg für den Wert, sondern ein hoher Anker, der den tatsächlichen Preis als Schnäppchen erscheinen lässt. Die Angst, ein Angebot zu verpassen, braucht eine Frist oder knappe Ware, wovon hier nichts steht. Beliebtheit bei anderen Käufern spielt keine Rolle, weil ein durchgestrichener Preis nichts über andere Kunden sagt. Auch ein Markenname, der auf die Bewertung abfärben könnte, kommt nicht vor.","coreRule":"⚡ Bewerte jeden Preis so, als hättest du den ersten genannten nie gesehen.","quote":"Wenn diese erste Zahl/diese erste Information nie existiert hätte, wie würde ich diese Situation dann völlig neu und von Grund auf bewerten?","quoteLabel":"Prüffrage:","beleg":"Werkstück B.20 (Anwendung: Preisgestaltung; Anti-Denkmuster)","status":"entwurf","kurz":"Die erste Zahl setzt den Rahmen: 99 € wirken günstig, weil 199 € daneben stehen, nicht weil du den Wert der Jacke kennst. Wer sich vorstellt, die Streichzahl hätte es nie gegeben, merkt, wie wenig er über den Preis wirklich weiß.","prueffrage":"Was kosten vergleichbare Jacken bei anderen Händlern, und steht dort ebenfalls ein Streichpreis daneben?","rueckmeldung":[{"option":0,"text":"Angst, etwas zu verpassen, braucht meist einen Druck wie eine Frist oder knappe Ware, und davon steht hier nichts. Die Bedauern-Frage prüft außerdem nicht den Preis, sondern verstärkt nur das Gefühl, handeln zu müssen."},{"option":2,"text":"Was viele kaufen, wirkt oft gut. Der durchgestrichene Preis sagt aber nichts darüber, wie viele Kunden die Jacke zu welchem Preis gekauft haben, und die Beliebtheit prüft den Preis auch nicht."},{"option":3,"text":"Bekannte Marken färben tatsächlich oft auf die Bewertung ab. Im Szenario ist aber von keiner Marke die Rede, sondern nur von einer Jacke und zwei Preisen, daher greift dieser Effekt hier nicht."}],"familie":"anker-erkennen","fertigkeit":"F4","quellen":[{"typ":"literatur","kurz":"Northcraft, G. B.; Neale, M. A. (1987): Experts, amateurs, and real estate: An anchoring-and-adjustment perspective on property pricing decisions. Organizational Behavior and Human Decision Processes 39(1), 84–97","oeffentlich":false},{"typ":"url","kurz":"Tversky, A.; Kahneman, D. (1974): Judgment under Uncertainty: Heuristics and Biases. Science 185 (inoffizielle Kopie, Kursseite University of Washington)","oeffentlich":true,"url":"https://sites.stat.washington.edu/peter/498.Sp16/Tversky.pdf","seite":"S. 1128","abruf":"2026-10-12"}],"thema":"Geld und Zahlen","pruefung":{"lauf":"quiz-audit-v3","modell":"claude-sonnet-5-5","datum":"2026-10-13","urteil":"korrigieren","pruefsumme":"f87ec08706994be7"}},{"id":"qx-b2-015","clusterId":"B","werkstueckRef":"B.20","stufe":3,"question":"Welche Schlussfolgerung ist am besten begründet?","options":["Dieser Preisbefund ist weniger gesichert als gedacht; dass Anker Schätzungen beeinflussen, ist davon unabhängig weiterhin gut belegt.","Spätere Studien fanden meist schwächere Effekte, also ist der Ankereffekt insgesamt widerlegt, auch bei Schätzungen und anderen Urteilen.","Ein veröffentlichter Befund wiegt schwerer als Wiederholungen, weil er begutachtet wurde; der Preisbefund bleibt daher gültig.","Dass mehrere Wiederholungen etwas fanden, wenn auch weniger, bestätigt den Preisbefund; die schwächeren Effekte sind nur Messrauschen."],"correctIndex":0,"explanation":"Misslingt die Wiederholung eines Versuchs oder fällt der Effekt viel schwächer aus, ist der ursprüngliche Befund weniger sicher, aber nicht automatisch widerlegt. Und er sagt nur etwas über genau diese Versuchsanordnung: Dass ein zufälliger Zahlenanker die Zahlungsbereitschaft stark lenkt, ist unsicher. Dass Anker Schätzungen verzerren, ist davon getrennt gut belegt, etwa durch das Glücksrad-Experiment von Tversky und Kahneman, in dem eine erkennbar zufällige Zahl die Schätzung des Anteils afrikanischer UN-Mitglieder verschob (Median 25 % gegenüber 45 %). Selbst Maniadis und Kollegen, die deutlich kleinere Effekte fanden als Ariely und seine Kollegen, halten Ankereffekte bei Bewertungen für real und bezweifeln nur deren Größe. Dass die Wiederholungen den Ankereffekt insgesamt widerlegen, folgt daraus nicht, denn sie betrafen nur diese Versuchsanordnung. Eine Begutachtung schützt nicht vor einem Befund, den andere nicht reproduzieren können, deshalb zählen hier die Wiederholungen. Und Effekte, die deutlich kleiner ausfielen oder ganz fehlten, lassen sich nicht als bloßes Messrauschen abtun, das den Befund bestätigt.","coreRule":"⚡ Wird ein Befund schlechter bestätigt, ist er weniger sicher, nicht automatisch falsch. Prüfe, was genau wackelt, und wie stark.","beleg":"Werkstück B.20 (Analyse); Fn. gl-b-anker-preis (Ariely/Loewenstein/Prelec 2003, S. 75–77; Maniadis/Tufano/List 2014, AER 104(1), S. 277–290, dort: andere Studien fanden „(if any) much smaller effects“; Ankereffekte bei Bewertungen gelten dennoch als real, offen ist ihre Größe)","status":"entwurf","scenario":"Eine Kollegin sagt: „Ein Experiment hat gezeigt, dass Menschen mehr für einen Wein zahlen, wenn sie vorher die letzten Ziffern ihrer Sozialversicherungsnummer als Dollarbetrag notiert haben. Ein Zufallswert steuert also, was wir bereit sind zu zahlen.“ Später liest du, dass spätere Studien meist deutlich schwächere Effekte fanden, manche gar keine.","kurz":"Wenn Wiederholungen schwächere oder keine Effekte finden, ist der Preisbefund weniger sicher, aber nicht automatisch widerlegt. Und er betrifft nur diese Anordnung: Dass Anker Schätzungen verzerren, ist davon getrennt gut belegt.","prueffrage":"Was genau fanden die späteren Studien im Vergleich zum ersten Versuch, und was wurde dort überhaupt gemessen?","rueckmeldung":[{"option":1,"text":"Dass spätere Studien meist schwächere Effekte fanden, stimmt, und es lässt den Preisbefund wackeln. Sie prüften aber nur diese Anordnung mit Wein und Zahlungsbereitschaft; bei Schätzungen ist der Ankereffekt davon unabhängig gut belegt."},{"option":2,"text":"Eine Begutachtung klingt nach Qualitätssiegel, schützt aber nicht davor, dass andere den Befund nicht reproduzieren können. Gerade deshalb zählen hier die Wiederholungen mit schwächeren oder fehlenden Effekten, und der Preisbefund bleibt unsicher."},{"option":3,"text":"Ein Teil der Wiederholungen fand tatsächlich noch etwas, doch deutlich kleinere oder ganz fehlende Effekte bestätigen den Befund nicht. Sie als bloßes Messrauschen abzutun, ist unbelegt: Sie machen den ursprünglichen Befund weniger sicher."}],"familie":"gewissheit-kalibrieren","fertigkeit":"F5","quellen":[{"typ":"url","kurz":"Maniadis, Z.; Tufano, F.; List, J. A. (2013): One Swallow Doesn't Make a Summer: New Evidence on Anchoring Effects. CeDEx Discussion Paper 2013-07 (später AER 104(1), 277–290)","oeffentlich":true,"url":"https://www.nottingham.ac.uk/cedex/documents/papers/cedex-discussion-paper-2013-07.pdf","abruf":"2026-10-12"},{"typ":"url","kurz":"Tversky, A.; Kahneman, D. (1974): Judgment under Uncertainty: Heuristics and Biases. Science 185 (inoffizielle Kopie, Kursseite University of Washington)","oeffentlich":true,"url":"https://sites.stat.washington.edu/peter/498.Sp16/Tversky.pdf","seite":"S. 1128","abruf":"2026-10-12"},{"typ":"doi","kurz":"Ariely, D.; Loewenstein, G.; Prelec, D. (2003): „Coherent Arbitrariness“: Stable Demand Curves Without Stable Preferences. Quarterly Journal of Economics 118(1), 73–106","oeffentlich":false,"doi":"10.1162/00335530360535153"}],"thema":"Psychologie","pruefung":{"lauf":"quiz-audit-v3","modell":"claude-sonnet-5-5","datum":"2026-10-13","urteil":"korrigieren","pruefsumme":"d487013ac2ebff61"}},{"id":"qx-b2-016","clusterId":"B","werkstueckRef":"B.20","stufe":4,"question":"Welche Erklärung passt am besten dazu, dass die Zufallszahl die Schätzungen trotzdem verschiebt?","scenario":"In einem Versuch sollen Menschen schätzen, wie viel Prozent der Mitgliedstaaten der Vereinten Nationen afrikanische Länder sind. Vorher dreht die Versuchsleitung ein Glücksrad (Ergebnis: 65) und fragt: „Liegt der Anteil über oder unter dieser Zahl?“ Danach liegen die Schätzungen deutlich höher als bei einer Vergleichsgruppe, die ohne Rad schätzt. Du weißt: Das Rad war reiner Zufall, und niemand hielt die Zahl für eine Expertenauskunft.","options":["Die Zahl wirkt, weil Menschen sich Zahlen nur einmal merken können und auch bei neuen Informationen nicht mehr umdenken.","Die Zahl wirkt, weil die Schätzenden sie für eine Expertenauskunft halten und sie dann ungeprüft übernehmen.","Die Frage nach „darüber oder darunter“ ruft bevorzugt Wissen wach, das zur Zahl passt, und färbt so die anschließende Schätzung.","Die Schätzenden starten bei der Zahl und passen von dort aus immer zu wenig an, genau wie bei selbst gewählten Ausgangswerten."],"correctIndex":2,"explanation":"Das Rad war erkennbar zufällig, und niemand hielt die Zahl für eine Expertenauskunft; ungeprüftes Vertrauen erklärt den Effekt also nicht. Die klassische Erklärung „Anpassung und Verankerung“ (Start beim Anker, zu wenig Korrektur) gilt nach späteren Versuchen vor allem für selbst gewählte Ausgangswerte, hier aber war die Zahl vorgegeben. Bei vorgegebenen Ankern wirkt offenbar ein anderer Mechanismus: Schon die Frage, ob die Antwort über oder unter der Zahl liegt, ruft bevorzugt Wissen wach, das zu ihr passt. Dass Menschen sich Zahlen nur einmal merken und nie mehr umdenken könnten, ist eine Übertreibung, die das Beispiel nicht stützt. Wer die Erklärung eines Effekts prüft, sollte fragen, ob sie zu den Rahmenbedingungen passt; ob beide Mechanismen nebeneinander wirken, ist in der Forschung umstritten.","coreRule":"⚡ Anker wirken auf mehr als einem Weg: Prüfe bei einer Erklärung, ob sie zu den Umständen passt (vorgegebener oder selbst gewählter Anker), und ersetze die erste Zahl bewusst durch eine eigene Ausgangsschätzung.","beleg":"Werkstück B.20 (Analyse: Anpassung und Verankerung); Fn. gl-b-anker-mechanismus (Epley/Gilovich 2006, Psychological Science 17(4), S. 312, 317; Gegenposition Simmons/LeBoeuf/Nelson 2010)","status":"entwurf","kernregel":"⚡ Auch eine erkennbar zufällige Zahl kann Schätzungen verschieben, schon die Frage „darüber oder darunter?“ ruft passendes Wissen wach. Schätze deshalb zuerst eigenständig, bevor du eine vorgegebene Zahl beachtest.","kurz":"Bei einer vorgegebenen Zahl erklärt vermutlich schon die Frage „über oder unter dieser Zahl?“ den Effekt, weil sie passendes Wissen wachruft. Vertrauen in eine Auskunft scheidet aus, und Start mit zu wenig Korrektur passt eher zu selbst gewählten Werten.","prueffrage":"Was unterscheidet diese Zahl von einem Startwert, den die Schätzenden selbst gewählt hätten, und woher kam sie?","rueckmeldung":[{"option":0,"text":"Dass die Schätzungen an der Zahl hängen, ist tatsächlich zu beobachten. Daraus folgt aber nicht, dass Menschen sich Zahlen nur einmal merken und nie umdenken: Das ist überzogen, und das Beispiel stützt es nicht."},{"option":1,"text":"Ungeprüftes Vertrauen in eine Auskunft ist ein möglicher Grund, warum Zahlen wirken. Hier passt er nicht: Das Rad war erkennbar Zufall, und niemand hielt die Zahl für eine Expertenauskunft."},{"option":3,"text":"Start beim Anker und zu wenig Korrektur ist die bekannte Erklärung und gilt vor allem für selbst gewählte Ausgangswerte. Hier wurde die Zahl vorgegeben, deshalb erklärt sie den Effekt nicht am besten."}],"familie":"anker-erkennen","fertigkeit":"F4","quellen":[{"typ":"url","kurz":"Association for Psychological Science: Abstract zu Epley, N.; Gilovich, T. (2006): The Anchoring-and-Adjustment Heuristic: Why the Adjustments Are Insufficient","oeffentlich":true,"url":"https://www.psychologicalscience.org/journals/psychological-science/j.1467-9280.2006.01704.x/","abruf":"2026-10-12"},{"typ":"doi","kurz":"Epley, N.; Gilovich, T. (2006): The Anchoring-and-Adjustment Heuristic: Why the Adjustments Are Insufficient. Psychological Science 17(4), 311–318","oeffentlich":false,"doi":"10.1111/j.1467-9280.2006.01704.x","seite":"S. 312, 317"},{"typ":"literatur","kurz":"Simmons, J. P.; LeBoeuf, R. A.; Nelson, L. D. (2010): The effect of accuracy motivation on anchoring and adjustment: Do people adjust from provided anchors? Journal of Personality and Social Psychology 99(6)","oeffentlich":false}],"thema":"Psychologie","pruefung":{"lauf":"quiz-audit-v3","modell":"claude-sonnet-5-5","datum":"2026-10-13","urteil":"korrigieren","pruefsumme":"90439d974211788f"}},{"id":"qx-b2-017","clusterId":"B","werkstueckRef":"B.21","stufe":1,"question":"Welche Erwiderung auf den Einwand des Ingenieurs prüft die Behauptung am besten, ohne die Ebenen von Werten und Fakten zu vermischen?","options":["Das Ziel steht fest. Offen ist nur der Weg, und ob er trägt, lässt sich mit den Berechnungen des Ingenieurs prüfen.","Der Ingenieur teilt das Ziel der Aktivistin, also stimmen auch seine Berechnungen, und sie sollte ihren Plan aufgeben.","Ziele zählen in solchen Debatten nicht. Nur wer die besseren Zahlen hat, darf über Energiepolitik mitreden.","Beide Seiten wollen das Richtige, also lässt sich nicht klären, wer sachlich recht hat. Es bleibt Geschmackssache."],"correctIndex":0,"explanation":"Die Aktivistin schließt von der guten Absicht auf die Richtigkeit ihrer Tatsachenannahmen und wehrt die Gegenzahlen mit einem Angriff auf Motive ab. Das vermischt zwei Ebenen: was erstrebenswert ist (Werte) und was tatsächlich funktioniert (Fakten). Das Ziel kann geklärt sein, während der Weg offen bleibt und sich anhand von Fakten und Daten klären lässt. Ob der Ingenieur recht hat, ist damit noch nicht entschieden. Das zeigt sich erst, wenn man seine Berechnungen prüft, nicht durch den Verweis auf moralische Überlegenheit. Falsch wäre es, aus dem geteilten Ziel auf die Richtigkeit der Berechnungen zu schließen, Ziele für irrelevant zu erklären oder die Tatsachenfrage für unentscheidbar zu halten. Gute Absichten sind kein Schutz vor schlechten Ergebnissen.","coreRule":"⚡ Eine gute Absicht macht die Tatsachenbehauptung nicht wahr.","beleg":"Werkstück B.21 (Kernidee; Anti-Denkmuster; Beispiel Aktivistin und Ingenieur)","status":"entwurf","scenario":"In einer Debatte über Energiepolitik sagt eine Aktivistin: „Wir kämpfen für die Rettung des Planeten, also stimmt auch unser Plan: Jede Kernenergie ist abzulehnen, und eine Versorgung allein aus Erneuerbaren ist machbar. Wer das bezweifelt, dem ist der Planet egal.“ Ein Ingenieur entgegnet: „Ich teile dein Ziel, aber meine Berechnungen zeigen, dass wir ohne Kernenergie keine stabile Versorgung gewährleisten können.“ Die Aktivistin antwortet: „Deine Zahlen sind nur Ablenkung. Wir haben die moralische Überlegenheit, und die zählt am Ende.“","kurz":"Das Ziel kann geklärt sein, während der Weg offen bleibt: Ob der Plan trägt, zeigt sich erst an den Berechnungen. Der Fehler wäre, von guter Absicht auf richtige Tatsachen zu schließen oder Gegenzahlen als Ablenkung abzutun.","prueffrage":"Was genau wirft die Aktivistin dem Ingenieur vor, und was sagt sie zu seinen Berechnungen selbst?","rueckmeldung":[{"option":1,"text":"Dass der Ingenieur das Ziel teilt, wirkt wie ein Argument für seine Seite. Doch auch bei ihm sagt die Absicht nichts über die Richtigkeit seiner Zahlen. Sie müssen genauso geprüft werden wie der Plan der Aktivistin."},{"option":2,"text":"Zahlen sind für die Wirksamkeit eines Plans wichtig, aber das Ziel bleibt dennoch eine Wertfrage, über die man sich verständigen kann. Es ist sogar die Grundlage, auf der man überhaupt von „funktioniert“ oder „funktioniert nicht“ spricht."},{"option":3,"text":"Dass beide das Richtige wollen, macht die Tatsachenfrage nicht zur Geschmackssache. Ob eine Versorgung ohne Kernenergie stabil läuft, lässt sich mit Daten und Berechnungen klären, unabhängig von den Absichten beider Seiten."}],"familie":"absicht-ist-kein-beleg","fertigkeit":"F2","quellen":[{"typ":"url","kurz":"Dowden, B.: Fallacies. Internet Encyclopedia of Philosophy (Einträge „Ad Hominem“, „Faulty Motives“)","oeffentlich":true,"url":"https://iep.utm.edu/fallacy/","abruf":"2026-10-12"},{"typ":"doi","kurz":"Liu, B. S.; Ditto, P. H. (2013): What Dilemma? Moral Evaluation Shapes Factual Belief. Social Psychological and Personality Science 4(3), 316–323","oeffentlich":false,"doi":"10.1177/1948550612456045"}],"thema":"Zusammenleben","pruefung":{"lauf":"quiz-audit-v3","modell":"claude-sonnet-5-5","datum":"2026-10-13","urteil":"korrigieren","pruefsumme":"c45ec9ed65b1d967"}},{"id":"qx-b2-018","clusterId":"B","werkstueckRef":"B.21","stufe":2,"question":"Was lässt sich aus dieser Antwort über die Richtigkeit der Berechnungen schließen?","scenario":"In einer Debatte zur Energieversorgung legt ein Ingenieur Berechnungen vor, wonach sich eine stabile Stromversorgung mit der heutigen Technik und Speicherlösung nicht allein mit erneuerbaren Quellen sichern lässt. Die Gegenseite antwortet: „Sie arbeiten für eine moralisch korrupte Industrie. Unsere Sache ist gerecht, und das zählt am Ende.“","options":["Sie zeigt, dass die Berechnungen stimmen, denn die Gegenseite hält keine einzige eigene Zahl dagegen und greift nur den Absender an.","Sie zeigt, dass die Berechnungen unvollständig sind, denn gute Entscheidungen müssen auch moralische Gründe berücksichtigen, die in Zahlen fehlen.","Sie zeigt, dass seine Zahlen vermutlich falsch sind, denn Befangenheit verschiebt Berechnungen meist in Richtung der eigenen Interessen.","Sie zeigt nichts darüber, denn ob die Berechnungen stimmen, lässt sich nur an den Zahlen selbst klären, nicht an Herkunft oder Moral."],"correctIndex":3,"explanation":"Die Antwort greift das Motiv des Gegners an („moralisch korrupte Industrie“) und beruft sich auf die eigene gerechte Sache. Beides sind Aussagen über Absichten und Werte, keine über die Berechnungen. Ob eine Rechnung stimmt, hängt nicht davon ab, wer sie vorlegt oder wie gut die Ziele des Gegenübers sind. Auch wer ein moralisch hehres Ziel verfolgt, kann sich über die Fakten irren, und auch ein Gegner mit zweifelhaften Motiven kann richtig rechnen. Der Einwand wäre nur dann ein Argument, wenn er die Zahlen selbst prüft, etwa Annahmen, Rechenweg oder Datenquellen. Solange das nicht geschieht, bleibt die Sachfrage offen und muss mit den Zahlen geklärt werden. Dass die Gegenseite keine Gegenzahlen nennt, macht die Berechnungen nicht richtig, sondern lässt die Frage offen. Moralische Gründe können für Entscheidungen wichtig sein, sagen aber nichts darüber, ob eine Rechnung stimmt. Und dass jemand befangen sein kann, ist ein Grund zum genauen Hinsehen, aber kein Beleg dafür, dass die Zahlen falsch sind.","coreRule":"⚡ Wer die Motive des Gegners angreift oder die eigene Moral betont, hat seine Zahlen noch nicht widerlegt.","beleg":"Werkstück B.21 (Eingangsszene; Analyse: Selbst-Immunisierung, Ad hominem)","status":"entwurf","kurz":"Der Angriff auf den Absender und der Verweis auf die eigene gerechte Sache sagen nichts über die Rechnung selbst. Ob sie stimmt, zeigt sich nur an Annahmen, Rechenweg und Daten, nicht daran, wer sie vorlegt oder welche Ziele er hat.","prueffrage":"Würde sich an den Berechnungen etwas ändern, wenn derselbe Ingenieur für einen Umweltverband arbeitete?","rueckmeldung":[{"option":0,"text":"Dass die Gegenseite keine eigenen Zahlen nennt, fällt tatsächlich auf. Daraus folgt aber nicht, dass die Berechnungen stimmen: Das Fehlen eines Gegenarguments lässt die Sachfrage nur offen."},{"option":1,"text":"Moralische Gründe können für eine Entscheidung durchaus wichtig sein. Die Frage lautet aber, ob die Berechnungen stimmen, und darauf haben Werte keinen Einfluss. Unvollständig in der Moral heißt nicht unrichtig in den Zahlen."},{"option":2,"text":"Befangenheit ist ein guter Grund, genauer hinzusehen. Sie belegt aber keinen Fehler: Auch jemand mit Eigeninteresse kann richtig rechnen, und ob es hier einen Fehler gibt, zeigt nur die Prüfung der Zahlen."}],"familie":"absicht-ist-kein-beleg","fertigkeit":"F2","quellen":[{"typ":"url","kurz":"Dowden, B.: Fallacies. Internet Encyclopedia of Philosophy (Einträge „Ad Hominem“, „Faulty Motives“)","oeffentlich":true,"url":"https://iep.utm.edu/fallacy/","abruf":"2026-10-12"}],"thema":"Zusammenleben","pruefung":{"lauf":"quiz-audit-v3","modell":"claude-sonnet-5-5","datum":"2026-10-13","urteil":"ok","pruefsumme":"0a4fb2a1f1e28a6c"}},{"id":"qx-b2-019","clusterId":"B","werkstueckRef":"B.21","stufe":3,"question":"In einer Debatte über Energiepolitik sagt eine Aktivistin: „Wir kämpfen für die Rettung des Planeten. Die Zahlen des Ingenieurs sind nur Ablenkung, er arbeitet für eine moralisch korrupte Industrie. Wir sind moralisch im Recht, und das zählt.“ Was ist an diesem Vorgehen der Kern des Fehlers?","options":["Sie schließt von der guten Absicht ihres Ziels auf die Richtigkeit ihrer Annahmen über den Weg dorthin und prüft die Zahlen deshalb nicht.","Sie verzerrt die Aussage des Ingenieurs zu einer leichter angreifbaren Karikatur und widerlegt nur diese, statt seine eigentlichen Zahlen.","Sie stützt ihren Plan auf die große Zahl ihrer Anhänger und lässt so die Zustimmung vieler an die Stelle der Prüfung der Annahmen treten.","Sie schließt von dem, was ist, auf das, was sein soll, und begründet ihre Forderung damit, dass der heutige Zustand auch der richtige sei."],"correctIndex":0,"explanation":"Ob ein Ziel gut ist (Werte) und ob ein bestimmter Weg es erreicht (Fakten), sind zwei verschiedene Fragen. Die Aktivistin schließt von der guten Absicht auf die Richtigkeit ihrer Annahmen und wehrt Gegenargumente ab, indem sie die Motive des Ingenieurs angreift, statt seine Zahlen zu prüfen. Ob er recht hat, ist damit nicht entschieden, das ließe sich nur mit den Daten klären. Eine moralische Überzeugung ist dabei nicht das Problem, sie treibt oft Reformen an. Zum Fehler wird sie, wenn sie zur Lizenz wird, die Realität nicht mehr zu prüfen, und Fakten dann als moralisch minderwertig gelten. Ein Strohmann setzt eine verzerrte Wiedergabe der Aussage des anderen voraus; sie gibt aber gar keine Fassung seiner Aussage wieder. Dass viele ihrer Anhänger zustimmen, spielt in ihrer Äußerung keine Rolle. Und sie leitet nicht das Sollen aus dem Sein ab, sondern umgekehrt das Sein aus ihrem Wollen.","coreRule":"⚡ Moral gibt das Ziel vor, aber den Weg dorthin entscheiden die Fakten.","beleg":"Werkstück B.21 (Adaptives Talent; Kipppunkt)","status":"entwurf","scenario":"","kurz":"Ob ein Ziel gut ist, sagt nicht, ob ein Weg es erreicht. Die Aktivistin lässt die gute Absicht für die Richtigkeit ihrer Annahmen einstehen und greift die Motive des Ingenieurs an, statt seine Zahlen zu prüfen.","prueffrage":"Womit begegnet die Aktivistin den Zahlen des Ingenieurs, und was davon betrifft die Zahlen selbst?","rueckmeldung":[{"option":1,"text":"Eine Verzerrung würde voraussetzen, dass sie seine Aussage in einer Fassung wiedergibt. Das tut sie aber nicht: Sie nennt seine Zahlen nur „Ablenkung“ und greift seine Motive an. Seine Zahlen bleiben ungeprüft."},{"option":2,"text":"Auf die Zahl ihrer Anhänger beruft sie sich in dieser Äußerung nirgends. Ihr „Wir“ benennt die Bewegung, ist aber kein Argument. Die Annahmen bleiben ungeprüft, weil sie sich moralisch im Recht sieht, nicht weil viele zustimmen."},{"option":3,"text":"Ein solcher Fehlschluss würde den heutigen Zustand zum richtigen erklären. Die Aktivistin will den Zustand aber gerade verändern. Ihr Fehler läuft in die andere Richtung: Aus ihrem Wollen, dem guten Ziel, folgt angeblich schon, dass ihre Annahmen über den Weg stimmen."}],"familie":"absicht-ist-kein-beleg","fertigkeit":"F2","quellen":[{"typ":"doi","kurz":"Liu, B. S.; Ditto, P. H. (2013): What Dilemma? Moral Evaluation Shapes Factual Belief. Social Psychological and Personality Science 4(3), 316–323","oeffentlich":false,"doi":"10.1177/1948550612456045"},{"typ":"url","kurz":"Dowden, B.: Fallacies. Internet Encyclopedia of Philosophy (Eintrag „Faulty Motives“)","oeffentlich":true,"url":"https://iep.utm.edu/fallacy/","abruf":"2026-10-12"}],"thema":"Zusammenleben","pruefung":{"lauf":"quiz-audit-v3","modell":"claude-sonnet-5-5","datum":"2026-10-13","urteil":"korrigieren","pruefsumme":"453756801e977009"}},{"id":"qx-b2-020","clusterId":"B","werkstueckRef":"B.21","stufe":4,"question":"Was ist ein produktiver erster Zug in dieser Debatte?","scenario":"In deinem Verein streiten zwei Lager über die Methoden eines Tierschutz-Protests. Lager A sagt: „Wir blockieren Schlachthof-Zufahrten, denn das ist der einzige Weg, der der Sache gerecht wird.“ Lager B meint: „Die Blockaden schaden uns eher, weil sie Spenden und Unterstützung kosten.“ Beide wollen weniger Tierleid und halten sich für moralisch im Recht.","options":["Beide Lager darlegen lassen, was sie antreibt, und dem mit den lauteren Beweggründen folgen, weil gute Absichten für gute Methoden sprechen.","Zuerst klären, ob Tierleid überhaupt vermieden werden soll, denn ohne gemeinsame Werte lässt sich über Methoden nicht sinnvoll streiten.","Das gemeinsame Ziel als geklärt festhalten und getrennt davon prüfen, welcher Weg es nach den vorliegenden Daten am ehesten erreicht.","Sich auf einen Mittelweg zwischen Blockade und Verzicht einigen, weil beide Lager dann Zugeständnisse machen und der Streit schnell endet."],"correctIndex":2,"explanation":"Hier streiten zwei Lager nicht über Werte, sondern über eine Tatsachenfrage: Welcher Weg führt tatsächlich zum gemeinsamen Ziel? Gute Absichten sagen nichts darüber, ob eine Methode wirkt. Man kann das Richtige wollen und sich trotzdem über den Weg irren. Sinnvoll ist deshalb, das Ziel als geklärt zu betrachten und die Wege an Fakten und Daten zu messen: Wie haben ähnliche Aktionen auf Spenden, Mitglieder und öffentliche Meinung gewirkt? Erst dann lässt sich begründet entscheiden. Über den Wert streiten die Lager nicht, denn beide wollen weniger Tierleid; eine Wertedebatte klärt also nichts. Wer die Motive vergleicht, ersetzt die Faktenprüfung durch Selbstvergewisserung, denn lautere Absichten sagen nicht, welche Methode wirkt. Ein Mittelweg ist keine Prüfung, weil er nur fragt, wie sich beide Lager treffen, und nicht, was das Ziel erreicht.","coreRule":"⚡ Erst das Ziel klären, dann die Wege an den Fakten messen.","beleg":"Werkstück B.21 (Anti-Denkmuster; Verbindungen: Stahlmann-Argument)","status":"entwurf","kurz":"Beide wollen weniger Tierleid, der Streit geht also darum, welcher Weg das Ziel erreicht. Das ist eine Tatsachenfrage, die sich an Daten messen lässt. Gute Absichten allein sagen nicht, ob eine Methode wirkt.","prueffrage":"Wenn sich herausstellte, dass Blockaden tatsächlich Spenden kosten, würde das etwas an den Absichten von Lager A ändern?","rueckmeldung":[{"option":0,"text":"Offene Beweggründe schaffen Verständnis, und lautere Motive wirken überzeugend. Ob eine Methode das Tierleid tatsächlich mindert, zeigen sie aber nicht. Man kann das Richtige wollen und sich über den Weg irren."},{"option":1,"text":"Die Frage nach den Werten klingt grundlegend, ist hier aber schon beantwortet: Beide Lager wollen weniger Tierleid. Streitig ist allein, welcher Weg dorthin führt, und das klärt keine Wertedebatte."},{"option":3,"text":"Ein Mittelweg verspricht schnellen Frieden, weil beide etwas abgeben. Er fragt aber nur, wie sich die Lager treffen, nicht, was das Ziel erreicht. Ob er wirkt, bliebe unbelegt."}],"familie":"absicht-ist-kein-beleg","fertigkeit":"F2","quellen":[{"typ":"doi","kurz":"Liu, B. S.; Ditto, P. H. (2013): What Dilemma? Moral Evaluation Shapes Factual Belief. Social Psychological and Personality Science 4(3), 316–323","oeffentlich":false,"doi":"10.1177/1948550612456045"},{"typ":"url","kurz":"Dowden, B.: Fallacies. Internet Encyclopedia of Philosophy (Eintrag „Faulty Motives“)","oeffentlich":true,"url":"https://iep.utm.edu/fallacy/","abruf":"2026-10-12"}],"thema":"Zusammenleben","pruefung":{"lauf":"quiz-audit-v3","modell":"claude-sonnet-5-5","datum":"2026-10-13","urteil":"korrigieren","pruefsumme":"bef0ab9cf44b1583"}},{"id":"qx-b2-021","clusterId":"B","werkstueckRef":"B.22","stufe":1,"question":"Was erklärt am besten, warum so viele Menschen nicht erkennen können, ob das Posting ernst gemeint ist?","options":["Ohne erkennbaren Hinweis auf die Absicht lässt sich eine Parodie auf Extremes nicht von echtem Extremismus unterscheiden, der oft ebenso absurd klingt.","Die Leser bewegen sich in Echokammern und kennen den Tonfall anderer Gruppen nicht mehr, weshalb sie Beiträge von dort falsch einordnen.","Die Leser prüfen die Behauptung nicht an Quellen; wer Tauben und Überwachung nachschlägt, erkennt am Ergebnis, ob der Verfasser sie ernst meint.","Der Wahrheitseffekt wirkt: Was man mehrfach liest, hält man eher für wahr, und so wird aus einem Scherz in der Debatte allmählich Ernst."],"correctIndex":0,"explanation":"Ohne Tonfall, Mimik und Körpersprache fehlen im Netz die Signale, an denen man im Gespräch Satire von Ernst unterscheidet. Hinzu kommt: Die Wirklichkeit des Extremismus ist oft so bizarr, dass eine Parodie davon kaum noch abweicht. Deshalb kann dieselbe Aussage für den einen ein Witz und für den anderen aufrichtig sein, und echter Extremismus wird umgekehrt manchmal für Satire gehalten. Ein Beispiel: Die Bewegung „Birds Aren’t Real“ war von Anfang an Satire, wurde aber von Fremden häufig für echte Verschwörungsgläubigkeit gehalten. Die Unsicherheit liegt also im fehlenden Kontext, nicht in einer erkennbaren Gesinnung des Verfassers. Sinnvoll ist deshalb, Kontext und Absicht zu prüfen, statt vorschnell nach dem eigenen Eindruck zu urteilen. Eine Echokammer würde gleichgesinnte Leser voraussetzen, hier streiten aber beide Lager im selben Thread. Ein Quellenabgleich zeigt nur, dass Tauben keine Drohnen sind, was für Ernst und Scherz gleichermaßen gilt. Und für den Wahrheitseffekt müsste der Beitrag wiederholt auftauchen, wovon hier nichts steht.","coreRule":"⚡ Ohne klaren Hinweis auf die Absicht lässt sich Satire über Extremes nicht verlässlich von echtem Extremismus unterscheiden: Prüfe Kontext und Absicht, statt nur nach deinem Eindruck zu urteilen.","beleg":"Werkstück B.22 (Kernidee; Analyse); Fn. gl-b-poe (Nathan Poe 2005; Aikin 2013)","status":"entwurf","scenario":"Auf einer Social-Media-Plattform erscheint der Beitrag: „Alle Tauben sind Überwachungsdrohnen der Regierung. Wer das noch bezweifelt, ist naiv.“ Kein Emoji, kein Hinweis auf Ironie, keine Angabe zum Autor. Unter dem Beitrag streiten sich die Leute: Ein Teil stimmt empört zu, ein anderer Teil lacht über den vermeintlichen Witz. Eine Person fragt: „Ist das ernst gemeint oder Satire?“ Niemand kann es sicher sagen.","kurz":"Im Netz fehlen Tonfall und Mimik, und echter Extremismus ist oft so bizarr, dass Parodie und Ernst kaum auseinanderfallen. Wer nur den eigenen Eindruck urteilen lässt, verwechselt die fehlende Information mit einer erkennbaren Absicht.","prueffrage":"Was an diesem Beitrag, außerhalb seines Wortlauts, würde etwas über die Absicht des Verfassers verraten?","rueckmeldung":[{"option":1,"text":"Echokammern gibt es, und sie verzerren manchmal den Blick auf andere Gruppen. Hier streiten aber beide Lager im selben Thread. Das Problem liegt im fehlenden Kontext des Beitrags, nicht im unbekannten Tonfall fremder Gruppen."},{"option":2,"text":"Quellen zu prüfen ist grundsätzlich klug. Der Abgleich zeigt hier aber nur, dass Tauben keine Drohnen sind, und das gilt für Scherz und Ernst gleichermaßen. Über die Absicht des Verfassers sagt er nichts."},{"option":3,"text":"Den Wahrheitseffekt gibt es: Wiederholtes wirkt vertrauter und damit glaubwürdiger. Er setzt aber mehrfaches Lesen voraus, wovon hier nichts steht, und er erklärt, was man für wahr hält, nicht ob etwas ernst gemeint ist."}],"familie":"satire-oder-ernst","fertigkeit":"F1","quellen":[{"typ":"url","kurz":"Wikipedia: Poe's law","oeffentlich":true,"url":"https://en.wikipedia.org/wiki/Poe%27s_law","abruf":"2026-10-12"},{"typ":"url","kurz":"TED (2023): How to Be a Better Human – Do we have something to learn from conspiracy theories? (w/ Peter McIndoe), Transkript","oeffentlich":true,"url":"https://www.ted.com/podcasts/how-to-be-a-better-human/do-we-have-something-to-learn-from-conspiracy-theories-w-peter-mcindoe-transcript","abruf":"2026-10-12"},{"typ":"doi","kurz":"Aikin, S. F. (2013): Poe's Law, group polarization, and argumentative failure in religious and political discourse. Social Semiotics 23(3), 301–317","oeffentlich":false,"doi":"10.1080/10350330.2012.719728"}],"thema":"Netz und Medien","pruefung":{"lauf":"quiz-audit-v3","modell":"claude-sonnet-5-5","datum":"2026-10-13","urteil":"ok","pruefsumme":"5119ef9fae6d5636"}},{"id":"qx-b2-022","clusterId":"B","werkstueckRef":"B.22","stufe":2,"question":"Was ist an dieser Schlussfolgerung fehlerhaft?","options":["Aus der Größe der Menge folgt nicht, dass die Menschen glauben, was auf den Schildern steht; sie könnten mitspielen, der Auftritt allein beweist es nicht.","Aus der Größe der Menge folgt nicht, dass die Behauptung auf den Schildern stimmt; was viele vertreten, ist nicht deshalb wahr (Argumentum ad populum).","Die Zeitung gibt die Behauptung der Bewegung verzerrt wieder und widerlegt eine überzogene Fassung, statt die tatsächliche Aussage zu prüfen (Strohmann).","Die Zeitung schließt von den Teilnehmern einer Kundgebung auf die ganze Bevölkerung, obwohl Kundgebungsbesucher eine besondere Auswahl sind (Selektionsverzerrung)."],"correctIndex":0,"explanation":"Von außen sehen Ernst und Spiel gleich aus: Wer ein Schild hochhält, kann glauben, was darauf steht, oder die Rolle des Gläubigen bewusst spielen. Genau so war es bei der Bewegung „Birds Aren’t Real“: Ihr Gründer Peter McIndoe gab 2021 öffentlich zu, dass sie von Anfang an Satire war, und viele der jungen Leute auf den Kundgebungen kannten den Witz und spielten die Gläubigen nur. Wer allein aus Auftritt und Menge auf aufrichtigen Glauben schließt, behandelt eine Möglichkeit als Tatsache. Solange keine Hinweise auf die Absicht vorliegen, ist die ehrliche Antwort Unsicherheit und der nächste Schritt eine Prüfung des Kontexts. Die Zeitung hält die Behauptung auf den Schildern gar nicht für wahr, sondern für Wahn, ein Schluss von der Menge auf die Wahrheit liegt also nicht vor. Sie gibt die Behauptung unverändert wieder, ein Strohmann liegt also nicht vor. Sie spricht auch nur über die Teilnehmer und nicht über die ganze Bevölkerung, deshalb trifft der Vorwurf der Verallgemeinerung nicht.","coreRule":"⚡ Wo Satire und Ernst gleich klingen, entscheidet nur der Kontext der Absicht.","beleg":"Werkstück B.22 (Eingangsszene); Fn. gl-b-birds (Lorenz 2021, New York Times, 9.12.2021; McIndoe im TED-Podcast 24.07.2023; NPR 08.12.2023)","status":"entwurf","scenario":"Eine Bewegung behauptet auf Schildern, alle Vögel seien von der Regierung durch Überwachungsdrohnen ersetzt worden. Zu ihren Kundgebungen kommen Hunderte junge Leute. Eine Zeitung schreibt: „Hunderte Menschen glauben ernsthaft, dass es keine echten Vögel gibt. So weit ist der Verschwörungswahn gekommen.“","quote":"","quoteLabel":"","kurz":"Wer ein Schild hochhält, kann glauben, was darauf steht, oder den Gläubigen nur spielen; von außen sieht beides gleich aus. Die Zeitung behandelt eine Möglichkeit als Tatsache, statt zuerst den Kontext zu prüfen.","prueffrage":"Was genau hat die Zeitung gesehen, und was davon verrät, was in den Köpfen der Teilnehmenden vorgeht?","rueckmeldung":[{"option":1,"text":"Dass Verbreitung allein nichts beweist, stimmt. Die Zeitung hält die Behauptung aber gar nicht für wahr, sondern für Wahn. Ein Schluss von der Menge auf die Wahrheit liegt hier also nicht vor."},{"option":2,"text":"Ein Strohmann setzt eine verzerrte Wiedergabe voraus. Die Zeitung gibt die Behauptung der Schilder aber unverändert wieder. Der Fehler liegt woanders: im Schluss auf aufrichtigen Glauben."},{"option":3,"text":"Kundgebungsbesucher sind tatsächlich keine Zufallsauswahl. Die Zeitung spricht aber nur über die Teilnehmer und verallgemeinert nicht auf die Bevölkerung. Der Fehler liegt daher nicht in einer Verallgemeinerung."}],"familie":"satire-oder-ernst","fertigkeit":"F1","quellen":[{"typ":"url","kurz":"Wikipedia: Birds Aren't Real","oeffentlich":true,"url":"https://en.wikipedia.org/wiki/Birds_Aren%27t_Real","abruf":"2026-10-12"},{"typ":"url","kurz":"TED (2023): How to Be a Better Human – Peter McIndoe, Transkript","oeffentlich":true,"url":"https://www.ted.com/podcasts/how-to-be-a-better-human/do-we-have-something-to-learn-from-conspiracy-theories-w-peter-mcindoe-transcript","abruf":"2026-10-12"},{"typ":"literatur","kurz":"Lorenz, T. (2021): Birds Aren't Real, or Are They? Inside a Gen Z Conspiracy Theory. The New York Times, 9.12.2021","oeffentlich":false}],"thema":"Netz und Medien","pruefung":{"lauf":"quiz-audit-v3","modell":"claude-sonnet-5-5","datum":"2026-10-13","urteil":"ok","pruefsumme":"3ba05b01ec33ac9b"}},{"id":"qx-b2-023","clusterId":"B","werkstueckRef":"B.22","stufe":3,"question":"Ein Mitglied der Gruppe sagt: „Das war doch nur ein Witz, versteht ihr keinen Spaß?“ Was ist an dieser Verteidigung als Beweis dafür, dass die Memes harmlos sind, fehlerhaft?","scenario":"In einer Online-Gruppe kursieren hasserfüllte Memes. Wird die Gruppe dafür kritisiert, heißt es regelmäßig: „Das war doch nur ein Witz, versteht ihr keinen Spaß?“ Weitere Hinweise auf Ironie, etwa Übertreibung gegen die eigene Position oder eine erkennbare Pointe, gibt es nicht.","options":["Die Verteidigung stützt sich auf eine nicht prüfbare Selbstauskunft, die an der Wirkung nichts ändert: Die Botschaft verbreitet sich, die Verantwortung wird abgelehnt.","Die Verteidigung lenkt ab: Sie verweist auf angebliche Verfehlungen anderer Gruppen, statt auf den Vorwurf einzugehen, dass die Memes Hass verbreiten.","Die Verteidigung beruft sich darauf, dass solche Memes seit Langem üblich seien, und ersetzt damit einen Beleg für ihre Harmlosigkeit durch Tradition.","Die Verteidigung malt aus, dass schon die Kritik an Witzen zwangsläufig zu Zensur und Redeverboten führe, und weicht so dem eigentlichen Vorwurf aus."],"correctIndex":0,"explanation":"Ob etwas Satire ist, entscheidet nicht die nachträgliche Behauptung des Absenders, sondern der Kontext und die erkennbare Absicht des Autors. Online fehlen Tonfall, Mimik und Körpersprache, deshalb sind Ironie und Ernst oft nicht zu trennen (Poe’s Law). Genau das lässt sich ausnutzen: Wer hasserfüllte Memes verbreitet und sich bei Kritik auf „nur ein Witz“ zurückzieht, normalisiert seine Ideologie und lehnt zugleich jede Verantwortung dafür ab. Satire ist ein gesundes Ventil und ein hochentwickeltes soziales Werkzeug, aber der Hinweis „nur ein Witz“ ersetzt weder Kontext noch erkennbare Absicht. Nützliche Prüffragen sind: Gibt es erkennbare Ironiesignale, etwa Emojis oder ein „/s“? Gibt es eine etablierte Gruppe von Menschen, die genau das aufrichtig glaubt? Und was verrät der Kontext über die Absicht des Autors? Die anderen Einwände nennen bekannte Denkfehler, treffen die Verteidigung aber nicht. Mit Verfehlungen anderer Gruppen wird hier nicht abgelenkt. Auch eine Tradition wird nicht als Rechtfertigung angeführt, und von drohender Zensur redet niemand.","coreRule":"⚡ „War nur Spaß“ ist kein Beweis für Satire, sondern oft der Rückzugsraum für Ernst.","beleg":"Werkstück B.22 (Anwendung: politischer Extremismus & Trolle; Kipppunkt)","status":"entwurf","kurz":"„Nur ein Witz“ ist eine Selbstauskunft, die sich nicht prüfen lässt und nichts an der Wirkung ändert. Ob Satire vorliegt, zeigen Kontext und erkennbare Absicht, nicht die nachträgliche Behauptung. Sie lässt die Botschaft stehen und lehnt die Verantwortung ab.","prueffrage":"Welche erkennbaren Signale im Meme selbst zeigen, dass der Autor die Aussage nicht ernst meint?","rueckmeldung":[{"option":1,"text":"Ablenkung durch Hinweise auf andere Gruppen ist ein bekannter Denkfehler, sie kommt in dieser Verteidigung aber nicht vor. Das Mitglied verweist nicht auf andere, sondern beruft sich allein darauf, es sei „nur ein Witz“."},{"option":2,"text":"Auch ein Verweis auf Tradition ersetzt keinen Beleg, nur wird er hier nicht gemacht. Das Mitglied sagt nicht, solche Memes seien seit jeher üblich, sondern erklärt sie nachträglich zum Scherz."},{"option":3,"text":"Das Zensurargument ist ein bekanntes Ausweichmuster, aber hier wird es nicht verwendet. Von Redeverboten spricht niemand, die Verteidigung besteht allein aus dem Hinweis, es sei „nur ein Witz“."}],"familie":"satire-oder-ernst","fertigkeit":"F1","quellen":[{"typ":"url","kurz":"Wikipedia: Poe's law","oeffentlich":true,"url":"https://en.wikipedia.org/wiki/Poe%27s_law","abruf":"2026-10-12"},{"typ":"doi","kurz":"Aikin, S. F. (2013): Poe's Law, group polarization, and argumentative failure in religious and political discourse. Social Semiotics 23(3), 301–317","oeffentlich":false,"doi":"10.1080/10350330.2012.719728"}],"thema":"Netz und Medien","pruefung":{"lauf":"quiz-audit-v3","modell":"claude-sonnet-5-5","datum":"2026-10-13","urteil":"ok","pruefsumme":"5fcbe3bc0e836fb0"}},{"id":"qx-b2-024","clusterId":"B","werkstueckRef":"B.22","stufe":4,"question":"Welches Vorgehen ist hier am sinnvollsten?","scenario":"Eine Kollegin teilt eine unglaubliche Schlagzeile: „Bericht: Bundesregierung will Schulpflicht durch freiwilliges Lernen per App ersetzen“. Du hältst es für einen Scherz, bist dir aber nicht sicher. Auf Nachfrage sagt sie nur: „Klingt doch total plausibel, oder?“","options":["Du wendest das Sparsamkeitsprinzip an, nach dem die einfachere Erklärung meist die bessere ist, und stufst die Meldung deshalb als Scherz ein.","Du prüfst Quelle, Kontext und mögliche Absicht und fragst dich, ob jemand das wirklich ernsthaft vertritt, bevor du dich festlegst.","Du prüfst, wie gut sich eine freiwillige App-Lösung fachlich begründen lässt, und hältst die Meldung für echt, wenn die Idee überzeugend klingt.","Du teilst die Meldung mit dem Vermerk „Quelle unklar“ weiter, damit andere sie gemeinsam einordnen, und wartest ab, wie die Reaktionen ausfallen."],"correctIndex":1,"explanation":"Ob ein Text ernst oder ironisch gemeint ist, lässt sich aus dem Inhalt allein oft nicht ablesen. Die Wirklichkeit des Extremismus und des Verschwörungsglaubens ist mitunter bizarrer als jede Parodie, und Satire-Seiten werden regelmäßig für echte Nachrichten gehalten. „Zu abwegig, um ernst zu sein“ ist deshalb kein sicherer Schluss, auch nicht über das Sparsamkeitsprinzip: Es setzt voraus, dass man Erklärungen an Belegen vergleichen kann, und die fehlen hier noch. Ob eine Idee fachlich überzeugt, sagt nichts darüber, ob jemand sie wirklich vertritt oder ob die Meldung echt ist; das ist eine Frage nach der Herkunft. Eine ungeprüfte Schlagzeile mit Vorbehalt weiterzuteilen, verbreitet sie, bevor die Frage geklärt ist. Verlässlich ist der Blick auf Quelle, Kontext und Absicht und die Frage, ob eine reale Gruppe genau das aufrichtig glaubt.","coreRule":"⚡ Absurdität allein entscheidet nicht über Satire; Kontext und Quelle tun es.","quote":"Unabhängig davon, ob ich das persönlich für einen Witz halte: Gibt es eine etablierte Gruppe von Menschen, die genau das aufrichtig glaubt? Bevor ich reagiere, sollte ich den Kontext und die Absicht des Autors prüfen.","quoteLabel":"Beispielgedanke:","beleg":"Werkstück B.22 (Anti-Denkmuster; Red Flags; Anwendung: Fake News & Satire)","status":"entwurf","kurz":"Ob eine Meldung ernst gemeint ist, verrät ihr Inhalt allein oft nicht, denn Wirklichkeit und Parodie sind mitunter kaum zu trennen. Verlässlich ist der Blick auf Quelle, Kontext und Absicht, nicht das Gefühl, etwas sei zu abwegig.","prueffrage":"Woran hast du bisher festgemacht, dass es ein Scherz sein könnte, und wie sicher ist dieses Zeichen?","rueckmeldung":[{"option":0,"text":"Die einfachere Erklärung zu bevorzugen klingt nüchtern. Dafür müsste man Erklärungen aber an Belegen vergleichen können, und die fehlen noch; „zu abwegig“ ist kein Beleg, da die Wirklichkeit mitunter bizarrer ist als jede Parodie."},{"option":2,"text":"Eine Idee kann fachlich gut begründbar sein, und das zu prüfen ist nicht verkehrt. Es sagt aber nichts darüber, ob die Meldung echt ist oder jemand sie wirklich vertritt; das ist eine Frage nach der Herkunft."},{"option":3,"text":"Der Vermerk „Quelle unklar“ ist ehrlich gemeint und besser als gar kein Hinweis. Trotzdem verbreitest du die Schlagzeile, bevor ihre Herkunft geklärt ist, und überlässt anderen die Prüfung."}],"familie":"satire-oder-ernst","fertigkeit":"F1","quellen":[{"typ":"url","kurz":"Wikipedia: Poe's law","oeffentlich":true,"url":"https://en.wikipedia.org/wiki/Poe%27s_law","abruf":"2026-10-12"},{"typ":"doi","kurz":"Aikin, S. F. (2013): Poe's Law, group polarization, and argumentative failure in religious and political discourse. Social Semiotics 23(3), 301–317","oeffentlich":false,"doi":"10.1080/10350330.2012.719728"}],"thema":"Netz und Medien","pruefung":{"lauf":"quiz-audit-v3","modell":"claude-sonnet-5-5","datum":"2026-10-13","urteil":"korrigieren","pruefsumme":"558d9220d1ec75cb"}},{"id":"qx-b2-025","clusterId":"B","werkstueckRef":"B.23","stufe":1,"question":"Welcher Denkfehler steckt im Schluss des Moderators?","options":["Er nimmt an, die Wahrheit liege in der Mitte, obwohl die beiden Seiten unterschiedlich gut belegt sind (Mittelweg-Trugschluss).","Er hält die Aussage der Ozeanografin allein wegen ihres Fachtitels für wahr, obwohl ein Titel noch kein Beleg ist (Autoritätsargument).","Er hält eine der Aussagen für wahr, weil viele Menschen sie glauben, obwohl Verbreitung nichts beweist (Appell an die Menge).","Er verzerrt die Aussagen beider Seiten zu angreifbaren Ersatzbehauptungen, die so niemand vertreten hat (Strohmann)."],"correctIndex":0,"explanation":"Die Ozeanografin stützt sich auf Messdaten, der Gast nur auf Internetrecherchen ohne belastbare Fakten. Der Moderator wendet eine Kompromiss-Heuristik an, die bei Geschmacksfragen oft taugt (Kino oder Theater? Dann eben ein gemeinsames Abendessen), und überträgt sie auf eine Tatsachenfrage. Die Realität ist aber nicht verpflichtet, zwischen einer belegten und einer unbelegten Aussage zu liegen. Wenn eine Seite erdrückende Belege hat und die andere keine, liegt die Wahrheit bei den Belegen, nicht in der Mitte. Die anderen Gedanken nennen bekannte Fehler, die der Moderator aber nicht begeht. Er beruft sich weder auf einen Titel noch auf die Zahl der Anhänger. Und er gibt beide Aussagen unverzerrt wieder, ohne sie zu Ersatzbehauptungen umzudeuten.","coreRule":"⚡ Die Wahrheit liegt bei den Beweisen, nicht automatisch in der Mitte.","beleg":"Werkstück B.23 (Eingangsszene Ozean/Gin; Kernidee; Analyse; Fußnoten: keine). Frage vom Definitionsabruf zur Fehlererkennung am konkreten Fall umgebaut.","status":"entwurf","scenario":"In einer Podiumsdiskussion sagt eine Ozeanografin: „Nach allen verfügbaren Messdaten ist der Ozean mit Wasser gefüllt.“ Ein Gast widerspricht: „Nach meinen Recherchen im Internet ist der Ozean mit reinem Gin gefüllt.“ Der Moderator fasst zusammen: „Zwei extreme Positionen. Die Wahrheit liegt wohl in der Mitte. Der Ozean ist also eine Art verdünnter Martini.“","kurz":"Wo die eine Seite belegt ist und die andere nicht, liegt die Wahrheit bei den Belegen. Der Moderator übertrug einen Kompromiss, der bei Geschmacksfragen oft taugt, auf eine Tatsachenfrage, bei der die Realität nicht zwischen zwei Aussagen liegen muss.","prueffrage":"Worauf stützt sich jede der beiden Aussagen, und wie gut lässt sich das jeweils nachprüfen?","rueckmeldung":[{"option":1,"text":"Die Ozeanografin kommt im Schluss des Moderators vor, doch er ordnet ihre Aussage weder wegen ihres Titels als wahr ein noch bevorzugt er sie. Er setzt beide Seiten gleich. Das Problem liegt daher nicht in übertriebenem Vertrauen in einen Titel."},{"option":2,"text":"Davon, dass viele Menschen eine der Aussagen glauben, ist weder im Szenario noch im Schluss etwas zu finden. Der Moderator zählt keine Anhänger, er mittelt zwei Aussagen. Mit der Verbreitung einer Aussage hat sein Fehler nichts zu tun."},{"option":3,"text":"Ein absurdes Ergebnis wie „verdünnter Martini“ lässt vermuten, dass hier etwas verzerrt wurde. Der Moderator nennt beide Aussagen aber korrekt, als „zwei extreme Positionen“. Absurd wird erst sein Schluss daraus, nicht seine Wiedergabe."}],"familie":"gewicht-statt-redezeit","fertigkeit":"F2","quellen":[{"typ":"url","kurz":"Wikipedia: Argument to moderation","oeffentlich":true,"url":"https://en.wikipedia.org/wiki/Argument_to_moderation","abruf":"2026-10-12"},{"typ":"url","kurz":"Dowden, B.: Fallacies. Internet Encyclopedia of Philosophy (Eintrag „False Balance“)","oeffentlich":true,"url":"https://iep.utm.edu/fallacy/","abruf":"2026-10-12"},{"typ":"literatur","kurz":"Harker, D. (2015): Creating Scientific Controversies: Uncertainty and Bias in Science and Society. Cambridge University Press","oeffentlich":false}],"thema":"Netz und Medien","pruefung":{"lauf":"quiz-audit-v3","modell":"claude-sonnet-5-5","datum":"2026-10-13","urteil":"ok","pruefsumme":"9a89aaa001873a20"}},{"id":"qx-b2-026","clusterId":"B","werkstueckRef":"B.23","stufe":2,"question":"Zwei Menschen streiten und sollen sich einigen. In welchem der folgenden Fälle ist ein Mittelweg eine vernünftige, pragmatische Lösung?","options":["Zwei Gutachten kommen zu entgegengesetzten Ergebnissen: Das eine hält eine Brücke für standsicher, das andere nicht. Als Ergebnis wird ein Mittelwert beider Aussagen festgelegt.","Bei einer Verhandlung will die eine Seite ein Feuer löschen, die andere es anfachen. Als Kompromiss lässt man das halbe Haus abbrennen.","Beim Streit darüber, ob ein Impfstoff wirkt, wird ein Teil der Daten übernommen und ein Teil verworfen, bis beide Seiten zufrieden sind.","Eine Freundin will ins Kino, ein Freund ins Theater. Sie verbringen den Abend mit einem gemeinsamen Essen, das beiden recht ist."],"correctIndex":3,"explanation":"Ein Mittelweg taugt dort, wo es um Vorlieben geht und beide Seiten ein gemeinsames Ziel haben, nämlich einen schönen gemeinsamen Abend. Dann ist ein Kompromiss tatsächlich eine gute, pragmatische Lösung. Bei den anderen Fällen geht es um Tatsachen oder um grundsätzlich entgegengesetzte Ziele. Ob eine Brücke hält oder ein Impfstoff wirkt, lässt sich nicht aushandeln, das entscheiden Messungen und Daten. Der Wert zwischen „sicher“ und „unsicher“ ist kein Ergebnis, sondern ein Unsinn. Und wer das Feuer löschen will und wer es legen will, hat kein gemeinsames Ziel: Das halbe Haus abbrennen zu lassen, wäre ein voller Sieg für den Brandstifter. Die Mitte zwischen einer gut belegten Aussage und einer unbelegten ist nicht automatisch wahr; die Wahrheit liegt dort, wo die Belege liegen.","coreRule":"⚡ Kompromisse gehören in die Welt der Präferenzen, nicht in die Welt der Tatsachen.","beleg":"Werkstück B.23 (Kontext & Tiefe; Der Kipppunkt)","status":"entwurf","scenario":"","quote":"","quoteLabel":"","kurz":"Ein Mittelweg trägt, wenn es um Vorlieben geht und beide dasselbe Ziel haben, hier einen guten gemeinsamen Abend. Bei Tatsachen oder gegensätzlichen Zielen taugt die Mitte nicht automatisch: Dort zählen Belege, nicht der Kompromiss.","prueffrage":"Was hätte jede Seite in den einzelnen Fällen nach der Einigung, und wäre danach etwas falsch oder gefährlich?","rueckmeldung":[{"option":0,"text":"Wenn Gutachten sich widersprechen, braucht es eine Entscheidung, und ein Mittelwert wirkt wie ein Ausgleich. Ob eine Brücke hält, entscheiden aber Berechnung und Messung, und ein Wert zwischen „sicher“ und „unsicher“ bedeutet nichts."},{"option":1,"text":"Dass jede Seite etwas bekommt, klingt nach fairem Kompromiss. Beide verfolgen hier aber entgegengesetzte Ziele, und das halbe Haus abbrennen zu lassen, wäre ein voller Erfolg für den, der das Feuer anfachen will."},{"option":2,"text":"Wenn beide Seiten zufrieden sind, scheint der Streit gelöst. Ob ein Impfstoff wirkt, ist aber eine Tatsachenfrage, die die Daten entscheiden, und ein Ergebnis nach Zufriedenheit der Streitenden sagt darüber nichts aus."}],"familie":"gewicht-statt-redezeit","fertigkeit":"F2","quellen":[{"typ":"url","kurz":"Wikipedia: Argument to moderation","oeffentlich":true,"url":"https://en.wikipedia.org/wiki/Argument_to_moderation","abruf":"2026-10-12"}],"thema":"Zusammenleben","pruefung":{"lauf":"quiz-audit-v3","modell":"claude-sonnet-5-5","datum":"2026-10-13","urteil":"korrigieren","pruefsumme":"21c1513485a9af3c"}},{"id":"qx-b2-027","clusterId":"B","werkstueckRef":"B.23","stufe":3,"question":"In einer Schlichtung schlägt jemand vor: „Der Brandstifter will, dass das Haus brennt, die Feuerwehr will es löschen – einigen wir uns darauf, dass nur das halbe Haus abbrennt.“ Was ist an diesem Vorschlag das Kernproblem?","options":["Der Vorschlag lässt offen, wie die Einigung durchgesetzt wird: Ohne Kontrolle kann sich keine Seite darauf verlassen, dass die andere sie einhält.","Der Vorschlag tut so, als lägen beide Ziele auf derselben Waage, obwohl sie gegensätzlich sind: Das halbe Haus zu opfern wäre für eine Seite ein voller Sieg.","Der Vorschlag mittelt zwischen zwei Tatsachenbehauptungen, obwohl sich Tatsachen nicht aushandeln lassen: Ob etwas stimmt, entscheiden allein Belege.","Der Vorschlag übersieht ein Machtgefälle zwischen den Seiten: Die mächtigere könnte ihr Ziel auch ohne jede Einigung gegen die andere durchsetzen."],"correctIndex":1,"explanation":"Ein Kompromiss ist nur sinnvoll, wenn die Positionen symmetrisch genug sind. Hier sind die Ziele grundlegend asymmetrisch: Das eine Ziel ist, dass nichts brennt, das andere, dass es brennt. „Das halbe Haus“ klingt nach Mitte, wäre aber ein kompletter Sieg für den Brandstifter und eine komplette Niederlage für die Feuerwehr. Die Mitte zwischen zwei Positionen ist also nicht automatisch die vernünftigste Lösung, sondern kann ein Ergebnis sein, das nur einer Seite nützt. Man kann drei Arten von Asymmetrie unterscheiden: Fakten, Ziele und Macht. Vor einem Kompromiss lohnt die Prüfung, ob die Positionen symmetrisch genug sind. Die anderen Gedanken sind für sich sinnvoll, treffen aber nicht den Kern. Hier wird keine Tatsache ausgehandelt, sondern es stehen sich gegensätzliche Ziele gegenüber. Von einem Machtgefälle ist nirgends die Rede, und wie man eine Einigung durchsetzt, wäre erst die Frage nach einem sinnvollen Kompromiss.","coreRule":"⚡ Prüfe vor jedem Kompromiss, ob die Ziele überhaupt auf derselben Waage liegen.","beleg":"Werkstück B.23 (Das Problem der Asymmetrie; Kipppunkt)","status":"entwurf","scenario":"","kurz":"Zwischen „es brennt“ und „es brennt nicht“ gibt es keine neutrale Mitte: Das halbe Haus wäre für den Brandstifter ein voller Sieg und für die Feuerwehr eine volle Niederlage. Ein Kompromiss trägt nur, wenn die Positionen symmetrisch genug sind.","prueffrage":"Was genau will die Feuerwehr erreichen, und was genau der Brandstifter?","rueckmeldung":[{"option":0,"text":"Ohne Kontrolle wäre eine Einigung tatsächlich brüchig, das ist eine berechtigte Sorge. Sie käme aber erst danach: Auch eine lückenlos eingehaltene Halbierung wäre ein Sieg des Brandstifters, der Fehler steckt schon im Vorschlag selbst."},{"option":2,"text":"Dass sich Tatsachen nicht aushandeln lassen, stimmt, passt hier aber nicht. Niemand streitet darüber, was der Fall ist, sondern darüber, was geschehen soll. Es treffen gegensätzliche Ziele aufeinander, keine widersprüchlichen Behauptungen über Fakten."},{"option":3,"text":"Ein Machtgefälle kann einen Kompromiss tatsächlich entwerten, im Szenario ist davon aber nichts zu lesen. Auch zwischen gleich starken Seiten bliebe der Vorschlag verzerrt, weil schon die Ziele nicht auf einer Skala liegen."}],"familie":"gewicht-statt-redezeit","fertigkeit":"F2","quellen":[{"typ":"url","kurz":"Wikipedia: Argument to moderation","oeffentlich":true,"url":"https://en.wikipedia.org/wiki/Argument_to_moderation","abruf":"2026-10-12"}],"thema":"Zusammenleben","pruefung":{"lauf":"quiz-audit-v3","modell":"claude-sonnet-5-5","datum":"2026-10-13","urteil":"ok","pruefsumme":"ad41b2fc4baefb34"}},{"id":"qx-b2-028","clusterId":"B","werkstueckRef":"B.23","stufe":4,"question":"Was ist an dem Schluss der Zuschauerin fehlerhaft, und was hat die Sendung damit zu tun?","scenario":"Eine Talkshow lädt zur Klimafrage eine Klimawissenschaftlerin und einen Leugner ein, beide mit exakt gleichen Redeanteilen. Eine Zuschauerin sagt danach: „Dann liegt die Wahrheit wohl irgendwo dazwischen. Ganz so schlimm wird es nicht, aber ein bisschen was ist vielleicht dran.“","options":["Die Sendung prägt die Zuschauerin durch ständiges Wiederholen derselben Botschaft, und sie hält das Vertraute für wahr (Wahrheitseffekt).","Die Sendung erzeugt den Anschein gleichwertiger Seiten, und die Zuschauerin löst die ungleiche Beweislage als Mittelweg auf (Mittelweg-Trugschluss).","Die Sendung setzt mit der Reihenfolge der Redebeiträge einen Anker, und die Zuschauerin orientiert sich am zuerst Gehörten (Ankereffekt).","Die Sendung zeigt den Leugner als Außenseiter, und die Zuschauerin lässt sich vom Mitleid mit ihm leiten (Appell an das Mitleid)."],"correctIndex":1,"explanation":"Die gleichwertige Darstellung beider Seiten erzeugt den Eindruck, beide Positionen stünden auf gleich festem Boden. Wer diesen Eindruck übernimmt, rechnet die Positionen zu einem „vernünftigen“ Kompromiss zusammen. Bei Tatsachenfragen gibt es aber keine Pflicht der Wirklichkeit, zwischen einer gut belegten Aussage und einer durch gar keine Beweise gestützten zu liegen. Der Schluss auf die Mitte ist hier ein Trugschluss, weil er die ungleiche Beweislage ignoriert. Und die Sendung hängt damit zusammen, weil die Darstellung als gleichwertig diesen Schluss nahelegt. Zugleich bleibt der Mittelweg bei Geschmacks- und Interessenfragen oft vernünftig. Entscheidend ist, die Positionen vorher nach Belegen zu gewichten, statt sie als gleichwertig zu behandeln. Die anderen Wirkmechanismen gibt es durchaus, sie passen aber nicht zu dieser Sendung. Von ständigen Wiederholungen oder einer Reihenfolge der Beiträge ist keine Rede. Und die Zuschauerin urteilt nicht aus Mitleid, sondern rechnet die beiden Aussagen zu einer Mitte zusammen.","coreRule":"⚡ Gleich viel Redezeit heißt nicht gleich viel Belege.","beleg":"Werkstück B.23 (Anwendung: Journalismus; Verbindungen: Falsche Ausgewogenheit)","status":"entwurf","kurz":"Gleiche Redeanteile lassen beide Seiten gleich gut belegt wirken, und die Zuschauerin mittelt sie zu einem Kompromiss. Bei Tatsachenfragen muss die Wahrheit aber nicht in der Mitte liegen, wenn die Beweislage ungleich ist.","prueffrage":"Wie viel Redezeit bekam jede Seite, und entspricht das dem Anteil der Fachleute, die jeweils so urteilen?","rueckmeldung":[{"option":0,"text":"Wiederholte Botschaften können tatsächlich Vertrautes wahr wirken lassen. Im Szenario aber hört die Zuschauerin eine einzelne Sendung; von Wiederholung ist keine Rede. Ihr Schluss entsteht, weil sie beide Aussagen zu einer Mitte verrechnet."},{"option":2,"text":"Eine Reihenfolge kann als Anker wirken, doch im Szenario ist nur von gleichen Redeanteilen die Rede, nicht davon, wer zuerst sprach. Die Zuschauerin folgt auch keinem ersten Eindruck, sondern setzt beide Seiten gleich und mittelt sie."},{"option":3,"text":"Mitleid kann Urteile lenken und eine Außenseiterrolle es begünstigen. Im Szenario zeigt aber nichts, dass der Leugner so dargestellt wird oder die Zuschauerin Mitgefühl hat. Ihr Schluss kommt aus dem Gleichgewicht der Seiten, nicht aus einem Gefühl."}],"familie":"gewicht-statt-redezeit","fertigkeit":"F2","quellen":[{"typ":"url","kurz":"Dowden, B.: Fallacies. Internet Encyclopedia of Philosophy (Eintrag „False Balance“)","oeffentlich":true,"url":"https://iep.utm.edu/fallacy/","abruf":"2026-10-12"},{"typ":"url","kurz":"Northwestern University, SESP Magazine (Sommer 2022): The Perils of Bothsidesism","oeffentlich":true,"url":"https://sesp.northwestern.edu/magazine/summer-2022/the-perils-of-bothsidesism.html","abruf":"2026-10-12"},{"typ":"literatur","kurz":"Imundo, M. N.; Rapp, D. N. (2022): When Fairness is Flawed: Effects of False Balance Reporting and Weight-of-Evidence Statements on Beliefs and Perceptions of Climate Change. Journal of Applied Research in Memory and Cognition","oeffentlich":false}],"thema":"Netz und Medien","pruefung":{"lauf":"quiz-audit-v3","modell":"claude-sonnet-5-5","datum":"2026-10-13","urteil":"korrigieren","pruefsumme":"b9a28f4d20e0bdf4"}},{"id":"qx-b2-029","clusterId":"B","werkstueckRef":"B.24","stufe":1,"question":"Was ist an dieser Erklärung der Reporterin am ehesten fehlerhaft?","options":["Sie führt ein Geschehen mit vielen zusammenwirkenden Ursachen auf einen einzigen Schuldigen zurück und lässt die übrigen Faktoren unbeachtet (monokausaler Fehlschluss).","Sie schließt aus dem zeitlichen Zusammentreffen zweier Ereignisse auf einen ursächlichen Zusammenhang, ohne diesen zu prüfen (post hoc ergo propter hoc).","Sie hält ihre Erklärung allein deshalb für richtig, weil sich das Gegenteil nicht beweisen lässt, und verkehrt so die Beweislast (Argument aus Unwissenheit).","Sie beruft sich auf ihre Rolle als Reporterin und ersetzt damit die Prüfung der Belege durch die Autorität ihres Amtes (Autoritätsargument)."],"correctIndex":0,"explanation":"Ein Unglück wie dieses entsteht in der Regel aus dem Zusammenspiel vieler Faktoren: Materialermüdung, Belastung, Wartung und Wetter greifen ineinander. Die Reporterin reduziert das auf einen einzigen Bösewicht. Das ist leicht zu erzählen und emotional befriedigend, blendet aber alle übrigen Beiträge aus und führt zu einer scheinbar einfachen Lösung, nämlich den Bauleiter auszutauschen. Bleiben Materialermüdung und mangelnde Wartung bestehen, kann die nächste Brücke genauso versagen. Dass der Bauleiter einen Anteil gehabt haben kann, ist damit nicht ausgeschlossen. Der Fehler liegt darin, ihn zur alleinigen Ursache zu erklären. Die anderen Denkfehler gibt es durchaus, sie passen aber nicht zu dieser Aussage. Die Reporterin verknüpft keine zwei bloß gleichzeitigen Ereignisse miteinander. Sie begründet ihre Erklärung auch nicht mit fehlender Widerlegung oder mit ihrem Amt, sondern behauptet einfach eine einzige Ursache.","coreRule":"⚡ Wo viele Faktoren zusammenwirken, ist die Erklärung mit einem einzigen Schuldigen verdächtig. Frag dich: Welche weiteren Faktoren könnten beigetragen haben?","beleg":"Werkstück B.24 (Kernidee; Analyse)","status":"entwurf","scenario":"Nach dem Einsturz einer Brücke sagt eine Reporterin im Fernsehen: „Die Wahrheit ist ganz einfach: Der Bauleiter hat geschlampt, er ist an allem schuld.“ Ein Gutachten nennt zugleich mehrere Faktoren: ein Baumaterial, das über Jahre ermüdet ist, eine Überlastung durch Schwerverkehr, aufgeschobene Wartungsarbeiten und ungewöhnlich starke Regenfälle.","kurz":"Ein Einsturz entsteht meist aus dem Zusammenspiel mehrerer Faktoren, hier Materialermüdung, Belastung, Wartung und Wetter. Die Aussage macht daraus eine einzige Ursache und blendet den Rest aus, obwohl der Bauleiter durchaus einen Anteil gehabt haben kann.","prueffrage":"Wie viele Faktoren nennt das Gutachten, und wie viele davon kommen in der Erklärung der Reporterin vor?","rueckmeldung":[{"option":1,"text":"Post hoc setzt voraus, dass zwei Ereignisse zeitlich zusammenfallen und daraus ein Zusammenhang gefolgert wird. Davon steht in der Aussage nichts: Sie verknüpft keine Ereignisse, sondern nennt einfach eine einzige Ursache."},{"option":2,"text":"Ein Argument aus Unwissenheit würde sich auf fehlende Widerlegung stützen. Die Reporterin begründet aber gar nichts damit, sie behauptet nur. Das Gutachten liefert sogar Gegenbelege, die ihre Aussage übergeht."},{"option":3,"text":"Ihre Rolle als Reporterin dient im Satz nicht als Begründung; sie beruft sich weder auf ein Amt noch auf besondere Sachkenntnis. Die Schwäche liegt im Inhalt der Aussage selbst, nicht darin, wer sie äußert."}],"familie":"monokausal-erkennen","fertigkeit":"F2","quellen":[{"typ":"doi","kurz":"Reason, J. (2000): Human error: models and management. BMJ 320(7237), 768–770","oeffentlich":true,"doi":"10.1136/bmj.320.7237.768","url":"https://pmc.ncbi.nlm.nih.gov/articles/PMC1117770/","abruf":"2026-10-12"},{"typ":"url","kurz":"Dowden, B. H.: Fallacies. Internet Encyclopedia of Philosophy (Einträge „Oversimplification“, „Scapegoating“)","oeffentlich":true,"url":"https://iep.utm.edu/fallacy/","abruf":"2026-10-12"}],"thema":"Zusammenleben","pruefung":{"lauf":"quiz-audit-v3","modell":"claude-sonnet-5-5","datum":"2026-10-13","urteil":"ok","pruefsumme":"5f9aa1c65e598f33"}},{"id":"qx-b2-030","clusterId":"B","werkstueckRef":"B.24","stufe":2,"question":"Welches Merkmal des Prospekts ist das deutlichste Warnzeichen für eine unzulässige Vereinfachung?","scenario":"Ein Prospekt erklärt: „Fast alle Krankheiten haben eine Wurzel: Schlacken im Darm. Unsere Detox-Kur beseitigt sie.“","options":["Es wird keine Studie genannt, die die Aussage stützt, und fehlende Belege sind ein Warnzeichen für bloße Behauptungen ohne Grundlage.","Der Anbieter verdient am Verkauf der Kur, und ein solches Eigeninteresse ist ein Warnzeichen für Interessenkonflikte und einseitige Darstellung.","Sehr verschiedene Krankheiten werden auf eine einzige Wurzelursache zurückgeführt, und dafür wird eine ebenso einfache Lösung verkauft.","Der Begriff „Schlacken“ bleibt undefiniert, und nicht erklärte Begriffe sind ein Warnzeichen für Scheinexaktheit statt echtem Wissen."],"correctIndex":2,"explanation":"Krankheiten haben sehr verschiedene, oft mehrere zusammenwirkende Ursachen. Dass eine einzige „Wurzelursache“ fast alle erklären soll, ist ein typischer monokausaler Fehlschluss. Verdächtig wird es zusätzlich, wenn die Lösung genauso einfach ist wie die Ursache und genau das Produkt ist, das der Prospekt verkauft. Die Reduktion eines vielfältigen Problems auf ein einfaches Ziel ist ein Muster, das man bei komplexen Themen immer prüfen sollte. Die anderen Hinweise sind bei Werbung durchaus berechtigte Warnzeichen, sie betreffen aber andere Probleme als die Vereinfachung. Fehlende Belege und ein Eigeninteresse des Anbieters sprechen für Vorsicht, sagen aber nichts darüber, ob ein vielfältiges Problem auf eine Ursache verkürzt wird. Ein unerklärter Begriff weist auf Scheinexaktheit hin, nicht auf die Vereinfachung selbst.","coreRule":"⚡ Eine Ursache und eine Lösung, beide ganz einfach: bei komplexen Problemen ein Warnsignal.","beleg":"Werkstück B.24 (Anwendung: Pseudomedizin; Red Flags)","status":"entwurf","kurz":"Viele verschiedene Krankheiten sollen eine einzige Wurzel haben, und die Lösung ist genauso einfach und zufällig das verkaufte Produkt. Krankheiten haben oft mehrere zusammenwirkende Ursachen, daher wird hier ein vielfältiges Problem verkürzt.","prueffrage":"Welche Aussage des Prospekts müsste am stärksten belegt sein, damit die Kur hält, was sie verspricht?","rueckmeldung":[{"option":0,"text":"Fehlende Belege sind bei Werbung tatsächlich ein berechtigtes Warnzeichen. Sie sagen aber nur etwas über die Beleglage und nichts darüber, ob ein vielfältiges Problem auf einen einzigen Grund verkürzt wird."},{"option":1,"text":"Dass der Anbieter an der Kur verdient, mahnt zu Vorsicht. Es zeigt aber nicht, ob die Aussage verkürzt: Auch ein eigennütziger Anbieter könnte im Einzelfall richtig liegen. Das Eigeninteresse betrifft ein anderes Problem."},{"option":3,"text":"Ein unerklärter Begriff wie „Schlacken“ kann Scheinexaktheit verraten, und das ist ein berechtigtes Warnzeichen. Es beschreibt aber nur, wie vage der Ausdruck ist, nicht, ob viele Krankheiten auf eine Ursache zurückgeführt werden."}],"familie":"monokausal-erkennen","fertigkeit":"F2","quellen":[{"typ":"url","kurz":"Dowden, B. H.: Fallacies. Internet Encyclopedia of Philosophy (Eintrag „Oversimplification“)","oeffentlich":true,"url":"https://iep.utm.edu/fallacy/","abruf":"2026-10-12"},{"typ":"url","kurz":"NCCIH (National Center for Complementary and Integrative Health): Detoxes and Cleanses: What You Need To Know","oeffentlich":true,"url":"https://www.nccih.nih.gov/health/detoxes-and-cleanses-what-you-need-to-know","abruf":"2026-10-12"}],"thema":"Gesundheit","pruefung":{"lauf":"quiz-audit-v3","modell":"claude-sonnet-5-5","datum":"2026-10-13","urteil":"ok","pruefsumme":"da7237c567da3ccc"}},{"id":"qx-b2-031","clusterId":"B","werkstueckRef":"B.24","stufe":3,"question":"Nach einem Schiffsunglück zeigt eine Untersuchung mehrere zusammenwirkende Ursachen: einen starken Sturm, einen unentdeckten Haarriss im Rumpf, eine Fehlentscheidung des Kapitäns unter Druck, eine unzureichend geschulte Crew und veraltete Rettungsboote. Ein Reeder kündigt an, nur den Kapitän zu entlassen, und erklärt: „Damit ist das Problem gelöst.“ Warum ist dieser Schluss riskant?","options":["Weil die übrigen Ursachen weiter bestehen und auch das nächste Schiff gefährden, selbst wenn der Kapitän ersetzt wird.","Weil der Reeder Kosten und Nutzen der Entlassung nicht gegeneinander abgewogen hat, was vor einer Personalentscheidung ratsam wäre.","Weil eine einzelne Untersuchung zu wenige Fälle umfasst, um verlässliche Schlüsse über Unglücksursachen zu ziehen (zu kleine Stichprobe).","Weil der Reeder dem Kapitän eine böse Absicht unterstellt, obwohl sich aus einer Fehlentscheidung nicht auf Vorsatz schließen lässt."],"correctIndex":0,"explanation":"Der Reeder greift aus mehreren zusammenwirkenden Ursachen eine einzige heraus und behandelt sie als die Lösung. Wer nur dieses einfache Ziel bekämpft, lässt die übrigen Ursachen unangetastet: den Haarriss im Rumpf, die schlecht geschulte Crew, die veralteten Rettungsboote. Das nächste Schiff trägt dann dieselben Risiken. Bei einfachen, technischen Problemen wie einem Wackelkontakt ist die Suche nach der einen Ursache dagegen oft richtig; bei komplexen Systemen mit vielen zusammenwirkenden Faktoren führt sie in die Irre. Eine gute Prüffrage lautet: Welche fünf weiteren, vielleicht weniger offensichtlichen Faktoren könnten ebenfalls zu diesem Ergebnis beigetragen haben? Die anderen Gedanken sind für sich sinnvoll, treffen hier aber nicht das Problem. Eine Kosten-Nutzen-Abwägung betrifft nicht die Frage, ob die Ursachen vollständig erfasst sind. Die Untersuchung hat ihre Ursachen an einem einzelnen Unglück gefunden, und von einer unterstellten Absicht ist nirgends die Rede.","coreRule":"⚡ Wer nur den Sündenbock behandelt, lässt die Ursachen des Problems unangetastet.","beleg":"Werkstück B.24 (Das Geheimnis des Schiffsunglücks; Der Kipppunkt)","status":"entwurf","scenario":"","kurz":"Die Untersuchung nennt mehrere zusammenwirkende Ursachen, doch der Reeder beseitigt nur eine. Haarriss, schwache Schulung und veraltete Rettungsboote bleiben, und das nächste Schiff trägt dieselben Risiken.","prueffrage":"Welche Faktoren, die nichts mit dem Kapitän zu tun haben, tauchen im Untersuchungsbericht noch auf?","rueckmeldung":[{"option":1,"text":"Eine Abwägung vor Personalentscheidungen ist grundsätzlich ratsam. Sie würde aber nur klären, ob sich die Entlassung lohnt, nicht, ob damit alle Ursachen erfasst sind. Genau das ist hier die Lücke."},{"option":2,"text":"Mit Stichproben hat das Szenario nichts zu tun: Die Ursachen wurden an einem einzelnen Unglück gefunden, und es wird nichts über Unglücke allgemein geschlossen. Der Fehler liegt darin, was der Reeder aus dem Befund macht."},{"option":3,"text":"Von böser Absicht ist im Szenario nirgends die Rede; der Reeder entlässt den Kapitän nur. Dass eine Fehlentscheidung nicht auf Vorsatz schließen lässt, stimmt zwar, trifft aber nicht das Problem."}],"familie":"monokausal-erkennen","fertigkeit":"F2","quellen":[{"typ":"doi","kurz":"Reason, J. (2000): Human error: models and management. BMJ 320(7237), 768–770","oeffentlich":true,"doi":"10.1136/bmj.320.7237.768","url":"https://pmc.ncbi.nlm.nih.gov/articles/PMC1117770/","abruf":"2026-10-12"},{"typ":"url","kurz":"Dowden, B. H.: Fallacies. Internet Encyclopedia of Philosophy (Eintrag „Oversimplification“)","oeffentlich":true,"url":"https://iep.utm.edu/fallacy/","abruf":"2026-10-12"}],"thema":"Zusammenleben","pruefung":{"lauf":"quiz-audit-v3","modell":"claude-sonnet-5-5","datum":"2026-10-13","urteil":"korrigieren","pruefsumme":"af8094d54ad6454d"}},{"id":"qx-b2-032","clusterId":"B","werkstueckRef":"B.24","stufe":4,"question":"Welche Prüfung wendest du auf diese Slogans an?","scenario":"Im Wahlkampf heißt es: „Warum geht es uns schlecht? Wegen der Milliardäre!“ Das gegnerische Lager antwortet mit ebenso einfachen Parolen über eine andere Gruppe.","options":["Beide Parolen stützen sich auf scheinbar genaue Zahlen; prüfe, aus welcher Quelle diese Zahlen stammen, wie sie erhoben wurden und ob sie richtig berechnet sind, bevor du ihnen glaubst.","Beide Parolen geben Aussagen anderer Personen verkürzt wieder; prüfe, was diese Personen im ursprünglichen Zusammenhang tatsächlich gemeint haben und ob das Zitat vollständig ist.","Beide Parolen sagen eine künftige Entwicklung voraus; prüfe, wie zuverlässig vergleichbare Vorhersagen in der Vergangenheit eingetroffen sind und welche Annahmen ihnen zugrunde liegen.","Beide Parolen verkürzen ein vielschichtiges Problem auf eine leicht benennbare Gruppe; frag nach weiteren, weniger offensichtlichen Faktoren, die ebenfalls dazu beigetragen haben könnten."],"correctIndex":3,"explanation":"Beide Slogans haben denselben Fehler: Ein vielschichtiges Problem wie wirtschaftliche Not hat selten eine einzige Ursache, sondern entsteht aus dem Zusammenspiel vieler Faktoren. Eine Parole, die eine einzige Gruppe als Schuldige benennt, ist eingängig und emotional befriedigend, aber gerade deshalb verdächtig. Die richtige Prüfung fragt unabhängig von der politischen Richtung, welche weiteren, weniger offensichtlichen Faktoren mitgewirkt haben könnten. Einzelne Akteure können tatsächlich zu einem Problem beitragen, nur selten allein. Die anderen Prüfungen sind in anderer Lage nützlich, passen aber nicht zu diesen Parolen. Sie nennen keine Zahlen, deren Herkunft sich prüfen ließe. Sie zitieren niemanden, dessen Aussage verkürzt sein könnte, und sie machen keine Vorhersage, deren Treffsicherheit man bewerten könnte.","coreRule":"⚡ Eine Erklärung wird nicht dadurch besser, dass sie einen klaren Schuldigen anbietet.","beleg":"Werkstück B.24 (Anwendung: In der Politik; Anti-Denkmuster: Aktivierungs-Frage), keine Fußnoten","status":"entwurf","kurz":"Wirtschaftliche Not hat selten nur eine Ursache, sondern entsteht aus dem Zusammenspiel vieler Faktoren. Eine Parole, die eine einzige Gruppe als schuldig benennt, ist gerade deshalb verdächtig; sinnvoll ist die Frage, welche weiteren Faktoren mitgewirkt haben könnten.","prueffrage":"Was wäre in den Slogans eigentlich zu erklären, und wie viele Ursachen kommen darin vor?","rueckmeldung":[{"option":0,"text":"Zahlen auf Quelle und Berechnung zu prüfen, ist oft hilfreich. Hier gibt es aber nichts dergleichen zu prüfen, denn die Parolen nennen gar keine Zahlen. Ihr Fehler liegt im Schluss auf eine einzige Schuldige."},{"option":1,"text":"Verkürzte Zitate sind eine häufige Falle, und der Zusammenhang einer Aussage lohnt die Nachfrage. Die Parolen zitieren aber niemanden, es gibt also keinen Wortlaut, den man vervollständigen könnte."},{"option":2,"text":"Wie verlässlich frühere Prognosen waren, ist eine gute Frage bei Vorhersagen. Die Parolen erklären aber eine bestehende Lage und sagen nichts Künftiges voraus, sodass dieser Maßstab ins Leere läuft."}],"familie":"monokausal-erkennen","fertigkeit":"F2","quellen":[{"typ":"url","kurz":"Dowden, B. H.: Fallacies. Internet Encyclopedia of Philosophy (Einträge „Oversimplification“, „Scapegoating“, „Bandwagon“)","oeffentlich":true,"url":"https://iep.utm.edu/fallacy/","abruf":"2026-10-12"}],"thema":"Zusammenleben","pruefung":{"lauf":"quiz-audit-v3","modell":"claude-sonnet-5-5","datum":"2026-10-13","urteil":"korrigieren","pruefsumme":"2b26cbc733b67b54"}},{"id":"qx-b2-033","clusterId":"B","werkstueckRef":"B.25","stufe":1,"question":"Welche Frage hilft dir am besten zu erkennen, ob du deine Denkwerkzeuge gerade als Späher oder als Soldat einsetzt?","options":["Habe ich meine Fachbegriffe so erklärt, dass mein Gegenüber sie versteht und dem Gespräch folgen kann?","Wie viel Zeit bleibt uns für das Gespräch, und welche Punkte sind in dieser Zeit am wichtigsten?","Welche Beobachtung würde mich dazu bringen, meine eigene Einschätzung zu ändern, und habe ich danach gesucht?","Wie bleibe ich in der Diskussion ruhig und sachlich, damit das Gespräch nicht in einen Streit abgleitet?"],"correctIndex":2,"explanation":"Dieselben Werkzeuge (Recherche, Logik, Befragung) können der Wahrheitssuche dienen oder dem Gewinnen um jeden Preis. Zwei Anwälte mit identischem Handwerk zeigen das: Anwalt A sammelt auch die Fakten, die seinem Mandanten schaden, baut den stärksten Fall der Gegenseite, um Schwachstellen zu finden, und ist bereit, seine Strategie bei widersprüchlichen Beweisen anzupassen. Anwalt B sucht nur Munition für seine vorgefasste Schlussfolgerung. Wer prüft, welche Beobachtung ihn umstimmen würde und ob er danach gesucht hat, testet genau diese Offenheit für Gegenbeweise; das ist die Haltung des Spähers. Dass du Denkfehler kennst, macht dich noch nicht zum Wahrheitssucher. Entscheidend ist, wofür du die Werkzeuge einsetzt und ob du sie auch auf dich selbst anwendest. Die anderen Fragen sind im Gespräch durchaus nützlich, sagen aber nichts über dein Ziel. Ob dein Gegenüber dich versteht, betrifft die Verständlichkeit. Die Zeit einzuteilen oder ruhig zu bleiben betrifft den Ablauf des Gesprächs, nicht die Frage, ob du die Wahrheit suchst oder gewinnen willst.","coreRule":"⚡ Werkzeuge des Denkens sind neutral: Entscheidend ist, ob du sie auch gegen deine eigene Position richtest.","beleg":"Werkstück B.25 (Eingangsszene; Kernidee); Fn. gl-b-galef (Galef, TEDxPSU 2016; The Scout Mindset 2021)","status":"entwurf","scenario":"Du hast dich intensiv mit logischen Fehlschlüssen beschäftigt. In einer Diskussion über ein Gesundheitsthema fällt dir auf, dass du vor allem darauf achtest, wo dein Gegenüber einen Denkfehler macht. Dein Ziel ist es, die Diskussion zu gewinnen.","kurz":"Ob du dich umstimmen ließest und ob du nach Gegenbeweisen gesucht hast, zeigt dein Ziel. Dass du Denkfehler kennst, macht dich noch nicht zum Wahrheitssucher: Es kommt darauf an, wofür du die Werkzeuge nutzt und ob du sie auch auf dich anwendest.","prueffrage":"Worauf achtest du in dieser Diskussion bisher vor allem, und was soll am Ende dabei herauskommen?","rueckmeldung":[{"option":0,"text":"Verständliche Sprache ist im Gespräch durchaus wertvoll. Sie sagt aber nichts über dein Ziel: Auch jemand, der nur gewinnen will, kann sich sehr klar ausdrücken."},{"option":1,"text":"Zeit einzuteilen und Schwerpunkte zu setzen, hilft dem Ablauf eines Gesprächs. Wer nur gewinnen will, plant das genauso, deshalb verrät die Frage nichts über deine Haltung."},{"option":3,"text":"Ruhig und sachlich zu bleiben, tut jeder Diskussion gut. Es betrifft aber den Ton und nicht das Ziel: Auch mit sachlichem Auftreten lässt sich ausschließlich Munition für die eigene Meinung sammeln."}],"familie":"werkzeuge-gegen-sich-selbst","fertigkeit":"F5","quellen":[{"typ":"url","kurz":"Galef, J. (2016): Why you think you're right -- even if you're wrong. TEDxPSU, Februar 2016 (TED-Seite mit Transkript)","oeffentlich":true,"url":"https://www.ted.com/talks/julia_galef_why_you_think_you_re_right_even_if_you_re_wrong/transcript","abruf":"2026-10-12"},{"typ":"literatur","kurz":"Galef, J. (2021): The Scout Mindset. New York: Portfolio","oeffentlich":false}],"thema":"Psychologie","pruefung":{"lauf":"quiz-audit-v3","modell":"claude-sonnet-5-5","datum":"2026-10-13","urteil":"korrigieren","pruefsumme":"975b5f7367509a1b"}},{"id":"qx-b2-034","clusterId":"B","werkstueckRef":"B.25","stufe":2,"question":"Welche Haltung zeigt sich in dieser Selbstbeobachtung, und was folgt daraus?","scenario":"Du merkst: In Online-Debatten freust du dich vor allem, wenn du den Gegner „besiegt“ hast. Dein Wissen über Denkfehler nutzt du vor allem, um andere zu katalogisieren und abzuwerten. Deine wichtigen Meinungen hast du trotz ständigen Debattierens lange nicht mehr geändert.","options":["Du verteidigst eine feste Position: Das Wissen dient dem Gewinnen und dem Status, und die Gefahr, selbstgerecht zu werden, ist bereits nahe.","Du kartierst die Wirklichkeit sorgfältig: Dass du deine Meinung lange nicht geändert hast, zeigt, dass deine Sicht offenbar stimmt.","Du suchst nach der Wahrheit: Indem du die Fehler anderer sammelst, bleibst du in deinem eigenen Urteil beweglich.","Du schützt dich zu Recht vor Desinformation: Das Abwerten anderer ist eine gesunde Strategie, um klar zu denken."],"correctIndex":0,"explanation":"Wer sich über das Besiegen anderer freut, sein Wissen über Denkfehler vor allem zum Abwerten nutzt und trotz ständiger Debatten nie umdenkt, setzt Werkzeuge des kritischen Denkens als Waffen ein, nicht als Instrumente der Selbstkorrektur. Dass man trotz ständigen Debattierens lange keine wichtige Meinung aufgrund neuer Beweise geändert hat, ist ein Warnzeichen für die Soldaten-Mentalität. Eine lange unveränderte Meinung ist also kein Beleg dafür, dass die eigene Sicht stimmt. Kippt die Liebe zum Recht-Haben über die Liebe zur Wahrheit, wird aus dem Skeptiker ein Dogmatiker mit schärferem Schwert.","coreRule":"⚡ Frag dich bei jedem Denkwerkzeug: Setze ich es ein, um die Wahrheit zu finden, oder um recht zu behalten?","quote":"Benutze ich dieses Werkzeug wie ein Späher oder wie ein Soldat?","quoteLabel":"Prüffrage:","beleg":"Werkstück B.25 (Red Flags; Kipppunkt; Anti-Denkmuster)","status":"entwurf","kurz":"Wer sich über Siege freut, Denkfehler vor allem bei anderen sucht und sich selbst nie korrigiert, nutzt Wissen als Waffe statt als Werkzeug. Dass die eigene Meinung lange gleich blieb, beweist nicht, dass sie stimmt.","prueffrage":"Wie oft hat eine deiner vielen Debatten in letzter Zeit eine deiner wichtigen Meinungen tatsächlich verändert?","rueckmeldung":[{"option":1,"text":"Eine Sicht kann stimmen, ohne dass man sie je ändern musste. Dass sie sich trotz ständigen Debattierens lange nicht verschoben hat, ist aber kein Beleg dafür, sondern passt eher zu einem Verteidigen als zu einem sorgfältigen Prüfen."},{"option":2,"text":"Das Ideal der Wahrheitssuche ist richtig. Fehler anderer zu sammeln zeigt aber nur auf andere und hält das eigene Urteil nicht beweglich; Beweglichkeit zeigt sich darin, dass man tatsächlich umdenkt, und genau das fehlt hier seit Langem."},{"option":3,"text":"Sich vor Desinformation zu schützen ist ein legitimes Ziel. Hier geht es aber um Freude am Besiegen und um Abwerten, und das dient dem Status, nicht dem klaren Denken, das beim Prüfen der eigenen Urteile beginnt."}],"familie":"werkzeuge-gegen-sich-selbst","fertigkeit":"F5","quellen":[{"typ":"url","kurz":"Galef, J. (2016): Why you think you're right -- even if you're wrong. TEDxPSU, Februar 2016 (TED-Seite mit Transkript)","oeffentlich":true,"url":"https://www.ted.com/talks/julia_galef_why_you_think_you_re_right_even_if_you_re_wrong/transcript","abruf":"2026-10-12"},{"typ":"literatur","kurz":"Galef, J. (2021): The Scout Mindset. New York: Portfolio","oeffentlich":false}],"thema":"Netz und Medien","pruefung":{"lauf":"quiz-audit-v3","modell":"claude-sonnet-5-5","datum":"2026-10-13","urteil":"ok","pruefsumme":"252153cc9fdf2905"}},{"id":"qx-b2-035","clusterId":"B","werkstueckRef":"B.25","stufe":4,"question":"Wie gehst du mit diesem Gesprächspartner am besten um?","scenario":"In einem Forum fordert jemand eine „offene Debatte“ zu einer Behauptung, die längst nach allen Regeln der Wissenschaft widerlegt wurde. Er lügt dabei systematisch, stellt deine Argumente verzerrt als Strohmänner dar und besteht darauf, du müsstest als Skeptiker offen bleiben.","options":["Du führst die Debatte so lange weiter, bis er seinen Irrtum öffentlich einräumt und dir in der Sache recht gibt.","Du prüfst die Behauptung immer wieder neu und offen, weil Skepsis verlangt, jede Idee ständig zu hinterfragen.","Du stellst fest, dass er sich nicht an die Bedingungen einer ehrlichen Auseinandersetzung hält, und steigst aus der Debatte aus.","Du bietest einen Mittelweg an, bei dem beide Seiten gleich viel nachgeben und sich in der Mitte treffen."],"correctIndex":2,"explanation":"Offenheit heißt, Behauptungen anhand von Belegen zu prüfen, nicht, jede Idee gleich zu behandeln. Eine Behauptung, die längst nach allen Regeln der Wissenschaft widerlegt wurde, verdient keine erneute offene Prüfung: Eine erneute „offene“ Debatte darüber verschwendet Zeit und ist eine Form der falschen Ausgewogenheit. Wer zudem systematisch lügt und Strohmänner baut, will nicht herausfinden, was stimmt, sondern gewinnen. Hier ist die „offene“ Fortführung der Debatte keine Tugend, sondern Selbstschädigung; darum greift die Ausstiegs-Strategie. Auch ein Mittelweg löst das Problem nicht, denn dein Gegenüber sucht gar nicht die Wahrheit. Der Ausstieg ist daher kein Akt der Engstirnigkeit, sondern eine begründete Entscheidung, die deine Energie schützt.","coreRule":"⚡ Offenheit heißt, Behauptungen ernsthaft zu prüfen, nicht, jedem Debattenpartner unbegrenzt Zeit und Aufmerksamkeit zu schenken.","beleg":"Werkstück B.25 (Die Grenzen der Offenheit; Anti-Denkmuster)","status":"entwurf","kurz":"Eine längst widerlegte Behauptung verdient keine erneute „offene“ Prüfung, und wer systematisch lügt und Strohmänner baut, will gewinnen statt klären. Offenheit heißt nicht, um jeden Preis weiterzudiskutieren; der Ausstieg ist begründet.","prueffrage":"Was ist über die Behauptung selbst längst geklärt, und was hat er bisher mit deinen Argumenten gemacht?","rueckmeldung":[{"option":0,"text":"Hartnäckigkeit klingt nach Standhaftigkeit. Wer aber systematisch lügt und Strohmänner baut, will nicht herausfinden, was stimmt, und wird kaum einlenken. Du würdest nur Zeit und Kraft in eine Debatte stecken, die nicht auf Klärung zielt."},{"option":1,"text":"Skepsis heißt, Behauptungen anhand von Belegen zu prüfen, nicht, jede Idee gleich zu behandeln. Eine längst widerlegte Behauptung immer wieder neu zu öffnen, wäre falsche Ausgewogenheit und keine Offenheit."},{"option":3,"text":"Ein Mittelweg ist oft ein guter Ausgleich, wenn Interessen gegeneinanderstehen. Bei einer Tatsachenfrage gibt es aber keine Mitte zwischen widerlegt und nicht widerlegt. Außerdem sucht dein Gegenüber gar keine Lösung, sondern will gewinnen."}],"familie":"kraefte-und-ausstieg","fertigkeit":"F3","quellen":[{"typ":"doi","kurz":"Grimes, D. R. (2019): A dangerous balancing act. EMBO Reports 20(8), e48706","oeffentlich":true,"doi":"10.15252/embr.201948706","url":"https://pmc.ncbi.nlm.nih.gov/articles/PMC6680130/","abruf":"2026-10-12"},{"typ":"doi","kurz":"Schmid, P.; Schwarzer, M.; Betsch, C. (2020): Weight-of-Evidence Strategies to Mitigate the Influence of Messages of Science Denialism in Public Discussions. Journal of Cognition 3(1), 36","oeffentlich":true,"doi":"10.5334/joc.125","url":"https://pmc.ncbi.nlm.nih.gov/articles/PMC7528676/","abruf":"2026-10-12"}],"thema":"Netz und Medien","pruefung":{"lauf":"quiz-audit-v3","modell":"claude-sonnet-5-5","datum":"2026-10-13","urteil":"ok","pruefsumme":"070df7c706860229"}},{"id":"qx-b2-036","clusterId":"B","werkstueckRef":"B.25","stufe":3,"question":"Was erklärt dieses Verhalten am besten?","scenario":"Jemand wirft in Online-Diskussionen ständig anderen „Strohmann“ und „Zirkelschluss“ vor und kennt viele Fachbegriffe für Denkfehler. Wird aber seine eigene Lieblingsthese kritisiert, tauchen dieselben Fehler in seinen Antworten auf. Er hat seine Ansicht seit Jahren nicht korrigiert, obwohl er täglich debattiert.","options":["Er setzt sein Wissen über Denkfehler als Waffe gegen andere ein, um seine vorgefasste Meinung zu verteidigen, statt es zur Selbstkorrektur zu nutzen.","Er passt sich dem Meinungsklima einer Gruppe an, um dazuzugehören, und übernimmt deren Thesen deshalb ungeprüft, statt eigene Urteile zu bilden.","Er misstraut jeder Behauptung gleichermaßen, auch seinen eigenen, und legt sich deshalb auf kein gefestigtes Urteil fest, weil ihm jede Position fragwürdig erscheint.","Er bewegt sich in einer Echokammer, in der nur Zustimmung vorkommt, und sieht deshalb keine Gegenargumente, mit denen er sich auseinandersetzen müsste."],"correctIndex":0,"explanation":"Der bloße Besitz von Denkwerkzeugen macht niemanden zum wahrheitssuchenden Denker. Die Julia Galef zugeschriebene Unterscheidung beschreibt es so: Wer in der Soldaten-Mentalität denkt, will eine Position verteidigen und nutzt sein Wissen als Waffe. Wer in der Späher-Mentalität denkt, will herausfinden, was tatsächlich stimmt, und prüft zuerst sich selbst. Hier zeigen drei Signale die Soldaten-Haltung: Die Fehlerjagd richtet sich nur nach außen, die eigene These bleibt unangetastet, und trotz täglicher Debatten hat sich über Jahre nichts geändert. Auch kluge Verschwörungsgläubige sind ein typisches Beispiel: Sie werfen anderen Fehlschlüsse vor und begehen dieselben selbst. Das Ziel entscheidet, ob die Werkzeuge der Wahrheit oder der Verteidigung dienen. Die Werkzeuge kippen damit von Instrumenten der Selbstkorrektur zu Instrumenten der Selbstgerechtigkeit. Die anderen Erklärungen beschreiben bekannte Mechanismen, passen aber nicht zu diesem Mann. Er ist nicht skeptisch gegenüber allem, denn seine eigene These verteidigt er hartnäckig. Er debattiert täglich mit Kritikern, lebt also nicht in einer Echokammer, und von einer Gruppe, der er sich anpassen würde, ist keine Rede.","coreRule":"⚡ Wissen über Denkfehler schützt nicht vor ihnen; es verpflichtet zur Selbstprüfung.","beleg":"Werkstück B.25 (Anwendung: Verschwörungs-„Forscher“; Kipppunkt)","status":"entwurf","kurz":"Wissen über Denkfehler macht noch nicht zum Wahrheitssucher: Es kommt darauf an, wozu man es einsetzt. Hier dient es der Verteidigung der eigenen These, nicht der Selbstkorrektur, deshalb erkennt er Fehler nur bei anderen.","prueffrage":"Gegen wen richtet er seine Fehlervorwürfe, und was hat sich nach Jahren täglicher Debatten an seiner eigenen Ansicht verändert?","rueckmeldung":[{"option":1,"text":"Gruppenanpassung ist ein bekannter Mechanismus, im Szenario gibt es aber weder eine Gruppe noch Anpassungsdruck. Er widerspricht ständig anderen und hält eigenständig an seiner Lieblingsthese fest."},{"option":2,"text":"Allgemeines Misstrauen würde auch die eigene These treffen. Er prüft aber nur fremde Aussagen und verteidigt die eigene hartnäckig, sein Urteil steht also durchaus fest."},{"option":3,"text":"Echokammern können Ansichten tatsächlich unangetastet lassen. Er debattiert aber täglich mit Kritikern und begegnet Gegenargumenten ständig. Das Problem liegt darin, wie er mit ihnen umgeht, nicht darin, dass sie fehlen."}],"familie":"werkzeuge-gegen-sich-selbst","fertigkeit":"F5","quellen":[{"typ":"url","kurz":"Galef, J. (2016): Why you think you're right -- even if you're wrong. TEDxPSU, Februar 2016 (TED-Seite mit Transkript)","oeffentlich":true,"url":"https://www.ted.com/talks/julia_galef_why_you_think_you_re_right_even_if_you_re_wrong/transcript","abruf":"2026-10-12"},{"typ":"doi","kurz":"West, R. F.; Meserve, R. J.; Stanovich, K. E. (2012): Cognitive Sophistication Does Not Attenuate the Bias Blind Spot. Journal of Personality and Social Psychology 103(3), 506–519","oeffentlich":false,"doi":"10.1037/a0028857"}],"thema":"Netz und Medien","pruefung":{"lauf":"quiz-audit-v3","modell":"claude-sonnet-5-5","datum":"2026-10-13","urteil":"korrigieren","pruefsumme":"333ba333f8537045"}},{"id":"qx-b2-037","clusterId":"B","werkstueckRef":"B.26","stufe":1,"question":"Was ist die sinnvollste Reaktion auf diesen Impuls?","scenario":"Beim Kauf von Konzerttickets blinkt ein roter Balken: „Nur noch 17 Tickets verfügbar! 250 Leute sehen sich dieses Angebot gerade an!“ Du wolltest eigentlich noch ein paar Tage überlegen, ob du hingehst. Jetzt schlägt dein Herz schneller, und du spürst den Impuls, sofort zu bestellen.","options":["Sofort kaufen, weil die Einschätzung vieler Interessenten meist besser ist als die eines Einzelnen.","Innehalten und in Ruhe prüfen, ob dich der Balken oder der Wert des Konzerts antreibt, bevor du kaufst.","Dem Bauchgefühl folgen und sofort bestellen, weil schnelle Entscheidungen oft besser sind als langes Grübeln.","Den Impuls unterdrücken und das Konzert aus dem Kopf streichen, damit du dich nicht beeinflussen lässt."],"correctIndex":1,"explanation":"„Nur noch 17“ (Knappheit) und „250 Leute sehen sich das gerade an“ (sozialer Beweis) sagen nichts darüber, ob das Konzert dir das Geld wert ist. Sie erzeugen Zeitdruck und sollen die ruhige Abwägung umgehen. Seltenes wirkt automatisch wertvoller, und was viele wollen, wirkt automatisch richtig, auch wenn beides über den eigentlichen Wert nichts verrät. Der Impuls ist ein Warnsignal, kein Argument. Sinnvoll ist, ihn zu bemerken und gezielt zu fragen: Will ich das, weil ich den Wert verstanden habe, oder nur, weil ich Angst habe, es zu verpassen? Pauschal nicht zu kaufen wäre ebenso wenig durchdacht wie blindes Kaufen: Auch dann bestimmt der Balken deine Entscheidung, nur in die Gegenrichtung. Die anderen Gedanken klingen vernünftig, passen aber nicht zu dieser Lage. Die Weisheit der Vielen gilt nur für unabhängige Urteile, und hier schauen bloß viele Leute auf dasselbe Angebot. Das Bauchgefühl ist an dieser Stelle gerade der vom Balken ausgelöste Impuls.","coreRule":"⚡ „Nur noch wenige“ und „viele schauen gerade“ sind Druckmittel, keine Informationen über den Wert. Prüfe, was dich antreibt, bevor du entscheidest.","beleg":"Werkstück B.26 (Eingangsszene Situation B; Analyse: drei Heuristiken; Anwendung: Alltag & Konsum)","status":"entwurf","kurz":"Der rote Balken sagt nichts darüber, ob dir das Konzert sein Geld wert ist, er erzeugt nur Zeitdruck. Der naheliegende Fehler ist, den Impuls für ein Argument zu halten, statt ihn als Warnsignal zu nehmen und in Ruhe zu prüfen, was du selbst willst.","prueffrage":"Was verraten dir die beiden Zahlen im roten Balken über das Konzert selbst?","rueckmeldung":[{"option":0,"text":"Die Einschätzung vieler kann tatsächlich klüger sein als die eines Einzelnen, aber nur, wenn die Urteile unabhängig entstehen. Hier schauen 250 Leute bloß auf dasselbe Angebot, und das verrät nichts darüber, ob das Konzert sein Geld wert ist."},{"option":2,"text":"Schnelle Entscheidungen können in vielen Lagen gut funktionieren. Hier ist das Bauchgefühl aber gerade der vom Balken ausgelöste Impuls, also keine unabhängige Einschätzung, sondern das Ergebnis des Drucks, den du eigentlich prüfen solltest."},{"option":3,"text":"Den Impuls zu bemerken ist richtig, ihn einfach zu unterdrücken und das Konzert zu streichen aber nicht. Auch dann bestimmt der Balken deine Entscheidung, nur in die Gegenrichtung, und du verzichtest womöglich auf etwas, das du wirklich willst."}],"familie":"mehrheit-ist-kein-beleg","fertigkeit":"F2","quellen":[{"typ":"url","kurz":"Federal Trade Commission (2022): Bringing Dark Patterns to Light. Staff Report, September 2022","oeffentlich":true,"url":"https://www.ftc.gov/system/files/ftc_gov/pdf/P214800%20Dark%20Patterns%20Report%209.14.2022%20-%20FINAL.pdf","seite":"21–22, 37","abruf":"2026-10-12"}],"thema":"Geld und Zahlen","pruefung":{"lauf":"quiz-audit-v3","modell":"claude-sonnet-5-5","datum":"2026-10-13","urteil":"ok","pruefsumme":"128087858dc23c5c"}},{"id":"qx-b2-038","clusterId":"B","werkstueckRef":"B.26","stufe":3,"question":"Ein Kollege schwärmt von einem Vermögenswert, dessen Preis sich in sechs Monaten vervielfacht hat. Du fragst ihn, warum er gerade jetzt kauft. Welche Antwort deutet am stärksten darauf hin, dass er sich in einer Spekulationsblase bewegt?","options":["„Die Preise sind höher als vor einem Jahr, und auch große Anleger kaufen deutlich mehr dazu als früher.“","„Ich habe mir Gewinne, Umsätze und Kennzahlen angesehen, und sie tragen den Anstieg aus meiner Sicht weiterhin.“","„Seit sich die ersten Kritiker gemeldet haben, hat sich der Anstieg verlangsamt, ich warte, ob er wieder anzieht.“","„Ob er etwas wert ist, weiß ich nicht genau, aber morgen ist er teurer, und ich will nicht als Einziger draußen bleiben.“"],"correctIndex":3,"explanation":"Typisch für eine Blase ist, dass sich die Begründung vom Wert auf die Erwartung weiterer Preissteigerungen verlagert und die Angst, nicht dabei zu sein, den Kauf antreibt. Dann kauft man, weil der Preis steigt, nicht weil man verstanden hat, was der Vermögenswert wert ist. Ein höherer Preis oder zusätzliche Käufe allein sind noch kein Beleg, auch ein kräftiger Anstieg kann durch Gewinne und Umsätze gedeckt sein. Entscheidend ist, woher die Rechtfertigung stammt: aus dem Wert der Sache oder aus der Hoffnung auf den nächsten Käufer.","coreRule":"⚡ Prüfe die Begründung: Kaufst du wegen des Wertes oder weil der Preis gestern gestiegen ist?","quote":"","quoteLabel":"","beleg":"Werkstück B.26 (Red Flags: eine Spekulationsblase; Anti-Denkmuster)","status":"entwurf","scenario":"","kurz":"Wer kauft, weil der Preis morgen höher sein wird, und aus Angst, draußen zu bleiben, stützt sich nicht mehr auf den Wert der Sache. Der naheliegende Fehler ist, schon den Preisanstieg selbst als Zeichen einer Blase zu lesen.","prueffrage":"Was müsste dein Kollege über den Vermögenswert selbst wissen, um beurteilen zu können, ob der heutige Preis angemessen ist?","rueckmeldung":[{"option":0,"text":"Gestiegene Preise und mehr Käufe großer Anleger wirken wie ein Warnsignal. Beides gibt es aber auch bei einem Anstieg, den Gewinne und Umsätze decken, und dass er den Wert nicht kennt oder nur aus Angst kauft, draußen zu bleiben, sagt er nicht."},{"option":1,"text":"Wer Gewinne, Umsätze und Kennzahlen prüft, begründet seinen Kauf mit dem Wert der Sache. Das ist das Gegenteil einer Blasenlogik, auch wenn sich im Einzelfall streiten lässt, ob die Zahlen den Anstieg wirklich tragen."},{"option":2,"text":"Das Abwarten nach der Kritik zeigt, dass er auf den Kursverlauf schaut. Er kauft aber gerade nicht überstürzt, und weder Unwissen über den Wert noch die Angst, draußen zu bleiben, ist darin zu erkennen."}],"familie":"mehrheit-ist-kein-beleg","fertigkeit":"F2","quellen":[{"typ":"url","kurz":"Shiller, R. J. (2014): Speculative Asset Prices (Nobel Prize Lecture). Cowles Foundation Discussion Paper 1936","oeffentlich":true,"url":"https://cowles.yale.edu/sites/default/files/2022-08/d1936.pdf","seite":"2","abruf":"2026-10-12"},{"typ":"literatur","kurz":"Kindleberger, C. P.; Aliber, R. Z. (2005): Manias, Panics, and Crashes. 5. Aufl., Hoboken: Wiley","oeffentlich":false}],"thema":"Geld und Zahlen","pruefung":{"lauf":"quiz-audit-v3","modell":"claude-sonnet-5-5","datum":"2026-10-13","urteil":"korrigieren","pruefsumme":"604127df74b21fb9"}},{"id":"qx-b2-039","clusterId":"B","werkstueckRef":"B.26","stufe":4,"question":"Welche Frage stellst du dir, bevor du auf das Angebot eingehst?","scenario":"Eine Freundin drängt: „Es gibt nur 20 Plätze beim Wochenend-Workshop mit dem berühmten Guru. Danach nimmt er drei Jahre lang keine neuen Schüler. Alle sagen, es hat ihr Leben verändert.“","options":["Habe ich schon so viel Geld und Zeit in diese Lehre gesteckt, dass ich weitermachen will, um das bisher Investierte nicht zu verlieren?","Würde ich den Workshop auch buchen, wenn es keine Platzbegrenzung und keine Frist gäbe, oder treibt mich vor allem die Angst, die Gelegenheit zu verpassen?","Habe ich mich dem Guru gegenüber schon früher festgelegt, sodass ich jetzt vor allem nach Belegen suche, die meine bisherige Haltung bestätigen?","Wurde mir ein Preis genannt, an dem ich mich orientiere, sodass ich prüfen muss, ob die erste genannte Zahl meine Erwartung verankert?"],"correctIndex":1,"explanation":"Platzbegrenzung („nur 20 Plätze“), Frist („drei Jahre keine neuen Schüler“) und Erfolgsberichte („alle sagen, es hat ihr Leben verändert“) sagen nichts darüber, ob der Workshop hält, was er verspricht. Knappheit und Exklusivität lassen Dinge automatisch wertvoller erscheinen, und eine große Zahl von Begeisterten wirkt als sozialer Beweis: Popularität wird mit Wert verwechselt. Beides erzeugt Zeitdruck und den Wunsch, zu einer auserwählten Gruppe zu gehören. Die beste Prüffrage trennt deshalb den Wert der Sache von dem Druck, der um sie herum aufgebaut wird: Würde das Angebot auch ohne Verknappung überzeugen? Wenn nicht, bezahlst du für die Angst vor dem Verpassen und nicht für den Inhalt. Die anderen Gedanken beschreiben bekannte Denkfallen, treffen aber auf diese Lage nicht zu: Von bisherigen Ausgaben für diese Lehre ist keine Rede, also gibt es keine versunkenen Kosten, die zum Weitermachen drängen. Du hast dich auch noch auf nichts festgelegt, das du nur noch bestätigen müsstest, und ein Preis, der als Anker wirken könnte, wird gar nicht genannt.","coreRule":"⚡ Wer wegen der Angst vor dem Verpassen kauft, bezahlt für das Gefühl, nicht für die Sache.","beleg":"Werkstück B.26 (Eingangsszene Situation C; Anwendung: Esoterik; Anti-Denkmuster)","status":"entwurf","kurz":"Entscheidend ist, ob der Workshop auch ohne Verknappung überzeugen würde. Platzbegrenzung, Frist und begeisterte Stimmen erhöhen den Druck und lassen das Angebot wertvoller wirken, sagen aber nichts darüber, ob es hält, was es verspricht.","prueffrage":"Welche der drei Aussagen deiner Freundin sagt etwas darüber, was im Workshop tatsächlich geschieht?","rueckmeldung":[{"option":0,"text":"Wer schon viel investiert hat, will das Eingesetzte oft nicht abschreiben, und das ist eine echte Falle. Hier ist aber von bisherigen Ausgaben für diese Lehre keine Rede, also gibt es nichts, was dich zum Weitermachen drängen könnte."},{"option":2,"text":"Wer sich früher festgelegt hat, sucht gern nur noch Bestätigung, und das kommt im Alltag oft vor. Im Szenario hast du dich aber noch auf nichts festgelegt, und der Druck kommt von außen: aus Verknappung und den Berichten der anderen."},{"option":3,"text":"Eine zuerst genannte Zahl kann die Erwartung an einen Preis tatsächlich verankern. Hier wird aber gar kein Preis genannt. Die Zahlen im Szenario, 20 Plätze und drei Jahre, markieren Knappheit und sagen nichts über den Wert des Workshops."}],"familie":"mehrheit-ist-kein-beleg","fertigkeit":"F2","quellen":[{"typ":"url","kurz":"Federal Trade Commission (2022): Bringing Dark Patterns to Light. Staff Report, September 2022","oeffentlich":true,"url":"https://www.ftc.gov/system/files/ftc_gov/pdf/P214800%20Dark%20Patterns%20Report%209.14.2022%20-%20FINAL.pdf","seite":"21–22","abruf":"2026-10-12"}],"thema":"Zusammenleben","pruefung":{"lauf":"quiz-audit-v3","modell":"claude-sonnet-5-5","datum":"2026-10-13","urteil":"ok","pruefsumme":"92b5218ffc6308c5"}},{"id":"qx-b2-040","clusterId":"B","werkstueckRef":"B.26","stufe":2,"question":"Welche Beobachtung zeigt am deutlichsten, dass hier Angst vor dem Verpassen ausgenutzt wird, statt dass ein Angebot überzeugen soll?","scenario":"Eine Bekannte lädt dich zu einem „Business-Abend“ ein. „Wer jetzt Mitglieder anwirbt, sichert sich die beste Position und wird reich“, sagt sie. „Es gibt nur noch wenige Startplätze, und heute entscheiden sich schon die Ersten.“ Über das Produkt selbst spricht sie kaum.","options":["Der Vorteil wird über die Rekrutierung neuer Mitglieder und knappe Startplätze begründet, nicht über den Nutzen des Produkts.","Die Bekannte stützt das Angebot auf berühmte Fürsprecher, die es angeblich nutzen, statt auf den Nutzen des Produkts.","Die Bekannte macht dir vorab ein Geschenk, damit du dich zu einer Gegenleistung verpflichtet fühlst, statt das Produkt zu prüfen.","Die Bekannte holt zunächst kleine Zusagen von dir ein, damit du dich später an dein früheres Ja gebunden fühlst."],"correctIndex":0,"explanation":"Bei Angeboten, die vor allem Reichtum durch Anwerben, Zeitdruck und Knappheit versprechen, wird nicht der Wert einer Sache verkauft, sondern die Sorge, eine einmalige Chance zu verpassen. Das Produkt tritt in den Hintergrund. Künstlich erzeugter Zeitdruck sowie Werbung mit Knappheit und Exklusivität sind typische Warnzeichen für FOMO-Manipulation. Entscheidend ist, woraus der versprochene Gewinn entsteht: Wird er mit dem Rekrutieren neuer Mitglieder statt mit dem Produkt begründet, ist das die FOMO-Mechanik von Multi-Level-Marketing und Schneeballsystemen. Andere Beeinflussungstechniken gibt es durchaus, sie kommen hier aber nicht vor: Die Bekannte beruft sich nicht auf berühmte Fürsprecher. Sie macht auch kein Geschenk, das dich zur Gegenleistung verpflichten soll, und holt keine kleinen Zusagen ein, an die du dich später gebunden fühlen sollst.","coreRule":"⚡ Wer vor allem die Angst vor dem Verpassen verkauft, verkauft nicht den Wert der Sache.","beleg":"Werkstück B.26 (Anwendung: Multi-Level-Marketing & Schneeballsysteme; Red Flags: FOMO-Manipulation)","status":"entwurf","kurz":"Wird der Gewinn mit dem Anwerben neuer Mitglieder und knappen Plätzen begründet, wird die Sorge verkauft, eine einmalige Chance zu verpassen, nicht der Wert einer Sache. Der Nutzen des Produkts tritt dabei in den Hintergrund.","prueffrage":"Was müsste eine seriöse Einladung zu einem Verkaufsabend enthalten, das in ihren Worten fehlt?","rueckmeldung":[{"option":1,"text":"Berühmte Fürsprecher sind tatsächlich ein verbreitetes Mittel, Vertrauen zu erzeugen. In dieser Situation fällt aber kein einziger Name, es geht nur um Positionen, Reichtum und knappe Startplätze."},{"option":2,"text":"Ein Geschenk, das ein Gefühl der Schuld erzeugt, ist eine bekannte Technik. Hier steht aber nur eine Einladung zu einem Abend, ohne ein Präsent, das du erwidern sollst. Der Druck entsteht über die Knappheit."},{"option":3,"text":"Kleine Zusagen, an die man sich später gebunden fühlt, sind ein klassischer Hebel. Die Bekannte holt hier aber nichts Gestaffeltes ein, sie lockt mit einem großen Gewinn und knappen Plätzen, die sofort entschieden werden sollen."}],"familie":"mehrheit-ist-kein-beleg","fertigkeit":"F2","quellen":[{"typ":"url","kurz":"Federal Trade Commission, Consumer Advice: Multi-Level Marketing Businesses and Pyramid Schemes","oeffentlich":true,"url":"https://consumer.ftc.gov/articles/multi-level-marketing-businesses-and-pyramid-schemes","abruf":"2026-10-12"},{"typ":"url","kurz":"Federal Trade Commission (2022): Bringing Dark Patterns to Light. Staff Report, September 2022","oeffentlich":true,"url":"https://www.ftc.gov/system/files/ftc_gov/pdf/P214800%20Dark%20Patterns%20Report%209.14.2022%20-%20FINAL.pdf","seite":"21–22","abruf":"2026-10-12"}],"thema":"Geld und Zahlen","pruefung":{"lauf":"quiz-audit-v3","modell":"claude-sonnet-5-5","datum":"2026-10-13","urteil":"ok","pruefsumme":"8cdfe26c77f386eb"}},{"id":"qx-b2-041","clusterId":"B","werkstueckRef":"B.27","stufe":1,"question":"Welche Erklärung für Lenas Meinungswechsel ist die sparsamste?","scenario":"Lena fand das Programm einer neuen Partei lange unausgegoren; im Freundeskreis hieß die Partei „Die Spinner“, die Umfragen lagen bei 3 %. Dann springt die Partei auf 15 %. In Lenas Feed erscheinen positive Artikel, und zwei Kollegen, die sie für klug hält, loben das Programm. Lena liest es noch einmal und findet es jetzt „erfrischend anders“. Nach der Wahl, bei der die Partei 25 % erreicht, sagt sie: „Ich habe mir das genau angesehen. Die haben einfach die besten Lösungen.“ Am Programm selbst wurde zwischen den Umfragen und der Wahl nichts geändert.","options":["Mit dem Umfrageplus stieg für sie die wahrgenommene Glaubwürdigkeit der Ideen; das Programm blieb gleich.","Mit dem Umfrageplus rechtfertigte sie eine frühere Parteiwahl vor sich selbst und wertete das Programm auf.","Mit dem Umfrageplus bestätigte sich eine lange gehegte Sympathie, für die sie nur noch Belege suchte.","Mit dem Umfrageplus rückten ihre persönlichen Interessen in den Vordergrund, die das Programm nun besser bedient."],"correctIndex":0,"explanation":"Verglichen werden muss, was sich zwischen den beiden Urteilen tatsächlich geändert hat. Das Programm blieb gleich; geändert haben sich nur die Umfragewerte und die Signale aus Lenas Umfeld, also positive Artikel und das Lob zweier geschätzter Kollegen. Die sparsamste Erklärung nimmt deshalb an, dass dieses gewachsene Ansehen ihr Urteil verschoben hat: Popularität dient als Ersatz für Qualität („Wenn so viele das gut finden, muss etwas dran sein“), das ist der Mitläufer-Effekt. Die anderen Erklärungen brauchen Zusatzannahmen, für die nichts spricht: Eine frühere Parteiwahl, die Lena rechtfertigen müsste, kommt nicht vor. Eine lange gehegte Sympathie widerspricht ihrer anfänglichen Skepsis, und von neuen persönlichen Interessen ist keine Rede. Auch Lenas Satz, sie habe sich alles genau angesehen, ändert daran nichts, denn die Ideen selbst sind dieselben geblieben.","coreRule":"⚡ Ändert sich nur die Zahl der Anhänger und nicht die Idee, dann sagt der Meinungswechsel etwas über die Stimmung aus, nicht über die Idee.","beleg":"Werkstück B.27 (Eingangsszene; Kernidee)","status":"entwurf","quote":"","quoteLabel":"","kurz":"Zwischen den beiden Urteilen änderten sich nur Umfragewerte und Signale aus Lenas Umfeld, nicht das Programm. Wer Beliebtheit als Ersatz für Qualität nimmt, fällt dem Mitläufer-Effekt zum Opfer und hält die Ideen für besser, obwohl sie gleich geblieben sind.","prueffrage":"Was genau hat sich zwischen Lenas erstem und ihrem zweiten Urteil nachweislich geändert?","rueckmeldung":[{"option":1,"text":"Menschen werten getroffene Entscheidungen oft nachträglich auf. Im Szenario hat Lena die Partei aber nie gewählt, sie hielt sie zuerst für „Spinner“. Die Erklärung setzt eine frühere Wahl voraus, die nirgends vorkommt."},{"option":2,"text":"Dass Lena das Programm noch einmal las und es plötzlich anders sah, wirkt wie späte Belegsuche. Eine lange gehegte Sympathie gibt es aber nicht: Anfangs hielt sie das Programm für unausgegoren und die Partei für „Spinner“."},{"option":3,"text":"Eigene Interessen können ein Urteil durchaus färben. Hier fehlt aber jeder Hinweis, dass sich bei Lena etwas verschoben hat; geändert haben sich nur Umfragen und Signale aus ihrem Umfeld, nicht ihre Lage und nicht das Programm."}],"familie":"mehrheit-ist-kein-beleg","fertigkeit":"F2","quellen":[{"typ":"url","kurz":"Dowden, B. H.: Fallacies. Internet Encyclopedia of Philosophy (Einträge „Bandwagon“, „Appeal to the People“)","oeffentlich":true,"url":"https://iep.utm.edu/fallacy/","abruf":"2026-10-12"}],"thema":"Zusammenleben","pruefung":{"lauf":"quiz-audit-v3","modell":"claude-sonnet-5-5","datum":"2026-10-13","urteil":"ok","pruefsumme":"8812c4250f29ea02"}},{"id":"qx-b2-042","clusterId":"B","werkstueckRef":"B.27","stufe":2,"question":"Du suchst in einer fremden Stadt ein Restaurant für den Abend und siehst: Das eine Lokal ist voll, das Nachbarlokal fast leer. Bei welcher der folgenden Entscheidungen wäre der Rat „Mach, was die Mehrheit macht“ ähnlich vertretbar wie hier?","options":["Du suchst einen Film für den Abend aus und wählst den, den die meisten deiner Freunde gerade schauen, weil ein Fehlgriff dort kaum Folgen hat und sich leicht korrigieren lässt.","Du überlegst, deine Ersparnisse in einen Vermögenswert zu stecken, weil gerade viele andere damit Gewinne machen und davon erzählen.","Du entscheidest, ob ein Mittel für dein Kind geeignet ist, und orientierst dich daran, dass die meisten Eltern in deinem Umfeld es verwenden und empfehlen.","Du fragst dich, ob eine Behauptung stimmt, und hältst sie für belegt, weil sie in sozialen Netzwerken bereits millionenfach angesehen und geteilt wurde."],"correctIndex":0,"explanation":"Der Hinweis „Das volle Lokal ist wohl das bessere“ funktioniert als schnelle Faustregel, weil sich dahinter viele einzelne Erfahrungen bündeln, ein Fehlgriff wenig kostet und sich leicht korrigieren lässt. Genau diese Bedingungen (umkehrbar, geringes Risiko) treffen beim Film für den Abend zu. Bei den anderen Fällen fehlen sie: Wer Ersparnisse anlegt, weil andere gerade Gewinne machen, kauft nicht, weil der Wert unterbewertet wäre, sondern weil der Preis steigt; das treibt Blasen. Beim Mittel für das Kind steht möglicherweise die Gesundheit auf dem Spiel, und dass viele Eltern etwas verwenden, sagt wenig über Wirksamkeit und Verträglichkeit. Und dass eine Behauptung millionenfach geteilt wurde, ist keine Prüfung ihres Wahrheitsgehalts. Je höher der mögliche Schaden und je schwerer die Entscheidung zurückzunehmen ist, desto weniger darf Popularität die eigene Prüfung von Fakten, Logik und Ethik ersetzen.","coreRule":"⚡ Der Mehrheit zu folgen genügt für den Filmabend, aber nicht für Wahrheitsfragen oder riskante Entscheidungen.","beleg":"Werkstück B.27 (Adaptives Talent; Kipppunkt)","status":"entwurf","scenario":"","kurz":"Beim Restaurant bündeln sich viele Einzelerfahrungen, ein Fehlgriff kostet wenig und lässt sich korrigieren. Der Fehler wäre, das auf Fälle mit hohem Schaden zu übertragen: Je schwerer etwas rückgängig zu machen ist, desto weniger ersetzt Beliebtheit die eigene Prüfung.","prueffrage":"Welche Eigenschaften der Restaurantwahl machen es dort vertretbar, sich nach der Mehrheit zu richten?","rueckmeldung":[{"option":1,"text":"Sichtbare Gewinne anderer wirken wie ein Beweis, dass sich der Einstieg lohnt. Wer aber kauft, weil der Preis steigt, folgt der Stimmung statt dem Wert, und das treibt Blasen; bei Ersparnissen ist ein Verlust hoch und schwer rückgängig zu machen."},{"option":2,"text":"Dass viele Eltern ein Mittel verwenden, wirkt wie gesammelte Erfahrung. Es sagt aber wenig über Wirksamkeit und Verträglichkeit, und hier steht möglicherweise die Gesundheit deines Kindes auf dem Spiel; das verlangt eigene Prüfung."},{"option":3,"text":"Millionenfache Aufrufe zeigen, dass eine Behauptung Aufmerksamkeit bekommt, nicht dass sie stimmt. Ob etwas wahr ist, klärst du über Belege und Logik. Die Verbreitung ersetzt diese Prüfung nicht, auch nicht bei großer Reichweite."}],"familie":"mehrheit-ist-kein-beleg","fertigkeit":"F2","quellen":[{"typ":"url","kurz":"Dowden, B. H.: Fallacies. Internet Encyclopedia of Philosophy (Eintrag „Bandwagon“)","oeffentlich":true,"url":"https://iep.utm.edu/fallacy/","abruf":"2026-10-12"},{"typ":"url","kurz":"Shiller, R. J. (2014): Speculative Asset Prices (Nobel Prize Lecture). Cowles Foundation Discussion Paper 1936","oeffentlich":true,"url":"https://cowles.yale.edu/sites/default/files/2022-08/d1936.pdf","seite":"2","abruf":"2026-10-12"}],"thema":"Psychologie","pruefung":{"lauf":"quiz-audit-v3","modell":"claude-sonnet-5-5","datum":"2026-10-13","urteil":"korrigieren","pruefsumme":"4335fa56df5bebc1"}},{"id":"qx-b2-043","clusterId":"B","werkstueckRef":"B.27","stufe":3,"question":"Welche Rückfrage prüft diese Erklärung am besten?","options":["Woher kam das Geld, mit dem so viele Anleger kaufen konnten, und wie stark wuchs die Kreditvergabe in dieser Zeit?","Hat der Kommentator ein eigenes finanzielles Interesse an der Aktie, sodass seine Erklärung gefärbt sein könnte?","Wie treffsicher waren frühere Kursprognosen dieses Kommentators, und wie oft lag er in seinen Erklärungen daneben?","Auf welchen Zeitraum und welchen Startkurs bezieht sich die Verdreifachung genau, und wie wurde sie berechnet?"],"correctIndex":0,"explanation":"Das Nachziehen hinter denen, die gerade Gewinne machen, ist real: Wer sieht, dass andere mit Spekulation verdienen, steigt ein. Das erklärt aber nur, warum Menschen kaufen wollen, nicht, womit sie kaufen. Bei einer einzelnen Aktie kann das Geld aus anderen Anlagen umgeschichtet werden; bei großen Manien sehen die Ökonomen Charles Kindleberger und Robert Aliber den eigentlichen Motor dagegen im Kredit, der in guten Zeiten rasch wächst, und das Mitlaufen ist bei ihnen ein Teil des Booms, nicht seine alleinige Ursache. Wer „der Herdentrieb allein“ behauptet, übersieht deshalb mindestens die Frage der Finanzierung. Die beste Rückfrage sucht diesen fehlenden Faktor. Ein Eigeninteresse des Kommentators ist ein vernünftiger Gedanke, betrifft aber seine Glaubwürdigkeit und sagt nichts über die Ursache des Anstiegs. Seine frühere Treffsicherheit zeigt, wie verlässlich er ist, nicht aber, ob der Herdentrieb hier allein genügt. Wie die Verdreifachung gerechnet wurde, klärt die genannte Zahl, nicht die behauptete Alleinursache.","coreRule":"⚡ Der Herdentrieb heizt Blasen an, aber das Geld dafür kommt aus wachsendem Kredit: Wer eine einzige Ursache behauptet, sollte nach den fehlenden fragen.","beleg":"Werkstück B.27 (Anwendung: Finanzmärkte); Fn. gl-b-kredit (Kindleberger/Aliber 2005, S. 12 und 29)","status":"entwurf","scenario":"Ein Börsenkommentator erklärt den starken Kursanstieg einer Aktie: „Sie hat sich in einem Jahr verdreifacht, weil alle auf den Zug aufgesprungen sind. Der Herdentrieb allein hat diese Blase gemacht.“","kurz":"Mitlaufen erklärt nur, warum Menschen kaufen wollen, nicht, womit sie kaufen. Wer „der Herdentrieb allein“ sagt, übersieht die Finanzierung. Bei großen Manien gilt Kredit als Motor, das Mitlaufen eher als Teil des Booms.","prueffrage":"Welche Auskunft könnte zeigen, dass der Herdentrieb allein den Anstieg nicht erklärt?","rueckmeldung":[{"option":1,"text":"Ein Eigeninteresse wäre ein berechtigter Gedanke, wenn es um die Glaubwürdigkeit des Kommentators geht. Ob der Herdentrieb den Anstieg allein erklärt, beantwortet es aber nicht, denn dafür zählt die Sache selbst und nicht, wer sie behauptet."},{"option":2,"text":"Eine schlechte Trefferquote macht den Kommentator weniger verlässlich, doch das betrifft ihn, nicht diese Erklärung. Auch jemand, der sonst oft danebenliegt, kann hier recht haben, und ein Treffsicherer kann sich irren. Geprüft wird so nicht, ob der Herdentrieb allein genügt."},{"option":3,"text":"Eine genaue Rechnung klärt, ob die Verdreifachung stimmt. Diese Zahl wird aber gar nicht bestritten, sondern ihre behauptete Ursache. Selbst mit sauber geklärter Basis bliebe offen, ob Mitlaufen allein den Anstieg erklärt."}],"familie":"monokausal-erkennen","fertigkeit":"F2","quellen":[{"typ":"literatur","kurz":"Kindleberger, C. P.; Aliber, R. Z. (2005): Manias, Panics, and Crashes: A History of Financial Crises. 5. Aufl., Hoboken: Wiley","oeffentlich":false},{"typ":"url","kurz":"Schularick, M.; Taylor, A. M. (2009/2011): Credit Booms Gone Bust: Monetary Policy, Leverage Cycles and Financial Crises, 1870–2008. NBER Working Paper 15512","oeffentlich":true,"url":"https://www.nber.org/papers/w15512","abruf":"2026-10-12"}],"thema":"Geld und Zahlen","pruefung":{"lauf":"quiz-audit-v3","modell":"claude-sonnet-5-5","datum":"2026-10-13","urteil":"korrigieren","pruefsumme":"664765c3294605d0"}},{"id":"qx-b2-044","clusterId":"B","werkstueckRef":"B.27","stufe":4,"question":"Welche Prüffrage hilft dir am besten, die Aussage zu beurteilen, ohne aus ihrer Größe auf ihre Wahrheit zu schließen?","scenario":"Ein Video behauptet etwas Spektakuläres. Darunter steht: „10 Millionen Aufrufe! Hunderttausende sind schon auf der Straße! Wir werden jeden Tag mehr!“ Dein Bekannter sagt: „Bei so vielen Leuten muss doch etwas dran sein.“","options":["Sind die Aufrufe und Teilnehmerzahlen echt, denn aufgeblähte Zahlen würden die Größe der Bewegung falsch darstellen?","Wie viele Menschen halten die Behauptung für falsch, denn die Zahl der Skeptiker zeigt, wie viel die Zahl der Anhänger wiegt?","Wie würde ich die Behauptung beurteilen, wenn nur ich davon wüsste, denn dann zählten allein die Belege, nicht Klickzahlen?","Wie ungewöhnlich schnell verbreitet sich die Behauptung, denn ein auffälliges Tempo könnte auf gesteuerte Verbreitung hindeuten?"],"correctIndex":2,"explanation":"Aufrufe, Demonstrationsgrößen und Wachstum sagen etwas darüber aus, wie viele Menschen eine Behauptung teilen, nicht darüber, ob sie stimmt. Das ist die Verwechslung von Popularität mit Richtigkeit. Zudem erzeugt Popularität weitere Popularität: Wer mitläuft, macht die Bewegung größer und scheinbar überzeugender, ohne dass ein einziger Beleg hinzukommt. Prüfen lässt sich die Aussage nur, wenn man die Menge gedanklich ausblendet und fragt, was die Belege allein hergeben. Die anderen Fragen sind für sich sinnvoll, bleiben aber bei der Menge: Auch echte Zahlen sagen nichts darüber, ob die Behauptung stimmt. Die Zahl der Gegenstimmen ist wieder nur ein Größenvergleich. Und selbst ein gesteuertes Wachstum würde nichts darüber verraten, ob die Aussage wahr ist.","coreRule":"⚡ Eine große Anhängerschaft ist ein Beleg für Beliebtheit, nicht für Wahrheit.","quote":"","quoteLabel":"","beleg":"Werkstück B.27 (Anwendung: Verschwörungsmythen & Kulte; Anti-Denkmuster)","status":"entwurf","kurz":"Die Menge blendest du am besten gedanklich aus und fragst, was die Belege allein hergeben. Aufrufe und Teilnehmerzahlen zeigen nur, wie viele die Behauptung teilen, und Zulauf erzeugt weiteren Zulauf, auch ohne einen einzigen neuen Beleg.","prueffrage":"Welche der Angaben unter dem Video sagt etwas darüber, ob das Behauptete tatsächlich zutrifft?","rueckmeldung":[{"option":0,"text":"Aufgeblähte Zahlen aufzudecken ist durchaus sinnvoll, denn Zahlen lassen sich manipulieren. Doch selbst vollkommen echte Zahlen würden nur zeigen, wie viele Menschen mitmachen, und nichts darüber, ob die Behauptung stimmt."},{"option":1,"text":"Wer die Gegenstimmen zählt, bleibt beim Größenvergleich: Ob mehr Menschen zustimmen oder widersprechen, sagt nichts über die Wahrheit. Aufschlussreicher wäre, welche Gründe die eine oder andere Seite nennt."},{"option":3,"text":"Ein auffälliges Tempo kann tatsächlich auf gelenkte Verbreitung hindeuten und ist als Quellenfrage nützlich. Es verrät aber nicht, ob die Aussage stimmt, denn auch eine gesteuerte Kampagne kann Wahres oder Falsches verbreiten."}],"familie":"mehrheit-ist-kein-beleg","fertigkeit":"F2","quellen":[{"typ":"url","kurz":"Dowden, B. H.: Fallacies. Internet Encyclopedia of Philosophy (Einträge „Appeal to the People“, „Bandwagon“)","oeffentlich":true,"url":"https://iep.utm.edu/fallacy/","abruf":"2026-10-12"}],"thema":"Netz und Medien","pruefung":{"lauf":"quiz-audit-v3","modell":"claude-sonnet-5-5","datum":"2026-10-13","urteil":"korrigieren","pruefsumme":"c04a7ddefa28e0c1"}},{"id":"qx-b2-045","clusterId":"B","werkstueckRef":"B.28","stufe":1,"question":"Welche Erklärung passt am besten zu diesem Preisunterschied, und was spricht gegen den Einwand der Teilnehmerin?","scenario":"Bei einem Experiment bekommt die eine Hälfte einer Gruppe eine Kaffeetasse geschenkt, die andere Hälfte nicht. Wer eine Tasse hat, will sie im Schnitt erst ab einem deutlich höheren Preis verkaufen, als die Übrigen bereit sind, für dieselbe Tasse zu zahlen. Eine Teilnehmerin sagt: „Die Tassen sind ja alle gleich. Dann haben die Besitzer eben genauer geprüft, wie gut sie ist.“","options":["Der Unterschied entsteht erst durch das Besitzen: Wer die Tasse hat, empfindet das Abgeben als Verlust und gewichtet ihn stärker als den Erlös, obwohl die Tassen identisch sind.","Der Unterschied entsteht durch bessere Information: Wer die Tasse hat, kennt ihre Qualität genauer und verlangt deshalb einen höheren Preis, obwohl die Tassen identisch sind.","Der Unterschied entsteht durch Gruppendruck: Wer die Tasse hat, richtet sich nach den übrigen Besitzern und nennt einen ähnlich hohen Preis, obwohl die Tassen identisch sind.","Der Unterschied entsteht durch Verankerung: Wer die Tasse hat, richtet sich nach dem Ladenpreis, den er für sie vermutet, und verlangt deshalb mehr, obwohl die Tassen identisch sind."],"correctIndex":0,"explanation":"Die Tassen sind identisch. Der einzige Unterschied zwischen den Gruppen ist der Besitz. Wer eine Tasse hat, für den wird sie Teil des Referenzpunkts. Sie herzugeben wird dann als Verlust erlebt, und ein Verlust wiegt meist schwerer als ein gleich hoher Gewinn. Deshalb verlangen die Besitzer mehr, als die anderen zahlen würden (Besitztumseffekt). Der Einwand der Teilnehmerin scheitert daran, dass identische Tassen keinen Qualitätsunterschied bieten, den die Besitzer genauer prüfen könnten. Dasselbe Muster steckt hinter „30 Tage kostenlos testen“: Was man schon hat, gibt man ungern zurück. Andere bekannte Mechanismen passen nicht: Gruppendruck setzt voraus, dass die Besitzer sich untereinander abstimmen, wovon nichts berichtet wird. Eine Verankerung am vermuteten Ladenpreis würde beide Gruppen gleichermaßen betreffen und nicht nur die Besitzer.","coreRule":"⚡ Wenn identische Dinge nur wegen des Besitzes unterschiedlich bewertet werden, steckt oft Verlustaversion dahinter: Was ich habe, wird Teil meines Referenzpunkts, und Hergeben zählt als Verlust.","beleg":"Werkstück B.28 (Analyse: Besitztumseffekt; Anwendung: Marketing)","status":"entwurf","kurz":"Der einzige Unterschied zwischen den Gruppen ist der Besitz: Wer die Tasse hat, erlebt das Abgeben als Verlust, und der wiegt meist schwerer als ein gleich hoher Gewinn. Identische Tassen bieten keinen Qualitätsunterschied, den man genauer prüfen könnte.","prueffrage":"Welche Information über die Tasse könnten die Besitzer haben, die den anderen fehlt, wenn alle Tassen gleich sind?","rueckmeldung":[{"option":1,"text":"Besser informiert zu sein würde einen höheren Preis plausibel machen. Bei identischen Tassen gibt es aber nichts, was die Besitzer genauer kennen könnten, und genau das ist der Punkt des Einwands."},{"option":2,"text":"Gruppendruck kann Preisangaben tatsächlich angleichen. Dafür müssten sich die Besitzer aber untereinander abstimmen, und davon ist im Experiment nichts berichtet. So bleibt es eine Vermutung ohne Anhaltspunkt."},{"option":3,"text":"Ein vermuteter Ladenpreis kann Preisvorstellungen durchaus prägen. Er würde aber Besitzer und Nichtbesitzer gleichermaßen betreffen und kann daher nicht erklären, warum nur die Besitzer mehr verlangen."}],"familie":"verlust-und-gewinn-abwaegen","fertigkeit":"F4","quellen":[{"typ":"doi","kurz":"Kahneman, D.; Knetsch, J. L.; Thaler, R. H. (1991): Anomalies: The Endowment Effect, Loss Aversion, and Status Quo Bias. Journal of Economic Perspectives 5(1), 193–206","oeffentlich":true,"doi":"10.1257/jep.5.1.193","url":"https://www.aeaweb.org/articles?id=10.1257/jep.5.1.193","abruf":"2026-10-12"},{"typ":"doi","kurz":"Kahneman, D.; Knetsch, J. L.; Thaler, R. H. (1990): Experimental Tests of the Endowment Effect and the Coase Theorem. Journal of Political Economy 98(6), 1325–1348","oeffentlich":false,"doi":"10.1086/261737"}],"thema":"Psychologie","pruefung":{"lauf":"quiz-audit-v3","modell":"claude-sonnet-5-5","datum":"2026-10-13","urteil":"ok","pruefsumme":"ead88a7bcae28afd"}},{"id":"qx-b2-046","clusterId":"B","werkstueckRef":"B.28","stufe":3,"question":"Ein Artikel behauptet: „Wissenschaftlich bewiesen: Verluste wiegen genau doppelt so schwer wie Gewinne.“ Zur Prüfung liest du die zugrunde liegenden Messungen nach. Die klassische Studie kam auf einen Faktor von 2,25. Eine große Zusammenstellung vieler späterer Arbeiten ergab im Mittel etwa 1,96. Betrachtet man nur Entscheidungen zwischen riskanten Lotterien, liegt der Wert bei etwa 1,31. Was folgt daraus für die Behauptung?","options":["Der Artikel überzeichnet: Der Wert ist eine Faustregel, die je nach Methode deutlich schwankt, und keine feste Konstante.","Der Artikel liegt richtig: Der Mittelwert vieler Arbeiten von etwa 1,96 entspricht praktisch dem Faktor 2 und belegt die Behauptung.","Der Artikel liegt falsch: Da die Werte so stark abweichen, ist nicht einmal belegt, dass Verluste überhaupt schwerer wiegen als Gewinne.","Der Artikel ist nicht beurteilbar: Solange die Zahl der Versuchspersonen jeder Studie fehlt, lässt sich über die Werte nichts sagen."],"correctIndex":0,"explanation":"Die Messwerte streuen je nach Methode erheblich: 2,25 in der klassischen Studie, etwa 1,96 im Mittel vieler späterer Arbeiten, nur etwa 1,31 bei riskanten Lotterien. Eine Größe, die so stark von der Messmethode abhängt, ist keine feste Konstante, sondern eine Faustregel. „Genau doppelt“ und „wissenschaftlich bewiesen“ verleihen der Zahl eine Präzision, die die Daten nicht hergeben. Die Gegenrichtung ist ebenso ein Fehlschluss: Schwankende Schätzwerte bedeuten nicht, dass der Effekt verschwindet. Die genannten Messungen liegen durchgehend über 1; wie stark der Effekt ausfällt, hängt von Methode und Kontext ab. Gal und Rucker (2018) bestreiten sogar, dass Verluste im Allgemeinen stärker wirken als gleich hohe Gewinne. Das „doppelt so stark“ ist also eine gerundete Faustregel, kein Naturgesetz. Der Mittelwert von etwa 1,96 liegt zwar in der Nähe von 2, macht aber „genau“ und „bewiesen“ bei einer Spanne von 1,31 bis 2,25 nicht wahr. Und auch ohne Angaben zur Stichprobengröße genügen die genannten Werte, um die behauptete Präzision zu widerlegen.","coreRule":"⚡ Eine Zahl, die je nach Messmethode stark schwankt, ist eine Faustregel, keine Konstante.","beleg":"Werkstück B.28 (Kernidee; Analyse); Fn. gl-b-verlust (Tversky/Kahneman 1992, S. 311; Brown u. a. 2024, JEL 62(2); Walasek u. a. 2024, JEP 103; Gal/Rucker 2018)","status":"entwurf","scenario":"","kurz":"Die Werte reichen je nach Methode von 1,31 bis 2,25, also ist „genau doppelt“ eine gerundete Faustregel und keine Konstante. Der naheliegende Fehler ist, einer glatten Zahl Präzision zuzutrauen, die die Messungen nicht hergeben.","prueffrage":"Wie weit liegen die drei genannten Werte auseinander, und welcher davon ist genau 2?","rueckmeldung":[{"option":1,"text":"Mit 1,96 liegt der Mittelwert tatsächlich nahe bei 2. Er fasst aber Werte von 1,31 bis 2,25 zusammen. Ein gerundeter Durchschnitt macht „genau doppelt“ und „bewiesen“ noch nicht wahr."},{"option":2,"text":"Die Werte streuen stark, das stimmt. Alle genannten Messungen liegen aber über 1. Schwankende Schätzwerte zeigen, dass die Zahl ungenau ist, nicht dass der Effekt verschwindet."},{"option":3,"text":"Stichprobengrößen wären für die Beurteilung einzelner Studien nützlich. Um die behauptete Genauigkeit zu widerlegen, genügt aber schon die Spanne der genannten Werte von 1,31 bis 2,25."}],"familie":"zahl-zur-quelle","fertigkeit":"F1","quellen":[{"typ":"doi","kurz":"Brown, A. L.; Imai, T.; Vieider, F. M.; Camerer, C. F. (2024): Meta-Analysis of Empirical Estimates of Loss Aversion (Preprint MetaArXiv; Zeitschriftenfassung JEL 62(2), 485–516)","oeffentlich":true,"doi":"10.31222/osf.io/hnefr","abruf":"2026-10-12"},{"typ":"doi","kurz":"Walasek, L.; Mullett, T. L.; Stewart, N. (2024): A meta-analysis of loss aversion in risky contexts. Journal of Economic Psychology 103, 102740","oeffentlich":false,"doi":"10.1016/j.joep.2024.102740"},{"typ":"doi","kurz":"Gal, D.; Rucker, D. D. (2018): The Loss of Loss Aversion: Will It Loom Larger Than Its Gain? Journal of Consumer Psychology 28(3), 497–516","oeffentlich":false,"doi":"10.1002/jcpy.1047"}],"thema":"Geschichte und Wissenschaft","pruefung":{"lauf":"quiz-audit-v3","modell":"claude-sonnet-5-5","datum":"2026-10-13","urteil":"korrigieren","pruefsumme":"95fa90e6ca073794"}},{"id":"qx-b2-047","clusterId":"B","werkstueckRef":"B.28","stufe":4,"question":"Welche Erklärung ihres Verhaltens ist am sparsamsten, wenn du nur ihre Lage betrachtest?","scenario":"Eine Bekannte ist seit Jahren in einer Gemeinschaft, die ihr viel bedeutet: Dort sind ihre engsten Freunde, ihre Rolle und das Gefühl, etwas Besonderes zu wissen. Sie hat investiert und gespendet. Nun hat ihr jemand die zentralen Behauptungen der Gruppe überzeugend widerlegt. Trotzdem sagt sie: „Du magst ja recht haben, aber ich bleibe.“","options":["Der erwartete Verlust durch einen Austritt wiegt für sie schwerer als der Gewinn, die Wahrheit zu erkennen.","Ein Bestätigungsfehler lässt sie die Widerlegung gar nicht aufnehmen, sodass sie die Behauptungen für zutreffend hält.","Sie rechnet fest damit, dass die Gemeinschaft sich bald bessert, und überschätzt die Aussichten auf eine gute Wendung.","Sie misstraut dem Überbringer der Widerlegung als Person und misst dessen Argumenten deshalb kein Gewicht bei."],"correctIndex":0,"explanation":"Wer aus einer Gemeinschaft austritt, verliert nicht nur eine Überzeugung, sondern auch Freunde, Identität, das Gefühl besonderen Wissens und die investierte Zeit und das Geld. Menschen gewichten Verluste meist stärker als gleich große Gewinne (Verlustaversion); wie stark, hängt von Methode und Lage ab. Deshalb kann der erwartete Verlust schwerer wiegen als der Gewinn, die Wahrheit zu erkennen, und diese Erklärung kommt mit ihrer geschilderten Lage aus. Die anderen Erklärungen brauchen zusätzliche Annahmen oder widersprechen ihren Worten: Einen Bestätigungsfehler widerlegt schon, dass sie einräumt, du könntest recht haben. Dass sie auf eine baldige Besserung hofft, wird nirgends erwähnt. Und von Misstrauen gegen dich als Person ist keine Rede, sie räumt deine Widerlegung ja sogar ein. Die Verlust-Erklärung beschreibt zudem einen Mechanismus, kein Urteil über die Intelligenz der Bekannten.","coreRule":"⚡ Wer fragt, warum jemand nicht geht, sollte zuerst fragen, was der Austritt ihn kosten würde, nicht nur, ob er recht hat.","beleg":"Werkstück B.28 (Anwendung: Verschwörungsmythen & Kulte)","status":"entwurf","kurz":"Mit der geschilderten Lage kommt die Verlust-Erklärung aus: Ein Austritt kostet Freunde, Rolle, Besonderheitsgefühl und Investiertes, und Verluste wiegen meist schwerer als gleich große Gewinne, auch der Gewinn, die Wahrheit zu erkennen.","prueffrage":"Was hängt für sie außer der Frage, ob die Behauptungen stimmen, noch an dieser Gemeinschaft?","rueckmeldung":[{"option":1,"text":"Bestätigungsfehler sind real, aber hier passt er nicht zu ihren Worten: Wer die Widerlegung gar nicht aufnimmt, räumt nicht ein, dass du recht haben könntest. Sie hat das Argument offenbar verstanden und bleibt trotzdem."},{"option":2,"text":"Übertriebener Optimismus kommt bei Menschen in Gruppen durchaus vor. Im Szenario steht aber nichts von der Hoffnung auf eine baldige Besserung; diese Erklärung müsste erst eine Annahme einführen, die die Lage nicht hergibt."},{"option":3,"text":"Misstrauen gegen den Überbringer kann Argumente tatsächlich entwerten, doch dafür gibt es hier keinen Hinweis. Im Gegenteil: Sie räumt ein, dass du recht haben könntest. Dann tut sie dein Argument gerade nicht als wertlos ab."}],"familie":"aus-ihrer-lage-urteilen","fertigkeit":"F2","quellen":[{"typ":"doi","kurz":"Kahneman, D.; Knetsch, J. L.; Thaler, R. H. (1991): Anomalies: The Endowment Effect, Loss Aversion, and Status Quo Bias. Journal of Economic Perspectives 5(1), 193–206","oeffentlich":true,"doi":"10.1257/jep.5.1.193","url":"https://www.aeaweb.org/articles?id=10.1257/jep.5.1.193","abruf":"2026-10-12"},{"typ":"doi","kurz":"Brown, A. L.; Imai, T.; Vieider, F. M.; Camerer, C. F. (2024): Meta-Analysis of Empirical Estimates of Loss Aversion (Preprint MetaArXiv)","oeffentlich":true,"doi":"10.31222/osf.io/hnefr","abruf":"2026-10-12"}],"thema":"Zusammenleben","pruefung":{"lauf":"quiz-audit-v3","modell":"claude-sonnet-5-5","datum":"2026-10-13","urteil":"ok","pruefsumme":"24bba58586d2a3d9"}},{"id":"qx-b2-048","clusterId":"B","werkstueckRef":"B.28","stufe":2,"question":"Welche Frage prüft am besten, ob du das Abo behalten solltest?","scenario":"Seit Jahren läuft von deinem Konto ein Abo ab, das du kaum noch nutzt. Eine Freundin sagt: „Kündige es doch einfach.“ Du antwortest: „Aber ich habe schon so viel dafür bezahlt, das kann ich jetzt nicht wegwerfen.“","options":["Waren meine Gründe für den Abschluss damals überzeugend, und war es rückblickend eine gute Entscheidung, das Abo abzuschließen?","Wenn ich das Abo heute nicht hätte, würde ich es jetzt neu abschließen und dafür diesen Aufwand an Geld und Zeit betreiben?","Wie groß ist der mögliche Verlust, wenn ich kündige, verglichen mit dem möglichen Gewinn, wenn ich einfach weitermache wie bisher?","Wie viele andere Menschen haben das Abo behalten, und was wissen sie vielleicht, das ich bisher noch nicht gesehen habe?"],"correctIndex":1,"explanation":"Eine gute Entscheidung schaut nach vorn: Was bringt mir das Abo ab jetzt, und was kostet es mich ab jetzt? Am klarsten wird das, wenn man sich vorstellt, man besäße es nicht, und fragt, ob man heute Geld und Zeit dafür aufwenden würde. Das bereits Eingezahlte ist nicht mehr zurückzuholen, egal ob du kündigst oder nicht. Wer darauf schaut, wirft gutes Geld schlechtem hinterher (versunkene Kosten). Die Frage, ob der Abschluss damals gut begründet war, schaut zurück und ändert nichts daran, was das Abo ab jetzt bringt. Der Blick auf das, was andere tun, beantwortet nicht die Frage, was das Abo dir ab jetzt bringt. Und die Abwägung „Verlust bei Kündigung gegen Gewinn beim Weitermachen“ bleibt am aktuellen Besitz als Referenzpunkt hängen, sodass Kündigen als Verlust kodiert wird.","coreRule":"⚡ Frag nicht, was du schon investiert hast, sondern ob du heute neu einsteigen würdest.","quote":"würde ich mein Geld, meine Zeit oder meinen Verstand heute dafür aufwenden, um exakt hier einzusteigen?","quoteLabel":"Prüffrage für festgefahrene Entscheidungen:","beleg":"Werkstück B.28 (Anti-Denkmuster: Clean-Slate-Test; Werkbank-Frage)","status":"entwurf","kurz":"Entscheidend ist, was das Abo dir ab jetzt bringt und kostet. Die bereits gezahlten Beträge sind weg, ob du kündigst oder nicht. Wer sie mitzählt, verfällt den versunkenen Kosten; die Neu-Abschluss-Frage blendet sie aus.","prueffrage":"Welcher Teil der Kosten hängt davon ab, ob du heute kündigst oder behältst, und welcher steht ohnehin fest?","rueckmeldung":[{"option":0,"text":"Gute Gründe damals sprechen für die damalige Entscheidung. Doch sie lassen offen, was das Abo heute bringt und kostet, und genau das entscheidet, ob du es jetzt behalten solltest."},{"option":2,"text":"Verlust und Gewinn abzuwägen klingt sachlich. Hier ist aber das Weiterlaufen als Normalzustand gesetzt, sodass Kündigen automatisch wie ein Verlust aussieht. Der Ausgangspunkt färbt die Rechnung schon vor."},{"option":3,"text":"Was andere tun, kann manchmal Hinweise geben. Hier fehlt aber jeder Anhaltspunkt, dass sie das Abo ähnlich nutzen wie du. Ihr Verhalten sagt nicht, was es dir ab jetzt bringt."}],"familie":"versunkene-kosten","fertigkeit":"F4","quellen":[{"typ":"doi","kurz":"Watzek, J.; Brosnan, S. F. (2020): Capuchin and rhesus monkeys show sunk cost effects in a psychomotor task. Scientific Reports 10, 20396","oeffentlich":true,"doi":"10.1038/s41598-020-77301-w","url":"https://pmc.ncbi.nlm.nih.gov/articles/PMC7683735/","abruf":"2026-10-12"},{"typ":"doi","kurz":"Arkes, H. R.; Blumer, C. (1985): The Psychology of Sunk Cost. Organizational Behavior and Human Decision Processes 35(1), 124–140","oeffentlich":false,"doi":"10.1016/0749-5978(85)90049-4"},{"typ":"doi","kurz":"Kahneman, D.; Knetsch, J. L.; Thaler, R. H. (1991): Anomalies: The Endowment Effect, Loss Aversion, and Status Quo Bias. Journal of Economic Perspectives 5(1), 193–206","oeffentlich":true,"doi":"10.1257/jep.5.1.193","url":"https://www.aeaweb.org/articles?id=10.1257/jep.5.1.193","abruf":"2026-10-12"}],"thema":"Geld und Zahlen","pruefung":{"lauf":"quiz-audit-v3","modell":"claude-sonnet-5-5","datum":"2026-10-13","urteil":"ok","pruefsumme":"8b3c58cf14dcc27b"}},{"id":"qx-b2-049","clusterId":"B","werkstueckRef":"B.29","stufe":2,"question":"Was ist an Lenas Schlussfolgerung fehlerhaft?","options":["Sie schließt aus dem Nicht-Finden auf das Nicht-Vorhandensein, obwohl Verzerrungen meist unbewusst ablaufen und sich durch bloßes Nach-innen-Schauen gar nicht zeigen.","Sie verallgemeinert vom Verhalten ihres einen Kollegen auf alle Menschen, obwohl ein einzelner Fall keine sichere Aussage über viele Menschen zulässt.","Sie stützt ihre Selbstbewertung auf das Urteil Dritter statt auf eigene Prüfung, obwohl die Meinung anderer nichts über ihre Verzerrungen beweist.","Sie überschätzt ihre Fähigkeit, Verzerrungen zu erkennen, weil Anfänger ihr Können oft besonders hoch einschätzen (Dunning-Kruger-Effekt)."],"correctIndex":0,"explanation":"Lena beurteilt sich über ihre Gedanken und Absichten, den Kollegen aber über sein sichtbares Verhalten. In ihren Gedanken findet sie fast immer gute Absichten. Die meisten Verzerrungen laufen jedoch unbewusst ab und sind durch einfaches Nach-innen-Schauen grundsätzlich nicht auffindbar. Aus „ich finde nichts“ folgt deshalb nicht „da ist nichts“. Zuverlässiger ist ein Blick von außen: ihr eigenes Verhalten prüfen (Welche Gegenargumente ignoriere ich? Welche Quellen nutze ich?) oder jemanden bitten, die eigene Position auseinanderzunehmen. Die anderen Gedanken benennen bekannte Fehler, die Lena hier nicht begeht: Sie verallgemeinert nicht vom Kollegen auf alle, sondern spricht über sich selbst. Von Urteilen Dritter ist keine Rede, sie stützt sich allein auf ihr Nach-innen-Schauen. Und einen Hinweis auf mangelnde Kompetenz nennt das Szenario nicht, ihr Problem liegt in der Methode.","coreRule":"⚡ Wer nur in sich hineinschaut, findet gute Absichten und übersieht die Verzerrung.","beleg":"Werkstück B.29 (Analyse: Der Introspektions-Trugschluss)","status":"entwurf","scenario":"Lena arbeitet sich durch eine Liste typischer Denkfehler. Bei ihrem Kollegen erkennt sie sofort, dass er nur Studien zitiert, die seine Meinung stützen. Danach prüft sie sich selbst: Sie geht in Gedanken durch, was sie bei ihrer eigenen Position antreibt, findet dort nur den Wunsch, die Wahrheit herauszufinden, und stellt fest: „Bei mir ist keine Voreingenommenheit im Spiel.“","kurz":"Wer nur nach innen schaut, findet fast immer gute Absichten, doch Verzerrungen laufen meist unbewusst ab. Aus „ich finde nichts“ folgt daher nicht „da ist nichts“. Verlässlicher ist der Blick auf das eigene Verhalten oder auf eine Kritik von außen.","prueffrage":"Woran würde man bei Lena und bei ihrem Kollegen jeweils erkennen, ob Voreingenommenheit im Spiel ist?","rueckmeldung":[{"option":1,"text":"Verallgemeinern von einem Einzelfall ist ein bekannter Fehler. Lena zieht aus dem Kollegen aber gar keinen Schluss auf andere, ihre Aussage betrifft nur sich selbst. Der Fehler liegt woanders: in der Art, wie sie sich beurteilt."},{"option":2,"text":"Das Urteil anderer sagt tatsächlich nichts über die eigenen Verzerrungen. Im Szenario beruft sich Lena aber auf niemanden, sie stützt sich allein auf ihr Nach-innen-Schauen. Der Kollege dient nur als Vergleich."},{"option":3,"text":"Selbstüberschätzung bei geringem Können gibt es. Das Szenario sagt aber nichts über Lenas Kompetenz. Ihr Problem liegt in der Methode: Nach-innen-Schauen reicht bei Verzerrungen grundsätzlich nicht, auch bei erfahrenen Menschen."}],"familie":"werkzeuge-gegen-sich-selbst","fertigkeit":"F5","quellen":[{"typ":"url","kurz":"Pronin, E. (2007): Perception and misperception of bias in human judgment. Trends in Cognitive Sciences 11(1), 37–43 (Zusammenfassung frei auf PubMed)","oeffentlich":true,"doi":"10.1016/j.tics.2006.11.001","url":"https://pubmed.ncbi.nlm.nih.gov/17129749/","abruf":"2026-10-12"},{"typ":"doi","kurz":"Pronin, E.; Kugler, M. B. (2007): Valuing thoughts, ignoring behavior: The introspection illusion as a source of the bias blind spot. Journal of Experimental Social Psychology 43(4), 565–578","oeffentlich":false,"doi":"10.1016/j.jesp.2006.05.011"}],"thema":"Psychologie","pruefung":{"lauf":"quiz-audit-v3","modell":"claude-sonnet-5-5","datum":"2026-10-13","urteil":"ok","pruefsumme":"264202272bb41376"}},{"id":"qx-b2-050","clusterId":"B","werkstueckRef":"B.29","stufe":3,"question":"Was ist an Jonas' Schlussfolgerung am problematischsten?","options":["Er schließt aus seinem Wissen über Denkfehler, dass er selbst gegen sie immun ist, obwohl nach Befunden selbst höhere kognitive Fähigkeit den blinden Fleck nicht verkleinert.","Er schließt vom Verhalten seines einen Kollegen auf alle Menschen ohne Statistikstudium, obwohl ein einzelner Fall keine Aussage über viele Menschen trägt.","Er stützt sein Selbstbild auf das Lob seiner Vorgesetzten statt auf eigene Prüfung, obwohl ein Lob nichts über seine unbewussten Verzerrungen verrät.","Er hält seine Position für richtig, weil bisher niemand widersprochen hat, obwohl ausbleibender Widerspruch noch nicht zeigt, dass eine Aussage stimmt."],"correctIndex":0,"explanation":"Die meisten Verzerrungen wirken unbewusst. Wer nach innen schaut, findet meist gute Absichten und schließt daraus, dass keine Voreingenommenheit im Spiel ist. Auch Klugheit schützt nicht: In einer Studie von West, Meserve und Stanovich (2012) mit Studierenden verkleinerten weder höhere kognitive Fähigkeit noch einschlägige Denkstile den blinden Fleck, wenn überhaupt ging höhere Fähigkeit mit einem etwas größeren einher. Eine mögliche Erklärung: Klügere können ihre voreingenommenen Schlüsse geschickter rational begründen. Daraus folgt für Jonas: Sein Wissen macht ihn vor allem besser darin, Fehler bei anderen zu entdecken, nicht bei sich selbst. Sinnvoller wäre ein externer Check, etwa jemanden zu bitten, die eigene Position gezielt zu zerlegen. Die anderen Einwände greifen Fehler auf, die Jonas nicht begeht: Er verallgemeinert nicht von seinem Kollegen auf viele andere. Er beruft sich auf kein Lob von Dritten, und er leitet nichts aus ausbleibendem Widerspruch ab.","coreRule":"⚡ Wissen über Denkfehler und hohe Intelligenz schützen nicht vor dem eigenen blinden Fleck; prüfe dich von außen, nicht nur durch Nach-innen-Schauen.","beleg":"Werkstück B.29 (Analyse: Intelligenz schützt nicht); Fn. gl-b-blindspot (West/Meserve/Stanovich 2012, JPSP 103(3), S. 511, 515)","status":"entwurf","scenario":"In einer Diskussion über einen Zeitungsartikel sagt Jonas: „Ich habe Statistik und Logik studiert und kenne die gängigen Denkfehler in- und auswendig. Von denen lasse ich mich nicht mehr täuschen. Bei meinem Kollegen erkenne ich sie sofort, bei mir selbst ist das kein Thema.“","kurz":"Wissen über Denkfehler macht vor allem besser darin, sie bei anderen zu entdecken. Der Fehler liegt im Schluss „Ich kenne sie, also bin ich gefeit“: Die meisten Verzerrungen wirken unbewusst, und selbst höhere Fähigkeit verkleinert den blinden Fleck meist nicht.","prueffrage":"Worauf stützt Jonas seine Aussage, bei ihm selbst seien Denkfehler kein Thema?","rueckmeldung":[{"option":1,"text":"Ein einzelner Fall trägt tatsächlich keine Aussage über viele. Jonas sagt aber nur, dass er die Fehler bei seinem Kollegen erkennt, und macht daraus keine Regel über alle anderen Menschen."},{"option":2,"text":"Dass ein Lob nichts über unbewusste Verzerrungen verrät, stimmt. Im Szenario kommt aber gar kein Lob vor: Jonas beruft sich auf sein Studium und sein Wissen, nicht auf die Meinung Dritter."},{"option":3,"text":"Fehlender Widerspruch beweist in der Tat nicht, dass eine Aussage stimmt. Jonas begründet seine Position jedoch nicht damit, in der Diskussion widerspricht ihm niemand. Sein Schluss läuft von seinem Wissen auf seine angebliche Immunität."}],"familie":"werkzeuge-gegen-sich-selbst","fertigkeit":"F5","quellen":[{"typ":"url","kurz":"West, R. F.; Meserve, R. J.; Stanovich, K. E. (2012): Cognitive Sophistication Does Not Attenuate the Bias Blind Spot. Journal of Personality and Social Psychology 103(3), 506–519 (Zusammenfassung frei auf PubMed)","oeffentlich":true,"doi":"10.1037/a0028857","url":"https://pubmed.ncbi.nlm.nih.gov/22663351/","abruf":"2026-10-12"},{"typ":"url","kurz":"Pronin, E. (2007): Perception and misperception of bias in human judgment. Trends in Cognitive Sciences 11(1), 37–43 (Zusammenfassung frei auf PubMed)","oeffentlich":true,"doi":"10.1016/j.tics.2006.11.001","url":"https://pubmed.ncbi.nlm.nih.gov/17129749/","abruf":"2026-10-12"}],"thema":"Psychologie","pruefung":{"lauf":"quiz-audit-v3","modell":"claude-sonnet-5-5","datum":"2026-10-13","urteil":"ok","pruefsumme":"103aba27367c4517"}},{"id":"qx-b2-051","clusterId":"B","werkstueckRef":"B.29","stufe":4,"question":"Was solltest du als Nächstes tun, um herauszufinden, ob du selbst voreingenommen bist?","scenario":"In einer hitzigen Diskussion über Ernährung bist du überzeugt, der Einzige am Tisch zu sein, der objektiv urteilt. Du hast viel über Denkfehler gelesen und erkennst bei deinem Gegenüber sofort Bestätigungsfehler und selektive Quellenwahl.","options":["Du bittest eine vertraute Person mit anderer Meinung, dein Argument nach Kräften auseinanderzunehmen, und hörst zunächst nur zu.","Du prüfst genau, ob die Studien deines Gegenübers methodisch sauber sind und seine Schlüsse daraus tragen.","Du nimmst dir einen Tag Abstand und gehst deine Argumente danach in Ruhe allein noch einmal Punkt für Punkt durch.","Du suchst weitere hochwertige Studien zu deinem Standpunkt, damit deine Position auf einer breiteren Belegbasis steht."],"correctIndex":0,"explanation":"Die meisten Verzerrungen wirken unbewusst. Von innen suchst du mit demselben Gehirn, das den Fehler macht: Findest du keine Voreingenommenheit, heißt das nicht, dass keine da ist. Klüger zu sein schützt kaum davor. In einer Studie ging höhere kognitive Fähigkeit sogar eher mit einem größeren blinden Fleck einher, und kluge Menschen können voreingenommene Schlüsse oft geschickter rechtfertigen. Was von innen unsichtbar bleibt, kann ein Blick von außen sichtbar machen: Jemand, der anderer Meinung ist und dein Argument ernsthaft angreift, findet Lücken, die du selbst nicht siehst. Dass du dann zunächst nur zuhörst, verhindert, dass du die Kritik sofort wegerklärst. Die Studien des Gegenübers zu prüfen ist sinnvoll, sagt aber etwas über seine Quellen und nichts über deine eigene Verzerrung. Abstand und Nachdenken allein helfen gegen Hitze, nicht gegen einen blinden Fleck, den dasselbe Denken erzeugt. Und weitere Belege für den eigenen Standpunkt zu sammeln bestätigt ihn nur, statt ihn zu testen.","coreRule":"⚡ Was du von innen nicht siehst, zeigt dir nur ein Blick von außen.","beleg":"Werkstück B.29 (Anti-Denkmuster: Die wirksamste Taktik; Anwendung: Der intellektuelle Skeptiker)","status":"entwurf","kurz":"Voreingenommenheit wirkt meist unbemerkt, und von innen suchst du mit demselben Denken, das den Fehler macht. Erst jemand mit anderer Sicht, den du zunächst nur anhörst, kann Lücken zeigen, die du selbst nicht siehst.","prueffrage":"Wer hat dein eigenes Argument in dieser Diskussion bisher überhaupt auf Schwächen geprüft?","rueckmeldung":[{"option":1,"text":"Die Studien des Gegenübers zu prüfen ist sinnvoll, sagt aber nur etwas über seine Quellen. Ob du selbst verzerrt urteilst, bleibt dabei unberührt, denn die Prüfung richtet sich nach außen."},{"option":2,"text":"Ein Tag Abstand kühlt die Hitze der Diskussion ab. Dasselbe Denken, das einen blinden Fleck erzeugt, geht deine Argumente aber erneut durch und übersieht ihn deshalb sehr wahrscheinlich wieder."},{"option":3,"text":"Weitere gute Studien machen deine Position vielleicht breiter belegt, aber sie testen sie nicht. Wer nur Belege für den eigenen Standpunkt sammelt, bestätigt ihn und macht genau das, was du beim anderen kritisierst."}],"familie":"werkzeuge-gegen-sich-selbst","fertigkeit":"F5","quellen":[{"typ":"url","kurz":"West, R. F.; Meserve, R. J.; Stanovich, K. E. (2012): Cognitive Sophistication Does Not Attenuate the Bias Blind Spot. Journal of Personality and Social Psychology 103(3), 506–519 (Zusammenfassung frei auf PubMed)","oeffentlich":true,"doi":"10.1037/a0028857","url":"https://pubmed.ncbi.nlm.nih.gov/22663351/","abruf":"2026-10-12"},{"typ":"url","kurz":"Pronin, E. (2007): Perception and misperception of bias in human judgment. Trends in Cognitive Sciences 11(1), 37–43 (Zusammenfassung frei auf PubMed)","oeffentlich":true,"doi":"10.1016/j.tics.2006.11.001","url":"https://pubmed.ncbi.nlm.nih.gov/17129749/","abruf":"2026-10-12"}],"thema":"Gesundheit","pruefung":{"lauf":"quiz-audit-v3","modell":"claude-sonnet-5-5","datum":"2026-10-13","urteil":"korrigieren","pruefsumme":"084c5fd8ce3ab53f"}},{"id":"qx-b2-052","clusterId":"B","werkstueckRef":"B.29","stufe":1,"question":"Wie lässt sich am besten erklären, was in dieser Situation passiert?","options":["Lena richtet ihr Urteil an der ersten Aussage aus, die in der Diskussion fiel, und misst alle späteren Argumente daran (Ankereffekt).","Lena nimmt an, dass die meisten Anwesenden ihre Sicht teilen, und hält andere Meinungen deshalb für Ausnahmen (falscher Konsens).","Lena hält sich für objektiver als andere, weil sie in sich hineinhorcht und dort nur gute Absichten findet (blinder Fleck für eigene Verzerrungen).","Lena übernimmt ihre Meinung ungeprüft von einer anerkannten Fachperson, nur weil diese Autorität besitzt (Autoritätsargument)."],"correctIndex":2,"explanation":"Lena misst Tom an seinem Verhalten, sich selbst aber an ihren Absichten: Sie horcht in sich hinein, findet dort nur den Wunsch nach Wahrheit und hält sich deshalb für objektiver. Viele Verzerrungen wirken jedoch unbewusst und zeigen sich beim Nach-innen-Schauen nicht; aus „nichts gefunden“ folgt nicht „nichts da“. Ihr eigener Schreibtisch zeigt dasselbe Muster, das sie Tom vorwirft. Ein Ankereffekt passt nicht, denn Lena beruft sich auf keine erste Aussage, sondern auf ihre eigene Innenschau. Für einen falschen Konsens gibt es keinen Hinweis, denn sie spricht nur über Tom und sich selbst, nicht über eine Mehrheit im Raum. Und ein Autoritätsargument liegt nicht vor, denn sie übernimmt nichts von einer Fachperson, sondern verlässt sich auf ihr eigenes Urteil.","coreRule":"⚡ Was du bei anderen sofort siehst, übersiehst du bei dir selbst am leichtesten.","beleg":"Werkstück B.29 (Kernidee; Eingangsszene; Introspektions-Trugschluss)","status":"entwurf","scenario":"Lena erklärt in einer hitzigen Diskussion: „Mein Kollege Tom sieht nur die Quellen, die zu seiner Meinung passen, und ignoriert alles andere. Der ist komplett voreingenommen. Ich dagegen suche einfach die Wahrheit.“ Wenn man sich ihren Schreibtisch anschaut, stellt man fest: Auch sie hat fast nur Artikel gesammelt, die ihre eigene Position stützen. Auf Nachfrage sagt sie: „Ich habe nachgedacht und bei mir keine Voreingenommenheit gefunden.“","kurz":"Lena misst Tom an seinem Verhalten, sich selbst aber an ihren Absichten. Beim Nach-innen-Schauen zeigen sich viele Verzerrungen nicht; aus „nichts gefunden“ folgt nicht „nichts da“, wie schon ihr einseitig gefüllter Schreibtisch zeigt.","prueffrage":"Was liegt auf Lenas Schreibtisch, und wie passt das zu ihrem Urteil über sich selbst?","rueckmeldung":[{"option":0,"text":"Ankereffekte gibt es wirklich, im Szenario fehlt aber jede erste Aussage, an der Lena spätere Argumente misst. Sie beruft sich auf ihre eigene Innenschau („bei mir keine Voreingenommenheit gefunden“), nicht auf einen Ausgangspunkt der Diskussion."},{"option":1,"text":"Für einen falschen Konsens müsste Lena annehmen, dass die meisten ihre Sicht teilen. Davon steht nichts im Szenario: Sie spricht nur über Tom und sich selbst, nicht über eine Mehrheit im Raum."},{"option":3,"text":"Ein Autoritätsargument braucht eine Fachperson, auf die man sich beruft. Lena übernimmt aber nichts von anderen, sondern verlässt sich ganz auf ihr eigenes Urteil. Das Problem liegt in der Selbsteinschätzung, nicht in einer fremden Quelle."}],"familie":"werkzeuge-gegen-sich-selbst","fertigkeit":"F5","quellen":[{"typ":"doi","kurz":"Pronin, E.; Kugler, M. B. (2007): Valuing thoughts, ignoring behavior: The introspection illusion as a source of the bias blind spot. Journal of Experimental Social Psychology 43(4), 565–578","oeffentlich":false,"doi":"10.1016/j.jesp.2006.05.011"},{"typ":"url","kurz":"Pronin, E. (2007): Perception and misperception of bias in human judgment. Trends in Cognitive Sciences 11(1), 37–43 (Zusammenfassung frei auf PubMed)","oeffentlich":true,"doi":"10.1016/j.tics.2006.11.001","url":"https://pubmed.ncbi.nlm.nih.gov/17129749/","abruf":"2026-10-12"}],"thema":"Psychologie","pruefung":{"lauf":"quiz-audit-v3","modell":"claude-sonnet-5-5","datum":"2026-10-13","urteil":"ok","pruefsumme":"b6d3ede196848057"}},{"id":"qx-b2-053","clusterId":"B","werkstueckRef":"B.30","stufe":1,"question":"Warum ist Rot im nächsten Spiel nicht wahrscheinlicher als im ersten Spiel des Abends?","scenario":"Ein Freund erzählt dir: „Im Kasino ist die Roulettekugel gestern zwanzigmal hintereinander auf Schwarz gefallen. Ich setze jetzt alles auf Rot, nach so einer Serie muss Rot einfach kommen.“ Der Tisch ist unauffällig und funktioniert einwandfrei.","options":["Die Null gehört keiner Farbe an: Die Chance auf Rot liegt unter 50 Prozent, und die Wette lohnt sich auf Dauer nicht.","Das Risiko ist hoch: Wer alles auf eine einzige Wette setzt, riskiert einen Totalverlust, gleich welche Farbe er wählt.","Eine solche Serie ist selten: Zwanzigmal dieselbe Farbe in Folge tritt für sich genommen äußerst unwahrscheinlich auf.","Die Kugel hat kein Gedächtnis: Bei unabhängigen Zufallsereignissen ist die Chance in jedem Spiel dieselbe, was zuvor auch fiel."],"correctIndex":3,"explanation":"Jedes Spiel ist ein neuer, unabhängiger Wurf. Die Kugel weiß nicht, was vorher gefallen ist, also bleibt die Chance auf Rot unverändert. Auch das Gesetz der großen Zahlen gleicht nichts aus, es verdünnt frühe Abweichungen nur: Über Tausende Spiele fällt eine frühe Serie immer weniger ins Gewicht, ohne dass der Zufall etwas nachholen müsste. Wer nach einer Serie auf die Gegenseite setzt, begeht den Spielerfehlschluss. Die Frage, die ihn entlarvt: Weiß das Ding, das hier „würfelt“, was vorher passiert ist? Wenn nicht, ist der nächste Wurf ein erster Wurf. Die anderen Gedanken sind für sich richtig, beantworten die Frage aber nicht: Dass die Null keiner Farbe gehört, drückt die Chance auf Rot in jedem Spiel gleich stark, am Anfang des Abends wie jetzt. Das Risiko eines Totalverlusts besteht bei jedem Einsatz und sagt nichts darüber, ob die Serie etwas verändert hat. Und selten ist die ganze Serie von zwanzig Würfen, nicht der einzelne nächste Wurf.","coreRule":"⚡ Zufall gleicht nichts aus: Münze, Kugel und Würfel haben kein Gedächtnis.","beleg":"Werkstück B.30 (Eingangsszene; Kernidee; Analyse); Fn. gl-b-montecarlo (Huff 1959; Zahl nicht durch Kasinoprotokolle belegt); Fn. gl-b-tversky (Tversky/Kahneman 1971, S. 105–106)","status":"entwurf","kurz":"Die Kugel weiß nicht, was vorher gefallen ist, also ist der nächste Wurf wie ein erster. Der Fehler: nach einer Serie auf einen Ausgleich zu hoffen, als müsste der Zufall etwas nachholen.","prueffrage":"Wie viele rote und wie viele schwarze Fächer hat der Kessel vor dem ersten Spiel des Abends, und wie viele nach der Serie?","rueckmeldung":[{"option":0,"text":"Dass die Null keiner Farbe gehört, stimmt und drückt die Chance auf Rot unter 50 Prozent. Sie tut das aber in jedem Spiel gleich stark, am Anfang des Abends wie jetzt, und erklärt daher nicht, ob die Serie etwas verändert."},{"option":1,"text":"Wer alles auf eine Wette setzt, riskiert tatsächlich den Totalverlust, bei Rot wie bei Schwarz. Dieses Risiko besteht bei jedem Einsatz und sagt nichts darüber, ob die vorherige Serie die Chance auf Rot verändert hat."},{"option":2,"text":"Zwanzigmal dieselbe Farbe ist als ganze Serie tatsächlich selten. Der nächste einzelne Wurf aber ist nicht selten oder besonders: Er hängt nicht von den früheren ab, und seine Chance bleibt unverändert."}],"familie":"zufall-ohne-gedaechtnis","fertigkeit":"F4","quellen":[{"typ":"url","kurz":"Dowden, B. H.: Fallacies. Internet Encyclopedia of Philosophy (Eintrag „Gambler’s“)","oeffentlich":true,"url":"https://iep.utm.edu/fallacy/","abruf":"2026-10-12"},{"typ":"doi","kurz":"Tversky, A.; Kahneman, D. (1971): Belief in the law of small numbers. Psychological Bulletin 76(2), 105–110","oeffentlich":false,"doi":"10.1037/h0031322"}],"thema":"Geld und Zahlen","pruefung":{"lauf":"quiz-audit-v3","modell":"claude-sonnet-5-5","datum":"2026-10-13","urteil":"ok","pruefsumme":"5f53ecd470444efe"}},{"id":"qx-b2-054","clusterId":"B","werkstueckRef":"B.30","stufe":2,"question":"Was ist an ihrem Vorgehen fehlerhaft?","scenario":"Eine Kreditprüferin hat drei Anträge hintereinander bewilligt. Beim vierten Antrag, der den anderen vom Risiko her gleicht, will sie ablehnen – „nur um nicht immer dasselbe zu entscheiden“.","options":["Sie behandelt die Reihe der Entscheidungen so, als müsse sie sich ausgleichen, obwohl jeder Antrag für sich zu beurteilen ist.","Sie schließt aus drei Bewilligungen auf die Qualität aller künftigen Antragsteller, obwohl drei Fälle eine zu kleine Stichprobe sind.","Sie bleibt aus Gewohnheit bei ihrer bisherigen Linie, obwohl der neue Antrag eine andere Beurteilung verdienen würde.","Sie lässt sich von persönlichen Merkmalen der Antragsteller leiten, obwohl allein das Ausfallrisiko über die Bewilligung entscheiden sollte."],"correctIndex":0,"explanation":"Jeder Antrag ist für sich zu bewerten; die vorherigen Entscheidungen sagen nichts über den nächsten Fall. Wer nach einer Serie das Gegenteil wählt, damit sich die Reihe „ausgleicht“, unterliegt dem Spielerfehlschluss: Er unterstellt einem Ablauf ohne Gedächtnis einen Ausgleichsdrang. Das ist kein Randphänomen: Chen, Moskowitz und Shue (2016) werteten über 150.000 Asylentscheidungen, rund 1,5 Millionen Schiedsrichter-Entscheidungen und gut 9.000 Kreditprüfungen aus einem Feldexperiment aus. Asylrichter, Kreditprüfer und Baseball-Schiedsrichter schwenkten nach einer oder mehreren gleichartigen Entscheidungen um einige Prozentpunkte häufiger „um“, und zwar umso öfter, je länger die Serie war. Ein Antrag verdient eine eigene Prüfung. Die Entscheidungen davor sind kein Argument. Die anderen Gedanken sind für sich bedenkenswert, treffen hier aber nicht zu: Die Prüferin schließt nichts über künftige Antragsteller, sie will nur die Reihe ausgleichen. Sie hält auch nicht an ihrer Linie fest, im Gegenteil, sie will von ihr abweichen. Und von persönlichen Merkmalen der Antragsteller ist nicht die Rede, der Antrag gleicht den anderen vom Risiko her.","coreRule":"⚡ Jeder Fall beginnt neu: Die Entscheidung davor darf die Entscheidung jetzt nicht färben.","beleg":"Werkstück B.30 (Anwendung: Urteile unter Serien; Zahlen und Befund laut Buchtext); Fn. gl-b-chen (Chen/Moskowitz/Shue 2016, QJE 131(3), S. 1181–1242)","status":"entwurf","kurz":"Jeder Antrag ist für sich zu beurteilen, denn die Fälle davor sagen nichts über den nächsten. Der Fehler liegt darin, einer Folge ohne Gedächtnis einen Ausgleichsdrang zu unterstellen: Gleiches Risiko heißt gleiche Entscheidung.","prueffrage":"Worin unterscheidet sich der vierte Antrag vom Risiko her von den drei bereits bewilligten?","rueckmeldung":[{"option":1,"text":"Dass drei Fälle wenig hergeben, stimmt allgemein. Hier aber zieht die Prüferin gar keinen Schluss auf künftige Antragsteller; sie will nur ihre eigene Reihe ausgleichen. Der Fehler liegt woanders."},{"option":2,"text":"Die Gewohnheit liegt nahe, wenn man an Routine denkt. Die Prüferin will aber gerade von ihrer bisherigen Linie abweichen, und der Antrag gleicht den anderen vom Risiko her. Eine andere Beurteilung wäre also gar nicht gerechtfertigt."},{"option":3,"text":"Entscheidungen nach persönlichen Merkmalen wären tatsächlich ein Problem, und allein das Risiko sollte zählen. Davon ist im Fall aber nicht die Rede: Der Antrag gleicht den anderen vom Risiko her, ihr Motiv ist reine Abwechslung."}],"familie":"zufall-ohne-gedaechtnis","fertigkeit":"F4","quellen":[{"typ":"url","kurz":"Chen, D. L.; Moskowitz, T. J.; Shue, K. (2016): Decision-Making under the Gambler's Fallacy: Evidence from Asylum Judges, Loan Officers, and Baseball Umpires. NBER Working Paper 22026","oeffentlich":true,"url":"https://www.nber.org/papers/w22026","seite":"14, 27","abruf":"2026-10-12"}],"thema":"Geld und Zahlen","pruefung":{"lauf":"quiz-audit-v3","modell":"claude-sonnet-5-5","datum":"2026-10-13","urteil":"ok","pruefsumme":"b9622ca09104cf9c"}},{"id":"qx-b2-055","clusterId":"B","werkstueckRef":"B.30","stufe":3,"question":"Eine Basketballtrainerin sagt vor dem Spiel: „Wer drei Würfe in Folge getroffen hat, trifft mit höherer Wahrscheinlichkeit auch den vierten.“ Ein Kollege entgegnet: „Das ist derselbe Fehler wie beim Roulette, wo nach fünfmal Rot angeblich Schwarz ‚fällig‘ ist.“ Wie beurteilst du den Einwand des Kollegen?","options":["Der Einwand ist berechtigt, weil jeder Wurf zufällig ist und eine Trefferserie deshalb bei Spielern ebenso wenig etwas über den nächsten Wurf aussagt wie bei einer Kugel.","Der Einwand greift zu kurz, weil ein Spieler anders als eine Kugel ein Gedächtnis hat: Form und Konzentration können schwanken, sodass eine Serie tatsächlich etwas über den nächsten Wurf aussagen kann.","Der Einwand ist berechtigt, weil beim Basketball die größere Zahl der Würfe dafür sorgt, dass sich Serien im Lauf des Spiels zuverlässig ausgleichen.","Der Einwand greift zu kurz, weil eine Trefferserie im Sport immer eine Fortsetzung ankündigt, während Serien beim Roulette immer ein Ende ankündigen."],"correctIndex":1,"explanation":"Der Spielerfehlschluss gilt für unabhängige Zufallsereignisse: Eine Roulettekugel weiß nicht, was vorher geschah, also ist jeder Wurf ein erster Wurf. Ein Basketballspieler ist kein Zufallsgenerator, denn Menschen haben ein Gedächtnis, Münzen nicht. Der Glaube an die „heiße Hand“ (eine Serie setzt sich fort) galt nach Gilovich, Vallone und Tversky (1985) lange als reiner Denkfehler. Neuere Analysen zeigen allerdings, dass es bei Menschen echte, messbare Formschwankungen geben kann; Miller und Sanjurjo (2018) korrigierten einen statistischen Verzerrungseffekt der älteren Analyse. Dass sich Serien durch viele Würfe „ausgleichen“, trifft ebenfalls nicht zu: Das Gesetz der großen Zahlen verdünnt Abweichungen nur, es gleicht sie nicht aus. Wer beides in einen Topf wirft, übersieht die Frage, die entscheidet: Hat das Ding, das hier „würfelt“, ein Gedächtnis? Dass Serien sich immer ausgleichen oder immer fortsetzen, folgt dagegen weder für Kugeln noch für Spieler.","coreRule":"⚡ Prüfe zuerst, ob das, was die Serie erzeugt, ein Gedächtnis hat: Bei Roulettekugeln nie, bei Menschen kann eine Serie eine Ursache haben.","beleg":"Werkstück B.30 (Analyse); Fn. gl-b-hothand (Gilovich/Vallone/Tversky 1985, S. 295–314; Miller/Sanjurjo 2018, Econometrica 86(6), S. 2019–2047)","status":"entwurf","scenario":"","kurz":"Eine Roulettekugel hat kein Gedächtnis, ein Spieler schon: Form und Konzentration schwanken, sodass eine Serie hier etwas über den nächsten Wurf verraten kann. Wer beide Fälle gleichsetzt, übersieht, dass „Serien sagen nichts“ nur für unabhängige Ereignisse gilt.","prueffrage":"Wovon hängt bei einer Spielerin ab, ob ihr Wurf trifft, und wovon beim Roulette, in welchem Fach die Kugel liegen bleibt?","rueckmeldung":[{"option":0,"text":"Beim Roulette stimmt der Vergleich: Die Kugel hat kein Gedächtnis. Ein Spieler ist aber kein Zufallsgenerator, seine Form kann schwanken. Dass Serien bei ihm nichts aussagen können, folgt deshalb nicht allein daraus, dass Würfe unsicher sind."},{"option":2,"text":"Dass sich Serien über viele Würfe ausgleichen, erinnert an das Gesetz der großen Zahlen. Das verdünnt Abweichungen aber nur und gleicht nichts aus; entscheidend ist, ob sich ein Spieler anders verhält als eine Kugel."},{"option":3,"text":"Dass eine Serie beim Sport etwas aussagen kann, ist denkbar. „Immer“ geht aber zu weit, denn weder bei Spielern noch bei Kugeln folgt, dass sich Serien zwingend fortsetzen oder beenden. Beim Roulette sagt die Serie gar nichts."}],"familie":"zufall-ohne-gedaechtnis","fertigkeit":"F4","quellen":[{"typ":"url","kurz":"Miller, J. B.; Sanjurjo, A.: Surprised by the Hot Hand Fallacy? A Truth in the Law of Small Numbers. arXiv:1902.01265 (Autorenfassung; Econometrica 86(6), 2018, 2019–2047)","oeffentlich":true,"url":"https://arxiv.org/abs/1902.01265","abruf":"2026-10-12"},{"typ":"doi","kurz":"Gilovich, T.; Vallone, R.; Tversky, A. (1985): The hot hand in basketball: On the misperception of random sequences. Cognitive Psychology 17(3), 295–314","oeffentlich":false,"doi":"10.1016/0010-0285(85)90010-6"},{"typ":"url","kurz":"Dowden, B. H.: Fallacies. Internet Encyclopedia of Philosophy (Eintrag „Gambler’s“)","oeffentlich":true,"url":"https://iep.utm.edu/fallacy/","abruf":"2026-10-12"}],"thema":"Geld und Zahlen","pruefung":{"lauf":"quiz-audit-v3","modell":"claude-sonnet-5-5","datum":"2026-10-13","urteil":"ok","pruefsumme":"39dd1d8fc380a489"}},{"id":"qx-b2-056","clusterId":"B","werkstueckRef":"B.30","stufe":4,"question":"Wie lässt sich die Beobachtung am besten erklären, ohne in den Spielerfehlschluss zu geraten?","scenario":"Nach einer ungewöhnlich schlechten Woche hat dein Fitnessarmband für die Folgewoche wieder normalere Werte gezeigt. Ein Bekannter sagt: „Das hat sich eben ausgeglichen. Die schlechte Woche musste durch eine bessere wettgemacht werden.“","options":["Extreme Werte sind selten, deshalb folgt auf einen Ausreißer meist ein normalerer Wert. Dafür muss nichts „ausgeglichen“ werden.","Nach einer Ruhephase erholt sich der Körper und leistet danach mehr. Die schlechte Woche hat die gute also vorbereitet.","Wer seine Werte im Blick hat, verhält sich anders. Der schlechte Wert hat dich vermutlich zu mehr Bewegung angespornt.","Das Armband hat in der schlechten Woche ungenau gemessen. Die Folgewoche zeigt deshalb wieder die tatsächlichen Werte."],"correctIndex":0,"explanation":"Die Beobachtung selbst stimmt: Extreme Werte werden tatsächlich oft von normaleren gefolgt. Aber nicht, weil der Zufall etwas ausgleicht, sondern weil Extremwerte selten sind. Der Spielerfehlschluss dagegen unterstellt, dass eine Abweichung aktiv „ausgeglichen“ werden müsse. Das Gesetz der großen Zahlen gleicht aber nichts aus, es verdünnt Abweichungen nur: Frühe Ausreißer fallen immer weniger ins Gewicht, je mehr normale Werte dazukommen. Eine bessere Folgewoche ist also nicht „fällig“, sie ist einfach der wahrscheinlichere Normalfall. Die anderen Erklärungen sind im Einzelfall denkbar, stützen sich hier aber auf nichts: Dass die schlechte Woche eine bewusste Ruhephase war, nach der der Körper mehr leisten konnte, steht nirgends. Eine Verhaltensänderung durch den Blick aufs Armband wird ebenso wenig erwähnt, die Werte sind einfach normaler geworden. Und ein Messfehler wäre eine Zusatzannahme ohne jeden Hinweis, denn ungewöhnliche Werte beweisen noch kein defektes Gerät.","coreRule":"⚡ Auf Extremes folgt oft Normales, aber nicht, weil der Zufall etwas schuldig wäre.","beleg":"Werkstück B.30 (Verbindungen: Nicht zu verwechseln mit Regression zur Mitte; Analyse)","status":"entwurf","kurz":"Extreme Werte sind selten, darum folgt auf einen Ausreißer meist ein normalerer Wert. Der Fehler ist, darin einen Ausgleich zu sehen, den der Zufall „schuldet“: Er gleicht nichts aus, die normalere Woche ist schlicht der wahrscheinlichere Fall.","prueffrage":"Wie oft hat das Armband in früheren Wochen so schlechte Werte gezeigt, und wie oft normale?","rueckmeldung":[{"option":1,"text":"Dass sich der Körper nach Ruhe erholt, ist plausibel. Im Szenario steht aber nichts von einer Ruhephase, und „vorbereitet“ schmuggelt die Ausgleichsidee wieder hinein. Die normalere Folgewoche braucht diese Zusatzannahme nicht."},{"option":2,"text":"Wer seine Werte beobachtet, verhält sich tatsächlich manchmal anders. Hier ist davon aber nichts bekannt, die Werte sind einfach normaler geworden. Die Erklärung ist denkbar, bleibt jedoch eine Vermutung ohne Anhaltspunkt."},{"option":3,"text":"Ein Messfehler ist grundsätzlich möglich, im Szenario gibt es dafür aber keinen Hinweis. Ungewöhnliche Werte allein beweisen kein ungenaues Gerät, und die Beobachtung lässt sich auch ohne diese Zusatzannahme erklären."}],"familie":"was-waere-ohne","fertigkeit":"F2","quellen":[{"typ":"url","kurz":"Dowden, B. H.: Fallacies. Internet Encyclopedia of Philosophy (Einträge „Regression“, „Gambler’s“)","oeffentlich":true,"url":"https://iep.utm.edu/fallacy/","abruf":"2026-10-12"},{"typ":"doi","kurz":"Barnett, A. G.; van der Pols, J. C.; Dobson, A. J. (2005): Regression to the mean: what it is and how to deal with it. International Journal of Epidemiology 34(1), 215–220","oeffentlich":false,"doi":"10.1093/ije/dyh299"},{"typ":"doi","kurz":"Tversky, A.; Kahneman, D. (1971): Belief in the law of small numbers. Psychological Bulletin 76(2), 105–110","oeffentlich":false,"doi":"10.1037/h0031322"}],"thema":"Gesundheit","pruefung":{"lauf":"quiz-audit-v3","modell":"claude-sonnet-5-5","datum":"2026-10-13","urteil":"ok","pruefsumme":"5807eaa304926871"}},{"id":"qx-b2-057","clusterId":"B","werkstueckRef":"B.31","stufe":1,"question":"Welche Beobachtung würde die Behauptung der Kollegin am stärksten widerlegen?","options":["Die Jugendlichen bevorzugen beim Verteilen die eigene Gruppe, obwohl es weder Wettkampf noch Streit gab und die Einteilung zufällig war.","Die Jugendlichen bevorzugen die eigene Gruppe stärker, nachdem sie in einem Wettkampf um einen knappen Preis gegeneinander angetreten sind.","Die Jugendlichen verteilen etwas mehr an Personen, die sie persönlich gut kennen und mögen, ganz gleich in welcher Gruppe diese sind.","Die Jugendlichen verteilen das Geld gleichmäßig auf beide Gruppen, wenn die Einteilung per Münzwurf erfolgt und es weder Wettkampf noch Streit gab."],"correctIndex":0,"explanation":"Die Behauptung sagt: Ohne Konkurrenz und ohne Streitgeschichte entsteht keine Gruppenbevorzugung. Am stärksten widerlegt sie ein Fall, in dem beides fehlt, die Einteilung rein zufällig ist und die eigene Gruppe trotzdem bevorzugt wird; ähnlich war der Versuch von Tajfel mit britischen Schuljungen angelegt (Einteilung angeblich nach Bildgeschmack, tatsächlich zufällig), und in einem Folgeversuch blieb die Bevorzugung auch bei offen per Münzwurf gebildeten Gruppen bestehen, wenn auch schwächer. Die anderen Beobachtungen widerlegen die Behauptung nicht: Ein Wettkampf um einen knappen Preis passt zu ihr. Wer mehr an Menschen gibt, die er persönlich kennt und mag, kann damit einer Beziehung folgen statt der Gruppe; über Konkurrenz und Streit sagt das nichts. Und gleichmäßiges Verteilen ohne Wettkampf und Streit bestätigt die Behauptung, statt sie zu widerlegen.","coreRule":"⚡ Wer behauptet, eine Ursache sei nötig, wird widerlegt durch einen Fall, in dem sie fehlt und die Wirkung trotzdem eintritt. Schon ein bloßes Etikett kann „wir“ gegen „die“ erzeugen.","beleg":"Werkstück B.31 (Eingangsszene); Fn. gl-b-tajfel (Tajfel 1970; Tajfel u. a. 1971; Billig/Tajfel 1973, S. 28 f.); Anmerkung zu gl-b-tajfel (Münzwurf-Bedingung im Folgeversuch)","status":"entwurf","scenario":"Eine Kollegin sagt: „Gruppenbevorzugung entsteht erst, wenn Gruppen um knappe Ressourcen konkurrieren und es eine Vorgeschichte von Streit gibt.“ In einem Versuch werden Jugendliche, die sich aus der Schule kennen, zufällig in zwei Gruppen eingeteilt, etwa per Münzwurf. Sie wissen nicht, wer sonst zu ihrer Gruppe gehört, und verteilen Geld an anonyme Empfänger beider Gruppen.","quote":"","quoteLabel":"","kurz":"Widerlegen lässt sich die Behauptung nur durch einen Fall, in dem Konkurrenz und Streit fehlen und die Gruppenbevorzugung trotzdem auftritt. Beobachtungen, die zu ihr passen oder andere Dinge betreffen, ändern daran nichts.","prueffrage":"Unter welchen Umständen würde die Kollegin selbst gar keine Bevorzugung der eigenen Gruppe erwarten?","rueckmeldung":[{"option":1,"text":"Ein Wettkampf um einen knappen Preis macht Bevorzugung plausibel, genau so, wie die Kollegin es sagt. Die Behauptung nennt Konkurrenz als Voraussetzung, also kann diese Beobachtung sie nicht widerlegen."},{"option":2,"text":"Dass man Menschen bevorzugt, die man kennt und mag, kommt vor. Es zeigt aber eine Beziehung zu einzelnen Personen und nichts über Gruppenbevorzugung ohne Konkurrenz und Streit, und gegen die Behauptung spricht es deshalb nicht."},{"option":3,"text":"Gleichmäßiges Verteilen sieht nach einem Gegenbeispiel zur Behauptung aus. Es entspricht aber genau dem, was die Kollegin erwartet: ohne Wettkampf und Streit keine Bevorzugung. Sie wird damit bestätigt, nicht widerlegt."}],"familie":"korrelation-und-ursache","fertigkeit":"F2","quellen":[{"typ":"url","kurz":"Tajfel, H.; Turner, J. C. (1979): An Integrative Theory of Intergroup Conflict. In: Austin, W. G.; Worchel, S. (Hg.): The Social Psychology of Intergroup Relations (Kopie bei ALNAP)","oeffentlich":true,"url":"https://alnap.org/documents/8612/tajfel-turner-1979-compressed.pdf","seite":"38–39","abruf":"2026-10-12"},{"typ":"doi","kurz":"Billig, M.; Tajfel, H. (1973): Social categorization and similarity in intergroup behaviour. European Journal of Social Psychology 3(1)","oeffentlich":false,"doi":"10.1002/ejsp.2420030103","seite":"27–29, 34, 39"},{"typ":"literatur","kurz":"Tajfel, H. (1970): Experiments in Intergroup Discrimination. Scientific American 223(5)","oeffentlich":false,"seite":"99–102"}],"thema":"Zusammenleben","pruefung":{"lauf":"quiz-audit-v3","modell":"claude-sonnet-5-5","datum":"2026-10-13","urteil":"ok","pruefsumme":"e2e2a29a11c3d2d1"}},{"id":"qx-b2-058","clusterId":"B","werkstueckRef":"B.31","stufe":3,"question":"Ein Kommentator behauptet: „Das Experiment beweist es: Sobald Menschen in ‚wir‘ und ‚die‘ eingeteilt werden, ist der Weg zur Entmenschlichung vorgezeichnet. Wer Gruppen bildet, bekommt am Ende Feindbilder.“ Was ist an diesem Schluss am ehesten fehlerhaft?","options":["Er springt von einer milden Bevorzugung der eigenen Gruppe auf eine extreme Folge, ohne zu zeigen, dass die Einteilung allein diesen Weg zurücklegt.","Er greift die Forschenden persönlich an, statt sich mit den Ergebnissen des Experiments auseinanderzusetzen (Ad-hominem-Argument).","Er hält die Behauptung für richtig, weil die meisten Menschen sie glauben, und prüft sie nicht am Befund (Mehrheitsargument).","Er begründet die Feindbilder mit der Bevorzugung der Gruppe und die Bevorzugung wiederum mit Feindbildern (Zirkelschluss)."],"correctIndex":0,"explanation":"Das Experiment zeigt eine milde, messbare Bevorzugung der eigenen Gruppe bei bloßer, sogar zufälliger Einteilung. Zwischen diesem Befund und der Entmenschlichung, bei der der Fremdgruppe die Menschlichkeit selbst abgesprochen wird, liegt ein weiter Weg, den die bloße Einteilung allein nicht zurücklegt. Den Weg dorthin treibt dieselbe Gruppenbindung unter wachsendem Druck: Bedrohung, Konkurrenz um knappe Ressourcen und eine Führung, die die Distanz zwischen „wir“ und „die“ vergrößert. Zudem lässt sich der Ursprung der Gruppenbindung auch ohne Feindschaft erklären: Eine mögliche Erklärung sieht in ihr eine Gemeinschaft gegenseitigen Vertrauens, die Verbündeten Schutz und geteilte Nahrung brachte – eine Hypothese, kein Messergebnis. Und auch Entmenschlichung ist kein Entweder-oder, sondern hat Stufen von subtil bis offen. Der Kommentator schließt also von einem Anfangsbefund auf ein Endergebnis, ohne die Zwischenstrecke zu belegen. Die anderen Fehler gibt es, sie kommen hier aber nicht vor: Der Kommentator greift niemanden persönlich an, sondern beruft sich auf den Versuch. Er verweist auch nicht darauf, dass viele Menschen es glauben. Und er dreht sich nicht im Kreis, sondern leitet die Feindbilder aus dem Befund ab, nur eben zu weit.","coreRule":"⚡ Wer von einem milden Befund auf eine extreme Folge schließt, muss den Weg dazwischen belegen: Wir-Gefühl ist noch keine Feindschaft.","beleg":"Werkstück B.31 (Kontext & Tiefe; Kipppunkt); Fn. gl-b-brewer (Brewer 1999, S. 432–434); Fn. gl-b-kteily (Kteily u. a. 2015)","status":"entwurf","scenario":"In einem Experiment werden Jugendliche per Zufall in zwei Gruppen eingeteilt, angeblich nach ihrem Bildgeschmack. Sie verteilen anschließend kleine Geldbeträge an anonyme Mitglieder beider Gruppen und bevorzugen dabei systematisch die eigene Gruppe, teils sogar auf Kosten des absoluten Gewinns der eigenen Gruppe, solange der Abstand zur anderen Gruppe wächst.","kurz":"Gemessen wurde nur eine milde Bevorzugung der eigenen Gruppe. Daraus auf Entmenschlichung zu schließen überspringt die lange Zwischenstrecke, die erst Bedrohung, Konkurrenz und Führung zurücklegen, nicht die bloße Einteilung.","prueffrage":"Was taten die Jugendlichen im Experiment gegenüber der anderen Gruppe, und was davon wurde gemessen?","rueckmeldung":[{"option":1,"text":"Ein Ad-hominem-Argument braucht einen Angriff auf Personen, hier gegen die Forschenden. Der Kommentator beruft sich aber gerade auf den Versuch. Der Mangel liegt darin, wie weit er vom Befund aus schließt, nicht in einem Angriff auf jemanden."},{"option":2,"text":"Der Ton „Das Experiment beweist es“ erinnert an Berufung auf Verbreitung oder Autorität. Der Kommentator verweist aber nicht darauf, dass viele Menschen es glauben, sondern auf den Versuch selbst. Gerade dessen Reichweite überdehnt er."},{"option":3,"text":"Bevorzugung der eigenen Gruppe und Feindbilder gehören thematisch eng zusammen, daher kann man eine wechselseitige Begründung vermuten. Der Kommentator leitet aber in einer Richtung ab: vom Befund zu den Feindbildern, nur eben zu weit. Ein Kreis liegt nicht vor."}],"familie":"dammbruch-pruefen","fertigkeit":"F2","quellen":[{"typ":"url","kurz":"Brewer, M. B. (1999): The Psychology of Prejudice: Ingroup Love or Outgroup Hate? Journal of Social Issues 55(3) (inoffizielle Kopie auf Server des Bard College)","oeffentlich":true,"url":"https://bcsh.bard.edu/files/2019/06/Brewer-ingroup-love-or-outgroup-hate.pdf","seite":"431–437","abruf":"2026-10-12"},{"typ":"doi","kurz":"Kteily, N.; Bruneau, E.; Waytz, A.; Cotterill, S. (2015): The Ascent of Man: Theoretical and Empirical Evidence for Blatant Dehumanization. JPSP 109(5)","oeffentlich":false,"doi":"10.1037/pspp0000048"},{"typ":"url","kurz":"Tajfel, H.; Turner, J. C. (1979): An Integrative Theory of Intergroup Conflict (Kopie bei ALNAP)","oeffentlich":true,"url":"https://alnap.org/documents/8612/tajfel-turner-1979-compressed.pdf","seite":"38–39","abruf":"2026-10-12"}],"thema":"Zusammenleben","pruefung":{"lauf":"quiz-audit-v3","modell":"claude-sonnet-5-5","datum":"2026-10-13","urteil":"ok","pruefsumme":"46884cdbedc8ea30"}},{"id":"qx-b2-059","clusterId":"B","werkstueckRef":"B.31","stufe":4,"question":"Was zeigt diese Beobachtung am ehesten über den Charakter der Debatte?","scenario":"In einer Debatte über eine Klimamaßnahme werden Abweichler in der eigenen Gruppe heftiger angegriffen als die eigentliche Gegenseite. Die Gegenseite wird nur noch als einheitliche Masse beschrieben.","options":["Die Gruppe nimmt Widerspruch auch im Inneren ernst, und die Debatte ist dadurch sachlicher geworden.","Die Gruppe prüft Abweichler strenger als externe Gegner, weil ihr die Sache besonders wichtig ist.","Die Gruppengrenze ist wichtiger geworden als die Sache selbst, und die Gegenseite gilt nur noch als Masse.","Die Gegenseite hat in der Sache recht, weil Gruppen auf unbequeme Wahrheiten besonders heftig reagieren."],"correctIndex":2,"explanation":"Wenn Abweichler in der eigenen Gruppe härter angegriffen werden als die eigentliche Gegenseite, geht es erkennbar nicht mehr um die Klimamaßnahme, sondern um Loyalität: Wer abweicht, stellt die Zugehörigkeit infrage. Dazu passt, dass die Gegenseite nur noch als einheitliche Masse ohne eigene Stimmen beschrieben wird. Das ist ein typisches Zeichen dafür, dass die Gruppenzugehörigkeit die Sachfrage überlagert: Wichtiger als die Argumente wird, was die Zugehörigkeit zur eigenen Gruppe signalisiert. Eine einfache Prüffrage: Würdest du dasselbe Argument genauso bewerten, wenn es aus der eigenen Gruppe käme, und ihm genauso widersprechen, wenn ein Mitglied deiner Gruppe es verträte?","coreRule":"⚡ Wo Zustimmung vor allem Zugehörigkeit signalisiert, verliert das Argument sein Gewicht.","quote":"","quoteLabel":"","beleg":"Werkstück B.31 (Red Flags; Anwendung: Politische Polarisierung; Anti-Denkmuster)","status":"entwurf","kurz":"Wer Abweichler härter angreift als die Gegenseite und diese nur noch als Masse beschreibt, kämpft erkennbar um Zugehörigkeit statt um die Klimamaßnahme. Der naheliegende Fehler ist, Härte für besondere Sachstrenge zu halten.","prueffrage":"Wen trifft die schärfste Kritik: Menschen mit anderen Argumenten oder Menschen aus den eigenen Reihen?","rueckmeldung":[{"option":0,"text":"Kritik von innen kann ein Zeichen offener Debatte sein. Hier werden Abweichler aber heftig angegriffen statt angehört, und die Gegenseite kommt nur als Masse vor. Das spricht nicht für mehr Sachlichkeit."},{"option":1,"text":"Wem eine Sache wichtig ist, der prüft genau, das wirkt plausibel. Doch wer wirklich die Sache prüft, nimmt sich die Gegenseite mindestens so genau vor wie Abweichler und beschreibt sie nicht nur als einheitliche Masse."},{"option":3,"text":"Heftige Reaktionen sagen etwas über die Gruppe, nicht darüber, wer in der Sache recht hat. Zudem treffen sie hier vor allem Abweichler aus den eigenen Reihen und nicht die Gegenseite."}],"familie":"wir-und-die-erkennen","fertigkeit":"F2","quellen":[{"typ":"url","kurz":"Ditto, P. H. u. a. (2019): At Least Bias Is Bipartisan: A Meta-Analytic Comparison of Partisan Bias in Liberals and Conservatives. Perspectives on Psychological Science 14(2) (Kopie auf der Seite des Ditto-Labors, UC Irvine)","oeffentlich":true,"url":"https://sites.uci.edu/peterdittolab/files/2018/06/Ditto-et-al.-2018-At-Least-Bias-is-Bipartisan-A-Meta-Analytic-Comparison-of-Partisan-Bias-in-Liberals-Conservatives.pdf","abruf":"2026-10-12"},{"typ":"url","kurz":"Castano, E.; Yzerbyt, V. Y. (1998): The highs and lows of group homogeneity. Behavioural Processes 42 (Kopie auf der Seite von V. Yzerbyt, UCLouvain)","oeffentlich":true,"url":"https://perso.uclouvain.be/vincent.yzerbyt/Castano%20&%20Yzerbyt%20BP%201998.pdf","abruf":"2026-10-12"}],"thema":"Zusammenleben","pruefung":{"lauf":"quiz-audit-v3","modell":"claude-sonnet-5-5","datum":"2026-10-13","urteil":"ok","pruefsumme":"3b5b3cae3558bba0"}},{"id":"qx-b2-060","clusterId":"B","werkstueckRef":"B.31","stufe":2,"question":"Welche Erklärung für diese Wahl ist am sparsamsten und erklärt zugleich, warum die Verteilung mit weniger Punkten für die eigene Gruppe gewählt wird?","scenario":"Zwei Gruppen von Schülern wurden eben erst zufällig eingeteilt, ohne Wettkampf und ohne vorherigen Streit; niemand weiß, wer sonst zur eigenen Gruppe gehört. Nun dürfen sie Punkte an anonyme Empfänger beider Gruppen verteilen, die später in echtes Geld umgetauscht werden. Viele wählen eine Verteilung, bei der die eigene Gruppe 7 Punkte und die andere 1 Punkt bekommt, statt einer Verteilung mit 10 Punkten für die eigene und 12 für die andere Gruppe. Dabei verteilen sie nie an sich selbst.","options":["Die Gruppe ist ihnen schon so wichtig, dass sie vor allem den Abstand zur anderen Gruppe vergrößern wollen, auch wenn die eigene Gruppe dabei absolut weniger erhält.","Sie wollen den Gewinn der eigenen Gruppe so groß wie möglich machen, weil mehr Punkte später auch mehr Geld bedeuten (Gewinnmaximierung).","Sie sehen in der anderen Gruppe einen Konkurrenten um knappe Mittel und wollen ihr zuvorkommen, bevor sie selbst benachteiligt werden (Gruppenkonflikt).","Sie folgen einer Reziprozitätsnorm: Wer der eigenen Gruppe viel gibt, erhält später eine Gegenleistung von deren Mitgliedern."],"correctIndex":0,"explanation":"Wenn jemand die Verteilung mit weniger Punkten für die eigene Gruppe wählt, nur weil der Abstand größer ist, geht es nicht ums Gewinnen, sondern ums Besser-Dastehen. Das passt dazu, dass ein Teil des Selbstwerts an die Gruppe gekoppelt ist: Es genügt nicht, dass es „uns“ gut geht, „wir“ sollen mehr haben als „die“. Dass schon eine zufällige Einteilung ausreicht, ist der Kern des Befunds: Das Gruppenetikett allein genügt, damit der Vergleich mit der anderen Gruppe wichtig wird. Die anderen Erklärungen klingen vernünftig, passen aber nicht zur Wahl: Wer den Gewinn der eigenen Gruppe maximieren wollte, hätte 10 statt 7 Punkte gewählt. Ein Konkurrenzdenken um knappe Mittel setzt einen Wettkampf voraus, den es hier nicht gab. Und Gegenleistung zu erwarten ergibt keinen Sinn, wenn niemand weiß, wer außer ihm selbst zur Gruppe gehört.","coreRule":"⚡ Wenn jemand lieber weniger für alle will, solange „wir“ mehr haben als „die“, geht es nicht um Gewinn, sondern um den Vergleich.","beleg":"Werkstück B.31 (Kernidee; Kontext & Tiefe: Sozialer Vergleich & positive Distinktheit)","status":"entwurf","quote":"","quoteLabel":"","kurz":"Wer 7 zu 1 statt 10 zu 12 wählt, will nicht möglichst viel gewinnen, sondern besser dastehen als die andere Gruppe. Naheliegend wäre Eigennutz, doch der hätte die 10 Punkte gewählt; hier zählt der Abstand.","prueffrage":"Was haben die Schüler in der Verteilung für ihre eigene Gruppe verloren, und was haben sie dafür bekommen?","rueckmeldung":[{"option":1,"text":"Dass aus den Punkten später echtes Geld wird, spricht auf den ersten Blick für Eigennutz. Wer aber den Ertrag der eigenen Gruppe maximieren wollte, hätte die 10 Punkte gewählt statt der 7, und die Gruppe geht hier sogar mit weniger aus der Verteilung."},{"option":2,"text":"Konkurrenz um knappe Mittel erklärt oft Streit zwischen Gruppen. Hier gab es aber weder Wettkampf noch Vorgeschichte, die Gruppen wurden eben erst zufällig gebildet, und niemand muss sich Mittel gegen die andere Seite sichern."},{"option":3,"text":"Gegenseitigkeit kann Verhalten sonst tatsächlich steuern. Eine Gegenleistung setzt aber voraus, dass man weiß, wer sie erbringen soll; hier kennt niemand die anderen Gruppenmitglieder. Und sie würde nicht erklären, warum die eigene Gruppe mit 7 statt 10 Punkten weniger bekommt."}],"familie":"wir-und-die-erkennen","fertigkeit":"F2","quellen":[{"typ":"url","kurz":"Tajfel, H.; Turner, J. C. (1979): An Integrative Theory of Intergroup Conflict (Kopie bei ALNAP)","oeffentlich":true,"url":"https://alnap.org/documents/8612/tajfel-turner-1979-compressed.pdf","seite":"38–42","abruf":"2026-10-12"},{"typ":"literatur","kurz":"Tajfel, H. (1970): Experiments in Intergroup Discrimination. Scientific American 223(5)","oeffentlich":false,"seite":"101–102"}],"thema":"Zusammenleben","pruefung":{"lauf":"quiz-audit-v3","modell":"claude-sonnet-5-5","datum":"2026-10-13","urteil":"korrigieren","pruefsumme":"7017d4da5615f531"}},{"id":"qx-b2-061","clusterId":"B","werkstueckRef":"B.32","stufe":1,"question":"Welche Annahme steckt hinter dieser Einschätzung, und warum ist sie riskant?","options":["Er unterstellt, die fremde Regierung denke und werte wie er selbst, und füllt so die Wissenslücke mit dem eigenen Bild statt mit Wissen über ihre Sicht.","Er unterstellt, wer Atomwaffen bauen könne, wolle sie auch, und verwechselt so Fähigkeit mit Absicht, ohne die Ziele der Regierung zu prüfen.","Er unterstellt, die Haltung der Regierung gelte für jeden einzelnen Bürger des Landes, und übergeht so die Vielfalt der Meinungen im Land.","Er unterstellt, jedes fremde Land sei von Natur aus bedrohlich, und überschätzt so die Gefahr, die von diesem Land ausgeht."],"correctIndex":0,"explanation":"Die Einschätzung beantwortet nicht die Frage, wie die fremde Regierung ihre Lage sieht, sondern eine andere: Was würde ich an ihrer Stelle wollen? Sie stützt sich auf nichts, was von der anderen Seite stammt, weder Äußerungen noch Kenntnis ihrer Lage. Wo Wissen fehlt, setzt man unbemerkt das einzige Modell eines Geistes ein, das man von innen kennt: sich selbst. Das nennt man Spiegelbild-Denken (Mirror-Imaging). So wurde 1977 ein mutmaßliches Atomtestgelände in Südafrika von vielen Analysten abgetan, mit genau diesem Argument. Als Notbehelf lässt sich der Blick in den Spiegel manchmal nicht vermeiden, aber ein solches Urteil verdient wenig Vertrauen. Besser prüft man, ob die andere Seite ihre Lage selbst beschrieben hat, und zieht Menschen hinzu, die sie aus eigener Anschauung kennen. Die anderen Fehler sind real, kommen hier aber nicht vor: Fähigkeit und Absicht zu verwechseln würde zum Schluss führen, das Land wolle die Waffe, der Analyst schließt aber das Gegenteil. Von den Bürgern des Landes ist nirgends die Rede. Und eine Überschätzung der Gefahr zeigt sich nicht, er unterschätzt sie eher.","coreRule":"⚡ Wo Wissen über den anderen fehlt, setzt man sich selbst ein, ohne es zu merken. Frag daher: Weiß ich, wie die andere Seite ihre Lage sieht, oder setze ich nur ein, was ich an ihrer Stelle täte?","beleg":"Werkstück B.32 (Kernidee; Analyse); Fn. gl-b-heuer (Heuer 1999, Psychology of Intelligence Analysis, S. 70)","status":"entwurf","scenario":"Ein Analyst soll einschätzen, ob ein ihm kaum bekannter Staat Atomwaffen anstrebt. Er schreibt: „Das Land hat keinen Feind, gegen den sich eine Atomwaffe wirksam einsetzen ließe. Also will es keine. An seiner Stelle würde ich auch darauf verzichten.“ Niemand im Team kennt das Land aus eigener Anschauung, und es liegen keine Äußerungen der dortigen Regierung vor.","kurz":"Der Analyst fragt nicht, wie die fremde Regierung ihre Lage sieht, sondern was er an ihrer Stelle wollte. Wo Wissen fehlt, setzt man unbemerkt das eigene Denken ein, und ein Urteil, das nur darauf ruht, verdient wenig Vertrauen.","prueffrage":"Was von dem, worauf sich die Einschätzung stützt, stammt tatsächlich von der Regierung des Landes selbst?","rueckmeldung":[{"option":1,"text":"Hier ginge es um Fähigkeit und Absicht, aber der Analyst folgert gerade nicht, das Land wolle die Waffe, sondern das Gegenteil. Auch die Fähigkeit des Landes kommt im Text nicht vor. Er unterstellt nicht Wollen aus Können, sondern setzt sein eigenes Wollen ein."},{"option":2,"text":"Von den Bürgern oder von Meinungsvielfalt im Land ist im Szenario nirgends die Rede, es geht um die Einschätzung der Regierung. Der Analyst überträgt nicht eine Haltung auf alle Einwohner, sondern seine eigene Sicht auf die fremde Regierung."},{"option":3,"text":"Von einem Bedrohungsbild gegenüber fremden Ländern steht nichts im Text. Der Analyst überschätzt die Gefahr auch nicht, er schließt Absicht aus und unterschätzt sie damit eher. Sein Fehler liegt woanders, nämlich im Maßstab, den er anlegt."}],"familie":"aus-ihrer-lage-urteilen","fertigkeit":"F2","quellen":[{"typ":"url","kurz":"Heuer, R. J. (1999): Psychology of Intelligence Analysis. CIA, Center for the Study of Intelligence","oeffentlich":true,"url":"https://www.cia.gov/resources/csi/static/Pyschology-of-Intelligence-Analysis.pdf","seite":"70–71, 181","abruf":"2026-10-12"}],"thema":"Zusammenleben","pruefung":{"lauf":"quiz-audit-v3","modell":"claude-sonnet-5-5","datum":"2026-10-13","urteil":"korrigieren","pruefsumme":"2b0fa0641fb9ddd6"}},{"id":"qx-b2-062","clusterId":"B","werkstueckRef":"B.32","stufe":3,"question":"Was ist der entscheidende Fehler an diesem Vorgehen?","options":["Die Annahme wurde als Behelf für eine Wissenslücke eingeführt, ist aber inzwischen als gesicherte Tatsache in eine folgenreiche Entscheidung eingegangen.","Die Gruppe hat nur Hinweise berücksichtigt, die ihre Annahme stützen, und Gegenhinweise ausgeblendet, sodass ein Bestätigungsfehler die Entscheidung prägt.","Es fehlt eine Abschätzung der Nebenfolgen von Sanktionen, die man vor jeder derart folgenreichen Entscheidung gründlich durchführen sollte.","Man hat sich auf die bloße Autorität des Beraters verlassen, statt seine Aussage zu prüfen, sodass ein Autoritätsargument die Entscheidung trägt."],"correctIndex":0,"explanation":"Die eigene Sicht ist das einzige Modell eines Geistes, das wir von innen kennen. Als vorläufiger Notbehelf bei fehlendem Wissen ist sie kaum zu vermeiden, solange allen klar bleibt, dass es nur eine Vermutung ist. Der Fehler liegt im Wechsel von der Vermutung zur Gewissheit: Aus „So würden wir handeln“ wurde „So wird sie handeln, alles andere wäre unvernünftig“, und das Wort „unvernünftig“ misst das Gegenüber an den eigenen Maßstäben. Wo niemand die andere Seite kennt, trägt diese Annahme allein keine folgenreiche Entscheidung. Dann hilft es, Fachleute hinzuzuziehen, die das Land kennen, oder die andere Seite mit ihren eigenen Worten zu Wort kommen zu lassen. Die anderen Antworten nennen für sich sinnvolle Warnungen, passen aber nicht auf diesen Fall: Es wurden gar keine Belege einseitig ausgewählt, man wusste ja nach eigener Aussage wenig. Von Nebenfolgen ist im Szenario keine Rede. Und der Berater selbst hatte seine Annahme ausdrücklich als vorläufig bezeichnet, den Wechsel zur Gewissheit vollzog erst der Entwurf.","coreRule":"⚡ Ein Spiegel ist als Notbehelf erlaubt, solange du weißt, dass du in einen Spiegel blickst.","beleg":"Werkstück B.32 (Adaptives Talent; Kipppunkt; Anwendung & Relevanz: Fachleute von außen); Fn. gl-b-heuer (Heuer 1999, S. 70 f. und 181)","status":"entwurf","scenario":"In einer Lagebesprechung sagt ein Berater: „Über die Absichten der Nachbarregierung wissen wir wenig. Also nehmen wir vorläufig an, sie handelt so, wie wir es an ihrer Stelle täten.“ Drei Wochen später steht im Entwurf einer Sanktionsentscheidung als Ausgangslage: „Die Nachbarregierung wird ihre Truppen abziehen, denn alles andere wäre unvernünftig.“ Niemand im Raum kennt das Land aus eigener Anschauung.","kurz":"Aus der vorläufigen Vermutung „So würden wir handeln“ wurde im Entwurf eine Tatsache, und „unvernünftig“ misst das Gegenüber an den eigenen Maßstäben. Das trägt keine folgenreiche Entscheidung, solange niemand das Land kennt.","prueffrage":"Welche neuen Erkenntnisse über das Nachbarland liegen zwischen der Lagebesprechung und dem Entwurf drei Wochen später?","rueckmeldung":[{"option":1,"text":"Hier wurden keine Belege einseitig ausgewählt, denn nach eigener Aussage wusste man ja kaum etwas. Ein Bestätigungsfehler braucht Hinweise, die man herauspickt. Das Problem liegt in der Annahme selbst, die zur Gewissheit wurde."},{"option":2,"text":"Bei Sanktionen lohnt sich eine Abschätzung der Nebenfolgen tatsächlich. Davon ist hier aber nicht die Rede, und selbst eine gründliche Abschätzung ändert nichts an der brüchigen Ausgangslage, auf der die Entscheidung ruht."},{"option":3,"text":"Der Berater hat seine Annahme selbst ausdrücklich als vorläufig bezeichnet und sich also nicht auf Autorität berufen. Den Sprung zur Gewissheit hat erst der Entwurf vollzogen, drei Wochen später und ohne neue Erkenntnisse."}],"familie":"aus-ihrer-lage-urteilen","fertigkeit":"F2","quellen":[{"typ":"url","kurz":"Heuer, R. J. (1999): Psychology of Intelligence Analysis. CIA, Center for the Study of Intelligence","oeffentlich":true,"url":"https://www.cia.gov/resources/csi/static/Pyschology-of-Intelligence-Analysis.pdf","seite":"70–71, 181","abruf":"2026-10-12"}],"thema":"Zusammenleben","pruefung":{"lauf":"quiz-audit-v3","modell":"claude-sonnet-5-5","datum":"2026-10-13","urteil":"ok","pruefsumme":"30fb4b98ecf4afcc"}},{"id":"qx-b2-063","clusterId":"B","werkstueckRef":"B.32","stufe":4,"question":"Was ist die klügste Reaktion auf diesen Satz in einer Lageanalyse?","scenario":"In einer Lageanalyse zu einem fremden Land steht: „Das Vorgehen dieser Regierung ist völlig irrational und gegen ihre eigenen Interessen.“ Keiner der Autoren hat das Land je besucht, und die Regierung selbst kommt in der Analyse nicht zu Wort.","options":["Den Satz als Hinweis nehmen, dass in der Regierung Gruppendenken herrscht, in dem Abweichler unterdrückt werden und Fehlentscheidungen entstehen.","Den Satz als Formulierungsfrage nehmen und das wertende Wort „irrational“ durch einen neutraleren Ausdruck ersetzen, ohne die Einschätzung selbst zu ändern.","Den Satz als Behauptung nehmen, die man durch weitere Beispiele für das Verhalten der Regierung stützen muss, damit sie belastbar wird.","Den Satz als Warnzeichen nehmen, dass womöglich eigene Werte und Denkrahmen übertragen wurden, und prüfen, wie die Regierung ihre Lage selbst sieht."],"correctIndex":3,"explanation":"Wenn das Verhalten einer fremden Regierung „irrational“ oder „gegen ihre eigenen Interessen“ wirkt, liegt der Fehler oft beim Beobachter: Er hat die eigenen Werte und Denkrahmen auf sie übertragen, statt die Logik der Lage so zu verstehen, wie sie sich ihr selbst darstellt. Wer nicht weiß, wie das Gegenüber denkt, setzt meist unbemerkt das einzige Modell eines Geistes ein, das er von innen kennt: sich selbst. Dass die Analyse keine Selbstauskunft der Regierung enthält und niemand das Land kennt, verstärkt den Verdacht. Das Etikett „irrational“ beendet die Erklärung, wo sie beginnen sollte. Die bessere Frage lautet: Weiß ich, wie die andere Seite ihre Lage sieht, oder setze ich nur ein, was ich an ihrer Stelle täte? Reden, Interviews und Programme der Regierung selbst sowie Fachleute, die das Land aus eigener Anschauung kennen, prüfen das. Die anderen Gedanken klingen vernünftig, passen aber nicht: Gruppendenken kann vorkommen, doch über das Innenleben der Regierung sagt der Satz nichts, es wäre eine unbelegte Zusatzannahme. Ein neutraleres Wort ändert nur den Ton, nicht den Denkfehler dahinter. Und weitere Beispiele für das Verhalten zeigen nur, was die Regierung tut, nicht, warum sie es aus ihrer Sicht tut.","coreRule":"⚡ „Irrational“ sagt oft mehr über den Beobachter als über den Beobachteten.","quote":"","quoteLabel":"","beleg":"Werkstück B.32 (Analyse; Red Flags; Anti-Denkmuster); Fn. gl-b-heuer (Heuer 1999, S. 33)","status":"entwurf","kurz":"Wer ein fremdes Handeln „irrational“ nennt, hat oft nur die eigenen Werte und Denkrahmen übertragen. Weil niemand das Land kennt und die Regierung nicht zu Wort kommt, sollte man erst klären, wie sie ihre Lage selbst sieht.","prueffrage":"Auf welchen Quellen beruht das Urteil „irrational“, und wer von den Autoren war je in diesem Land?","rueckmeldung":[{"option":0,"text":"Gruppendenken kommt tatsächlich vor und kann Fehlentscheidungen erklären. Der Satz sagt aber nichts über das Innenleben der Regierung; das wäre eine unbelegte Zusatzannahme, die ein Etikett nur durch ein anderes ersetzt."},{"option":1,"text":"Wertende Wörter in einer Analyse sind tatsächlich ein Problem, und ein sachlicherer Ausdruck liest sich besser. Er ändert aber nur den Ton: Die ungeprüfte Einschätzung dahinter bliebe dieselbe."},{"option":2,"text":"Mehr Belege für das Verhalten machen die Beschreibung genauer, und das ist nützlich. Sie zeigen aber nur, was die Regierung tut, nicht, warum sie es aus ihrer Sicht tut, und genau dort liegt die Lücke."}],"familie":"aus-ihrer-lage-urteilen","fertigkeit":"F2","quellen":[{"typ":"url","kurz":"Heuer, R. J. (1999): Psychology of Intelligence Analysis. CIA, Center for the Study of Intelligence","oeffentlich":true,"url":"https://www.cia.gov/resources/csi/static/Pyschology-of-Intelligence-Analysis.pdf","seite":"33, 70, 181","abruf":"2026-10-12"}],"thema":"Zusammenleben","pruefung":{"lauf":"quiz-audit-v3","modell":"claude-sonnet-5-5","datum":"2026-10-13","urteil":"ok","pruefsumme":"eac429cc6c342abd"}},{"id":"qx-b2-064","clusterId":"B","werkstueckRef":"B.32","stufe":2,"question":"Was ist an dieser Schlussfolgerung fehlerhaft, und was wäre der nächste sinnvolle Schritt?","scenario":"In einer Verhandlung stellt der andere Verband plötzlich eine Forderung, die deinem Team völlig unverständlich vorkommt. Eine Kollegin sagt: „Ich hätte an seiner Stelle nie so etwas verlangt. Er muss also bluffen und will uns nur unter Druck setzen.“ Ihr habt nie mit jemandem aus seinem Verband gesprochen, und in euren Unterlagen steht nichts darüber, wie er die eigene Lage beschreibt.","options":["Sie setzt das eigene Denken an die Stelle seines Denkens; sinnvoll wäre, zuerst herauszufinden, wie er seine eigene Lage und seine Ziele selbst beschreibt.","Sie sucht nur Hinweise, die die Vermutung stützen; sinnvoll wäre, die Vermutung als Hypothese zu formulieren und dafür Belege zu sammeln.","Sie hält die eigenen Ziele für moralisch besser als seine; sinnvoll wäre, die eigenen Ziele offen und ausführlich zu begründen.","Sie nimmt an, die Wahrheit liege in der Mitte zwischen beiden Positionen; sinnvoll wäre, sofort einen Kompromiss anzubieten."],"correctIndex":0,"explanation":"Die Kollegin beantwortet nicht die Frage, wie der andere seine Lage sieht, sondern eine andere: was sie selbst an seiner Stelle wollen würde. Das ist Spiegelbild-Denken. Die Frage „Warum würde ich so etwas tun?“ liefert eine Antwort über einen selbst, nicht über den anderen. Sie füllt eine Wissenslücke mit dem einzigen Modell eines Geistes, das sie von innen kennt: ihrem eigenen. Gerade weil niemand im Team die andere Seite aus eigener Anschauung kennt und ihre Sicht in den Unterlagen nirgends mit eigenen Worten vorkommt, ist die Schlussfolgerung „Bluff“ nur eine Vermutung und sollte nicht als Tatsache in die Verhandlung eingehen. Der nächste Schritt ist, die Sicht des anderen zu klären: über seine eigenen Worte, etwa eine Rede, ein Interview oder eine Beschreibung seiner Lage, und über Menschen, die seine Seite aus eigener Anschauung kennen. Mit dem Symmetrie-Trugschluss ist das nicht zu verwechseln: Dort liegt der Fehler in der Annahme, die Wahrheit liege in der Mitte zwischen zwei Positionen; hier darin, dass der andere als Spiegelbild von einem selbst gesehen wird. Ein sofortiges Kompromissangebot würde deshalb am eigentlichen Fehler vorbeigehen.","coreRule":"⚡ „Was würde ich tun?“ ist eine Frage über dich, nicht über den anderen.","beleg":"Werkstück B.32 (Anwendung: Verhandlung & Alltag; Anti-Denkmuster)","status":"entwurf","kurz":"Die Kollegin beantwortet nicht, wie der andere seine Lage sieht, sondern was sie selbst an seiner Stelle wollen würde. „Bluff“ ist damit nur eine Vermutung. Sinnvoll ist, zuerst seine eigene Sicht zu klären.","prueffrage":"Was hat der andere Verband selbst über seine Forderung gesagt, und wer im Team hat je mit jemandem von dort gesprochen?","rueckmeldung":[{"option":1,"text":"Dass „Bluff“ nur eine Vermutung ist, stimmt. Doch die Kollegin sucht gar keine Hinweise, sie schließt von sich auf ihn; und Belege nur für die eigene Vermutung zu sammeln, klärt nicht, wie er seine Lage sieht."},{"option":2,"text":"Die eigenen Ziele offen zu begründen, ist nützlich. Von einer moralischen Wertung ist in der Aussage aber gar nicht die Rede, und die Begründung klärt nichts darüber, wie der andere seine Lage sieht."},{"option":3,"text":"Ein Kompromiss klingt vernünftig, wenn zwei Positionen aufeinandertreffen. Hier fehlt aber erst das Wissen darüber, was der andere will. Der Fehler liegt im Blick auf ihn als Spiegelbild, nicht in einer Mitte-Annahme."}],"familie":"aus-ihrer-lage-urteilen","fertigkeit":"F2","quellen":[{"typ":"url","kurz":"Heuer, R. J. (1999): Psychology of Intelligence Analysis. CIA, Center for the Study of Intelligence","oeffentlich":true,"url":"https://www.cia.gov/resources/csi/static/Pyschology-of-Intelligence-Analysis.pdf","seite":"70, 181","abruf":"2026-10-12"}],"thema":"Zusammenleben","pruefung":{"lauf":"quiz-audit-v3","modell":"claude-sonnet-5-5","datum":"2026-10-13","urteil":"ok","pruefsumme":"68677764c81752d1"}}]`);export{t as n,n as t};